export const tdkSentences: Sentence[] = [
  {"id":"s_work_tdk_1_1","chapterId":"ch_work_tdk_1","text":"卷一文上","sortOrder":1},
  {"id":"s_work_tdk_1_2","chapterId":"ch_work_tdk_1","text":"大體第一","sortOrder":2},
  {"id":"s_work_tdk_1_3","chapterId":"ch_work_tdk_1","text":"臣聞《老子》曰：以正理國，以奇用兵，以無事取天下。荀卿曰：人主者，以官人為能者也。匹夫者，以自能為能者也。《傅子》曰：士大夫分職而聽，諸侯之君分土而守，三公總方而議，則天子拱己而正矣。以明其然耶？當尧之時，舜為司徒，契為司馬，禹為司空，後稷為田畴，夔為樂正，垂為工師，伯夷為秩宗，皋陶為理官，益掌驅禽，尧不能為一焉，奚以為君？而九子者為臣，其故何也？尧知九賦之事，使九子各授其事，皆勝其任以成九功，尧遂乘成功以王天下。漢高帝曰：夫運筹策於帏幄之中，决勝於千里之外，吾不如子房；镇國家，撫百姓，給餉饋，不絕糧道，吾不如萧何；連百萬之軍，戰必勝，攻必取，吾不如韓信。三人者，皆人杰也。吾能用之，此吾所以有天下也。","sortOrder":3},
  {"id":"s_work_tdk_1_4","chapterId":"ch_work_tdk_1","text":"故曰：知人者，王道也；知事者，臣道也。無形者，物之君也；無端者，事之本也。鼓不預五音，而為五音主；有道者不為五官之事，而為理事之主。君守其道，官知其事，有自來矣。先王知其如此也，故用非其有如已有之，通肚君道者也。人主不通主道者則不然。自為之則不能任賢，不能任賢則賢者惡之，此功名之所以傷，國家之所以危。湯武一百而盡有夏商之财，以其地封，而天下莫敢不悅服；以其财賞，而天下皆競勸，通乎用非其有也。","sortOrder":4},
  {"id":"s_work_tdk_1_5","chapterId":"ch_work_tdk_1","text":"故稱設宮分職，君之體也；委任责成，君之體也；好謀無倦，君之體也；宽以得眾，君之體也；含垢藏疾，君之體也。君有君人之體，其臣畏而愛之，此帝王所以成業也。","sortOrder":5},
  {"id":"s_work_tdk_1_6","chapterId":"ch_work_tdk_1","text":"任長第二","sortOrder":6},
  {"id":"s_work_tdk_1_7","chapterId":"ch_work_tdk_1","text":"臣聞料才核能，治世之要。自非聖人，誰能兼茲百行，備貫眾理乎？故舜合群司，隨才授位；漢述功臣，三杰異稱。况非此儔，而可備责耶？","sortOrder":7},
  {"id":"s_work_tdk_1_8","chapterId":"ch_work_tdk_1","text":"昔伊尹之興土工也；強脊者使之負土，眇者使之推，傴者使之涂，各有所宜而人性齊矣。管仲曰：升降揖讓，進退閒習，臣不如隰朋，請立以為大行；辟土聚粟，盡地之利，臣不如甯戚，請立以為司田；平原廣牧，車不結轍，士不旋踵，鼓之而三軍之士视死如歸，臣不如王子城父，請立以為大司馬；决獄折中，不殺不辜，不誣不罪，臣不如賓胥無，請立以為大理；犯君顏色，進諫必忠，不避死亡，不撓富貴，臣不如東郭牙；請立以為太諫。君若欲治國強兵，則五子者存焉。若欲霸王，則夷吾在此。黃石公曰：使智使勇，使貪使愚。智者樂立其功，勇者好行其志，貪者决取其利，愚者不愛其死。因其至情而用之，此軍之微權也。《淮南子》曰：天下之物，莫凶於谿毒。然而良医橐而藏之，有所用也。麋之上山也，大章不能跂；及其下也，牧竖能追之，才有脩短也。胡人便於馬，越人便於舟，異形殊類，易事則悖矣。魏武詔曰：進取之士，未必能有行；有行之士，未必能進取。陳平豈篤行，蘇秦豈守信耶？而陳平定漢業、蘇秦濟弱燕者，任其長也。","sortOrder":8},
  {"id":"s_work_tdk_1_9","chapterId":"ch_work_tdk_1","text":"由此觀之，使韓信下帏，仲舒當戎，於公馳說，陆贾聽訟，必無曩時之勋而顯今日之名也。故任長之道，不可不察。","sortOrder":9},
  {"id":"s_work_tdk_1_10","chapterId":"ch_work_tdk_1","text":"品目第三","sortOrder":10},
  {"id":"s_work_tdk_1_11","chapterId":"ch_work_tdk_1","text":"夫天下重器、王者大統，莫不勞聰明於品材，獲安逸於任使。","sortOrder":11},
  {"id":"s_work_tdk_1_12","chapterId":"ch_work_tdk_1","text":"故孔子曰：人有五儀：有庸人，有士人，有君子，有聖，有賢。審此五者，則治道畢矣。所謂庸人者，心不存慎終之規，口不吐訓格之言不擇賢以讬身，不力行以自定，見小闇大而不知所務，從物如流而不知所執，此則庸人也。所謂士人者，心有所定，計有所守，雖不能盡道術之本，必有率也，雖不能遍百善之美，必有處也。是故智不務多，務審其所知；言不務多，務審其所謂；行不務多，務審其所由。智既知之，言既得之，行既由之，則若性命形骸之不可易也。富貴不足以益，貧賤不足以損，此則士人也。所謂君子者，言必忠信而心不忌，仁義在身而色不伐，思慮明而辭不专。篤行信道，自強不息，油然若將可而終不可及者，此君子也。所謂賢者，德不逾閒，行中規繩；言足法於天下而不傷其身，道足化於百姓而不傷於本；富則天下無菀财，施則天下不病貧，此則賢者也。所謂聖者，德合天地，变通無方；刚萬事之終始，协庶品之自然；敷其大道，而遂成情性；明併日月，化行若神；下民不知其德，睹者不識其鄰，此聖者也。","sortOrder":12},
  {"id":"s_work_tdk_1_13","chapterId":"ch_work_tdk_1","text":"《鈴經》曰：德足以懷遠，信足以一異，識足以鑒古，才足以冠世，此則人之英也；法足以成教，行足以修義，仁足以得眾，明足以照下，此則人之俊也；身足以為儀表，智足以决嫌疑，操足以厲貪鄙，信足以懷殊俗，此則人之豪也；守節而無撓，處義而不怒，見嫌不苟免，見利不苟得，此則人之杰也。","sortOrder":13},
  {"id":"s_work_tdk_1_14","chapterId":"ch_work_tdk_1","text":"《家語》曰：昔者明王，必盡知天下良士之名。既知其名，又知其實，然後用天下之爵以尊之，則天下理也。此之謂矣。","sortOrder":14},
  {"id":"s_work_tdk_1_15","chapterId":"ch_work_tdk_1","text":"量才第四","sortOrder":15},
  {"id":"s_work_tdk_1_16","chapterId":"ch_work_tdk_1","text":"夫人才能參差、大小不同，猶升不可以盛斛，滿則弃矣。非其人而使之，安得不殆乎？","sortOrder":16},
  {"id":"s_work_tdk_1_17","chapterId":"ch_work_tdk_1","text":"故伊尹曰：智通於大道，應变而不窮，辯於萬物之情，其言足以調陰陽、正四時、節風雨，如是者舉以為三公；故三公之事，常在於道。不失四時，通於地理，能通不通，能利不利，如是者舉以為九卿；故九卿之事，常在於德。通於人事，行猶舉繩，通於關梁，實於府库，如是者舉以為大夫；故大夫之事，常在於仁。忠正強諫，而無有奸诈，去私立公，而言有法度，如是者舉以為列士；故列士事，常在於義也。故道德仁義定而天下正。","sortOrder":17},
  {"id":"s_work_tdk_1_18","chapterId":"ch_work_tdk_1","text":"太公曰：多言多語，惡口惡舌，終日言惡，寢臥不絕，為眾所憎，為人所疾，此可使要遮闾巷察奸詞禍；權數好事，夜臥早起，雖剧不悔，此妻子之將也；先語察事，勸而與食，實長希言，财物平均，此十人之將也；仞仞截截，垂意肅肅；不用諫言，數行刑戮；刑必見血，不避親戚，此百人之將也。訟辯好勝，嫉賊侵凌，斥人以刑，欲整一眾，此千人之將也。外兒怍怍，言語時出；知人飢飽，習人剧易，此萬人之將也，戰戰栗栗，日慎一日，近賢進謀，使人知節，言語不慢，忠心誠畢，此十萬人之將也。溫良實長，用心無兩，見賢進之，行法不枉，此百萬人之將也，勋勋紛紛，鄰國皆聞；出入豪居，百姓所親；誠信缓大，明於領世；能效成事，又能救败；上知天文，下知地理；四海之內，皆如妻子，此英雄之率，乃天下之主也。","sortOrder":18},
  {"id":"s_work_tdk_1_19","chapterId":"ch_work_tdk_1","text":"經曰：智如源泉，行可以為表儀者，人師也；智可以砥砺，行可以為辅警者，人友也；據法守職而不敢為非者，人吏也；當前快意，一呼再诺者，人隸也。故上主以師為佐，中主以友為佐，下主以吏為佐，危亡之主以隸為佐。欲觀其亡，必由其下。故同明者相見，同聽者相聞，同志者相從，非賢者莫能用賢。故辅佐左右所欲任使者，存亡之機、得失之要。","sortOrder":19},
  {"id":"s_work_tdk_1_20","chapterId":"ch_work_tdk_1","text":"孫武曰：主孰有道。將孰有能？吾以此知勝之謂矣。","sortOrder":20},
  {"id":"s_work_tdk_1_21","chapterId":"ch_work_tdk_1","text":"知人第五","sortOrder":21},
  {"id":"s_work_tdk_1_22","chapterId":"ch_work_tdk_1","text":"臣聞主將之法，務覽英雄之心。然人未易知，知人未易。漢光武聰聽之主也，谬於庞萌；曹孟德知人之哲也，弊於張邈。何則？夫物類者，世之所惑亂也。","sortOrder":22},
  {"id":"s_work_tdk_1_23","chapterId":"ch_work_tdk_1","text":"故曰：宜者類智而非智也，愚者類君而非君子也，戆者類勇而非勇也。亡國之主似智，亡國之臣似忠，幽秀之幼似禾，驪牛之黃似虎，白骨疑象，碔砆類玉。此皆似是而非也。","sortOrder":23},
  {"id":"s_work_tdk_1_24","chapterId":"ch_work_tdk_1","text":"孔子曰：凡人心险於山川，難知於天。天猶有春秋、冬夏、旦暮之期，人者貌深情。故有貌願而益，有長若不肖，有順懁而達，有堅而缦，有缓而焊。太公曰：士有嚴而不肖者，有溫良而為盜者，有外貌恭敬、中心欺慢者，有精精而無情者，有威威而無成者，有如敢斷而不能者，有恍恍惚惚而反忠實者，有倭倭亻々而有效者，有貌勇食而內怯者，有夢夢而反易人者，無使不至，無使不遂。天下所賤，聖人所貴，凡人莫知。惟有大明，乃見其际。此士之外貌而不與中情相應者也。","sortOrder":24},
  {"id":"s_work_tdk_1_25","chapterId":"ch_work_tdk_1","text":"知此士者而有術焉：微察問之，以觀其辭；窮之以辭，以觀其变；與之閒謀，以觀其誠；明白顯問，以觀其德；遠使以财，以觀其廉；试之以色，以觀其貞；告之以難，以觀其勇；醉之以酒，以觀其態。《莊子》曰：遠使之而觀其忠，近使之而觀其敬，煩使之而觀其能，卒然問焉而觀其智，急與之期而觀其信，雜之以處而觀其色。","sortOrder":25},
  {"id":"s_work_tdk_1_26","chapterId":"ch_work_tdk_1","text":"《呂氏春秋》曰：通則觀其所禮，貴則觀其所進，富則觀其所養；聽則觀其所行，近則觀其所好，習則觀其所言，窮則觀其所不愛，賤則觀其所不為；喜之以验其守，樂之以验其僻，怒之以验其節，哀之以验其仁，苦之以验其志。","sortOrder":26},
  {"id":"s_work_tdk_1_27","chapterId":"ch_work_tdk_1","text":"經曰：任寵之人，觀其不驕奢；疏废之人，觀其不背越；榮顯之人，觀其不矜夸；隱約之人，觀其不慑懼。少者觀其恭敬好學而能悌；壮者觀其廉絜務行而勝其私；老者觀其思慎，強其所不足而不逾；父子之閒，觀其慈孝；兄弟之閒，觀其和友；乡党之閒，觀其信義；君臣之閒，觀其忠惠，此之謂觀誠。","sortOrder":27},
  {"id":"s_work_tdk_1_28","chapterId":"ch_work_tdk_1","text":"《人物志》曰：骨植而柔立者，謂之宏毅；宏毅也者，仁之质也。氣清而朗者，謂之文理；文理也者，禮之本也。體端而實者，謂之貞固；貞固也者，信之基也。筋劲而精者，謂之勇敢；勇敢也者，義之决也。色平而畅者，謂之通微；通微也者，智之原也。五质恒性，故謂之五常。故曰：直而不刚則木，劲而不精則力，固而不端則愚，氣而不清則越，畅而不平則荡。然則平陂之质在於神，明暗之實在於精，勇怯之势在於筋，強弱之植在於骨，躁靜之决在於氣，惨怿之情在於色，衰正之形在於儀，態度之動在於，缓急之状在於言，若质素平淡，中睿外朗，筋劲植固，聲清色怿，儀容容直，則純粹之德也。","sortOrder":28},
  {"id":"s_work_tdk_1_29","chapterId":"ch_work_tdk_1","text":"夫人有氣，氣也者，謂誠在其中，必見諸外。故心氣粗訟者，其聲沈散；心氣詳慎者，其聲和節；心氣戾者，其聲粗獷；心氣宽柔者，其聲溫润。信氣中易，義氣時舒，和氣簡略，勇氣壮立，此之謂聽氣。","sortOrder":29},
  {"id":"s_work_tdk_1_30","chapterId":"ch_work_tdk_1","text":"又有察色：察也謂心氣內蓄，皆可以色取之。夫誠智必有難盡之色，誠仁必有可尊之色，誠勇必有難慑之色，誠忠必有可觀之色，誠絜必有難汙之色，誠貞必有可信之色，质色浩然固以安，伪色曼然亂以煩，此之謂察色。","sortOrder":30},
  {"id":"s_work_tdk_1_31","chapterId":"ch_work_tdk_1","text":"又有考志：考志者，謂方與之言以察其志。其氣宽以柔，其色檢而不諂，其禮先人，其言後人，每自見其所不足者，是益人也；若好臨以色，高人以氣，勝人以言，防其所不足，而废其所不能者，是損人也；其貌直而不侮，其言正而不私，不飾其美，不隱其惡，不防其過者，是质人也；若其貌曲媚，其言諛巧，飾其見物，務其小證，以故自說者，是無质人也；喜怒以物而色不作，煩亂以事而志不惑，深导以利而心不移，臨慑以而氣不卑者，是平心固守人也；若喜怒以物而心变易，亂之以事而志不治，示之以利而心遷動，慑之以威而氣恇懼者，是鄙心而假氣人也；設之以物而數决，驚之以卒而屢應，不文而慧者，是有智思之人；若難設以物，難說以言，守一而不知变，固執而不知改，是愚很人也。若屏言而勿顧，自私而不護，非是而強之，是誣嫉人也。此之謂考志。","sortOrder":31},
  {"id":"s_work_tdk_1_32","chapterId":"ch_work_tdk_1","text":"又有测隱：测隱者，若小施而好得，小讓而大爭，言願以為质，伪愛以為忠，尊其行以收其名，此隱於仁賢；若問則不對，詳而不窮，貌示有餘，假道自從，困之以物，窮則讬深，此隱於藝文也；若高言以為廉，矯厲以為勇，內恐外夸，亟而稱說，以诈氣臨人，此隱於廉勇也；若自事君親而好以告人，飾其見物而不誠於內，發名以君親，因名以私身，此隱於忠孝也，此謂测隱矣。","sortOrder":32},
  {"id":"s_work_tdk_1_33","chapterId":"ch_work_tdk_1","text":"夫人言行不類，終始相悖，外內不合，而立假節以感视聽者，曰毀志者也；若飲食以親，货賂以交，損利以合，得其權譽而隱於物者，曰貪鄙者也；若小知而不大解，小能而不大成，規小物而不知大倫，曰華誕者也。","sortOrder":33},
  {"id":"s_work_tdk_1_34","chapterId":"ch_work_tdk_1","text":"又有揆德：揆德者，其言忠行夷，秉志無私，施不求反，情忠而察，貌拙而安者，曰仁心者也；有事变而能治效，窮而能達，措身立功而能遂，曰有知者也；有富貴恭俭，而能威嚴，有禮而不驕，曰有德者也；有隱約而不慑，安樂而不奢，勋勞而不变，喜怒而有度，曰有守者也；有恭敬以事君，恩愛以事親，情乖而不叛，力竭而無违，曰忠孝者也，此之謂揆德。","sortOrder":34},
  {"id":"s_work_tdk_1_35","chapterId":"ch_work_tdk_1","text":"夫聖賢之所美，莫美乎聰明；聰明之所貴，莫貴乎知人。知人識智，則眾得其序，而庶績之業興矣。是故仲尼訓六蔽，以戒偏材之失；思狂狷，以通拘抗之材；疾悾悾而無信，以明為似之難保；察其所安，觀其所由，以知居止之行。率此道也，人焉廋哉？人焉廋哉？","sortOrder":35},
  {"id":"s_work_tdk_1_36","chapterId":"ch_work_tdk_1","text":"察相第六","sortOrder":36},
  {"id":"s_work_tdk_1_37","chapterId":"ch_work_tdk_1","text":"《左傳》曰：周內史叔服如魯，公孫敖聞其能相人也，見其二子焉。叔服曰：穀也食子，難也收子。穀也丰下，必有後於魯國。《漢書》曰：高祖立濞為吳王。已拜，上相之曰：汝面状有反相，漢後五十年，東南有亂，豈非汝耶？天下一家，慎無反。由此觀之，以相察士，其來尚矣。","sortOrder":37},
  {"id":"s_work_tdk_1_38","chapterId":"ch_work_tdk_1","text":"故曰：富貴在於骨法，忧喜在於容色，成败在於决斷，以此參之，萬不失一。","sortOrder":38},
  {"id":"s_work_tdk_1_39","chapterId":"ch_work_tdk_1","text":"經曰：言貴賤者，存乎骨骼；言脩短者，存乎虛實；言性靈者，存乎容止，斯其大體。","sortOrder":39},
  {"id":"s_work_tdk_1_40","chapterId":"ch_work_tdk_1","text":"夫相人先视其面，面有五嶽四渎、五官六府、九州八極、七門二儀。若夫權骨才起、膚色润泽者，九品之候也；辅骨小見、鼻准微端者，八品之候也；辅角成稜仓库皆平者，七品之候也；天中丰隆、印堂端正者，六品之候也；伏犀明峻、辅角丰秾者，五品之候也；邊地高深、福堂廣厚者，四品之候也；犀及司空、龍角纖直者，三品之候也；頭顶高深、龍犀成就者，二品之候也；四仓盡滿、骨角俱明者，一品之候也。似龍者為文吏，似虎者為將軍，似牛者為宰辅，似馬者為武吏，似者為清官、為方伯。天中主貴、氣平滿者，宜官祿也。天庭主上公大丞相之氣；司空主天宮，亦三公之氣；中正主群寮之氣，平品人物之司也；印堂主天下印授，掌符印之官也。山根平美、及有奇骨伏起，為婚連帝室，公主婿也。高廣主方伯之坐，陽尺主州佐之官，武库主兵甲典库之吏，辅角主遠州刺史之官，邊地主邊州之任，日角主公侯之坐，房心主京輦之任，驿馬主急疾之吏，額角主卿寺之位，上卿主帝卿之位，虎眉主大將軍，牛角主王之統師小將，元角主將軍之相。","sortOrder":40},
  {"id":"s_work_tdk_1_41","chapterId":"ch_work_tdk_1","text":"夫人有六賤：頭小身大，為一賤；目無光泽，為二賤；舉動不便，為三賤；鼻不成就，准向前低，為四賤；腳長腰短，為五賤；文策不成、唇細橫長，為六賤，此貴賊乎骨骼者也。","sortOrder":41},
  {"id":"s_work_tdk_1_42","chapterId":"ch_work_tdk_1","text":"夫木主春，生長之行也；火主夏，丰盛之時也；金主秋，收藏之節也；水主冬，萬物伏匿之日也；土主季夏，萬物結實之月也。故曰：凡人美眉目、好指爪者，庶幾好施人也；毛發光泽、唇口如朱者，才能學藝人也；鼻孔小縮、准頭低曲者，慳吝人也；耳孔小、齒瓣細者，邪諂奸佞人也；耳輪厚大、鼻准圓實、乳頭端净、颏颐深廣厚大者，忠信謹厚人也，此性靈存乎容止者也。","sortOrder":42},
  {"id":"s_work_tdk_1_43","chapterId":"ch_work_tdk_1","text":"夫命之與相，猶聲之與饗也。聲動乎幾，响窮乎應，必然理矣。雖雲以言信行、失之宰予，以貌度性，失之子羽，然傳稱無忧而戚、忧必及之，無慶而歡、樂必還之，此心有先動，而神有先知，則色有先見。故扁鵲見桓公，知其將亡；申叔見巫臣，知其竊妻。或躍馬膳珍，或飛而食肉，或早隸晚侯，或初刑末王，銅巖無以飽生，玉饌終乎饿死，則彼度表捕骨，指色摘理，不可誣也，故列雲爾。","sortOrder":43},
  {"id":"s_work_tdk_1_44","chapterId":"ch_work_tdk_1","text":"論士第七","sortOrder":44},
  {"id":"s_work_tdk_1_45","chapterId":"ch_work_tdk_1","text":"臣聞黃石公曰：昔太平之時，諸侯二師，方伯三師，天子六師。世亂則叛逆生，王泽竭則盟誓相罰，德同無以相加，乃攬英雄之心。故曰：得人則興，失士則崩，何以明之？昔齊桓公見小臣稷，一土三往而不得見，從者止之。桓公曰：士之傲爵祿者，固輕其主；其主傲霸王者，亦輕其士。縱夫子傲爵祿，吾庸敢傲霸霸王乎？五往而後得見。《書》曰：能自師者王。何以明之？齊宣王見顏觸，曰：觸前。觸亦曰：王前。議曰：夫觸前慕势，王前為趨士。與使觸為慕势，不若使王為趨士。宣王作色曰：王者貴乎？士者貴乎？對曰：昔秦攻齊，令曰：有有敢去柳下季龚五百步而樵采者，罪，死不赦；令曰：有能得齊王頭者，封萬戶侯，賜金千隘。由是言之，生王之頭，曾不如死士之龚。宣王竟師之。","sortOrder":45},
  {"id":"s_work_tdk_1_46","chapterId":"ch_work_tdk_1","text":"諺曰：浴不必江海，要之去垢，馬不必騏骥，要之善走；士不必賢也，要之知道；女不必貴种，要之貞好。何以明之？淳於髡謂齊宣王曰：古者好馬，王亦好馬；古者好味，王亦好味；古者好色，王亦好色。古者好士，王獨不好。王曰：國無士耳，有則寡人亦悅之。髡曰：古有驊骝騏骥，今之無有，王選於眾，王好馬矣；古有豹象之胎，今之無有，王選於眾，王朔味矣；古有毛嫱西施，今之無有，王選於眾，王好色矣。王必待尧舜禹湯之士，而後好之，則尧舜禹湯之士，亦不好王矣。","sortOrder":46},
  {"id":"s_work_tdk_1_47","chapterId":"ch_work_tdk_1","text":"語曰：琼艘瑤楫，無涉川之用；金弧玉絃，無激矢之能。是以介絜而無政事者，非拨亂之器；儒雅而乏治理者，非翼亮之士。何偶明之？魏無知見陳平於漢王，漢王用之。絳、灌等讒平曰：平盜嫂受金。漢王讓魏無知，無知曰：臣之所言者，能也；陛下所聞者，行也。今有尾生、孝已之行，而無益於勝負之數，陛下假用之乎？今楚、漢相距，臣進奇謀之士，顧其計誠足以利國家耳。盜嫂受金，又安足疑哉？漢王曰：善。","sortOrder":47},
  {"id":"s_work_tdk_1_48","chapterId":"ch_work_tdk_1","text":"黃石公曰：有清白之士者，不可以爵祿得；守節之士，不可以威刑胁。致清白之士，修其禮；致守節之士，修其道。何以明之？郭隗說燕昭王曰：帝者與師處，王者與友處，霸者與臣處，亡國者與厮役處。诎指而事之，北面受學，則百己者至；先趨而後息，先問而後默，則什己者至；人趨己趨，則若己者至；凭幾據杖，眄视指使，則厮役之人至；恣睢奋击，呴藉叱咄，則徒隸之人至矣。此乃古之服道致士者也。","sortOrder":48},
  {"id":"s_work_tdk_1_49","chapterId":"ch_work_tdk_1","text":"黃石公曰：禮者，士之所歸；賞者，士之所死。招其所歸，示其所死，則所求者至矣。何以明之？魏文侯太子击禮田子方，而子方不為禮。太子不悅，謂子方曰：不識貧賤者驕人乎？富貴者驕人乎？子方曰：貧賤者驕人耳，富貴者安敢驕人？人主驕人而亡其國，大夫驕人而亡其家。貧賤者若不得意，納履而去，安往而不得貧賤乎？宋燕相齊，見逐罢歸，謂諸大夫曰：有能與我赴諸侯乎？皆執仗排班，默而不對。燕曰：悲乎！何士大夫易得而難用也？陳饒曰：舉士大夫易得而難用，尹不能用也。君不能用，則有不平之心，是失之於己而责諸人也。燕曰：其說雲何？對曰：三升之稷，不足於士，而君雁鶩有餘粟，是君之過一也；果園梨栗，後宮婦女以相提挃，而士曾不得一嘗，是君之過二也；綾紈綺縠，美麗於堂，從風而弊，士曾不得以為緣，是君之過三也。夫财者，君之所輕；死者，士之所重。君不能行君之所輕，而欲使士致其所重，譬猶鉛刀畜之，幹將用之，不亦難乎？宋燕曰：是燕之過也。","sortOrder":49},
  {"id":"s_work_tdk_1_50","chapterId":"ch_work_tdk_1","text":"語曰：夫人同明者相見，同聽者相聞，德合則未見而相親，聲同則處異而相應。《韓子》曰：趣舍同則相是，趣舍異則相非。何以明之？楚威王問宋玉曰：先生其有遺行欤？何士人眾庶不譽之甚？宋玉曰：夫鳥有鳳而魚有鯨，鳳凰上击九萬里，翱翔乎窈冥之上。夫蕃篱之鷃，豈能與料天地之高哉？鯨魚朝發於崑崙之墟，暮宿於孟津，夫尺泽之鲵，豈能與量江海之大哉？故年獨鳥有鳳而魚有鯨，士亦有之。夫聖人瑰琦意行，超然獨處，夫世俗之民，又安知臣之所為哉？","sortOrder":50},
  {"id":"s_work_tdk_1_51","chapterId":"ch_work_tdk_1","text":"語曰：知人未易，人未易知。何以明之？汗明說春申君，春申君悅之。汗明-欲談，春申君曰：仆已知先生意矣。汗明曰：未審君之聖與尧？春申君曰：臣何足以當尧？汗明曰：然則君料臣孰與舜？春申君曰：先生即舜也。汗明曰：不然。臣請為君終言之：君之賢不如尧，臣之能不及舜。夫以賢舜事聖尧，三年而後乃相知也。今君一時而知臣，是君聖於尧而臣賢於舜也。","sortOrder":51},
  {"id":"s_work_tdk_1_52","chapterId":"ch_work_tdk_1","text":"記曰：夫骥唯伯樂獨知之，若時無伯樂之知，即不容其為良馬也。士亦然矣。何以明之？孔子厄於陳蔡，顏回曰：夫子之德至大，天下莫能容。然夫子推而行之，世不我用，有國者之丑也。夫子何病焉？《穀梁傳》曰：子既生，不免乎水火，母之罪也；羁冠成童，不就師傅，父之罪也；就師學問無方，心志不通，身之罪也；心志既通，而名譽不聞，友之罪也；名譽既聞，有司不舉，有司之罪也；有司舉之，王者不用，王者之過也。","sortOrder":52},
  {"id":"s_work_tdk_1_53","chapterId":"ch_work_tdk_1","text":"論曰：行遠道者，假於車馬；濟江海者，因於舟楫。故賢士之立功成名，因於資而假物者。何以明之？公输子能因人主之材木，以構宮室台榭，而不能自為专屋狹庐，材不足也；欧冶能因國君之銅鐵，以為金爐大鍾，而不能為壶鼎盤盂，無其用也；君子能因人主之政朝，以和百姓润眾庶，而不能自饒其家，势不便也。故舜於歷山，恩不及州里；太公屠牛於朝歌，利不及於妻子。及其用也，恩流八荒，德溢四海。故舜假之尧，太公因之周文。君子能修身以假道，不能枉道而假财。","sortOrder":53},
  {"id":"s_work_tdk_1_54","chapterId":"ch_work_tdk_1","text":"語曰：夫有國之主，不可謂舉國無深謀之臣，阖朝無智策之士，在聽察所考精與不精，審與不審耳。何以明之？在昔漢祖，聽聰之主也，納陳恢之謀，則下南陽；不用娄敬之計，則困平城。廣武君者，策謀之士也，韓信納其計，則燕、齊舉；陳餘不用其謀，則泜水败。由此觀之，不可謂事濟者有計策之士，覆败者無深謀之臣。虞公不用宮之奇之謀，滅於晉；仇由不聽赤章之言，仁於智氏；蹇叔之哭，不能濟崤黾之覆；趙括之母，不能救長平之败，此皆人主之聽，不精屎審耳。天下之國，莫不有忠臣謀士也。","sortOrder":54},
  {"id":"s_work_tdk_1_55","chapterId":"ch_work_tdk_1","text":"黃石公曰：羅其英雄，則敵國窮。夫英雄者，國家之幹；士民者，國家之半。後其幹，收其半，則政行而無怨。知人則哲，唯帝難之，慎哉！","sortOrder":55},
  {"id":"s_work_tdk_1_56","chapterId":"ch_work_tdk_1","text":"政體第八","sortOrder":56},
  {"id":"s_work_tdk_1_57","chapterId":"ch_work_tdk_1","text":"古之立帝王者，非以奉養其欲也。為天下之人強掩弱、诈欺愚，故立天子齊一之。謂一人之明，不能遍照海內，故立三公九卿以辅翼之。為絕國殊俗，不得被泽，故立諸侯以教誨之。","sortOrder":57},
  {"id":"s_work_tdk_1_58","chapterId":"ch_work_tdk_1","text":"夫教誨之政，有自來矣。何以言之？《管子》曰：措國於不傾之地，有德也；積於不涸之仓，務五穀也；藏於不竭之府，養桑麻、育六畜也；下令於流水之原，以順人心也；使士於不諍之官，使人各為其所長也；明必死之路，嚴刑罰也；开必得之門，信慶賞也。不為不可成，量人力也；不求不可得，不強人以其所惡也；不處不可久，不偷取取一世宜也。知時者，可立以為長；審於時、察於用，而能備官者，可奉以為君。","sortOrder":58},
  {"id":"s_work_tdk_1_59","chapterId":"ch_work_tdk_1","text":"故曰：明版籍，審什伍，限夫田，定刑名，立君長，急農桑，去末作，敦學敩，核才藝，簡精悍，修武備，嚴禁令，信賞罰，糾遊戲，察苛克，此十五者，雖聖人复起，必此言也。夫欲論長短之变，故立政道以為經焉。","sortOrder":59},
  {"id":"s_work_tdk_1_60","chapterId":"ch_work_tdk_1","text":"《長短經》　唐　趙蕤","sortOrder":60},
  {"id":"s_work_tdk_2_1","chapterId":"ch_work_tdk_2","text":"卷二文中","sortOrder":1},
  {"id":"s_work_tdk_2_2","chapterId":"ch_work_tdk_2","text":"君德第九","sortOrder":2},
  {"id":"s_work_tdk_2_3","chapterId":"ch_work_tdk_2","text":"夫三皇無言，化流四海，故天下無所歸功。帝者體天則地，有言有令，而天下太平。君臣讓功，四海化行，百姓不知其所以然。故使臣不用禮賞功，美而無害。王者製人以道，降心服志，設矩備衰，有察察之政、兵甲之備，而無爭戰血刃之用，天下太平。君無疑於臣，臣無疑於主，國定主安，臣以義退，亦能美而無害。霸主製士以權，結士以信，使士以賞。信衰士疏，賞毀士不為用。","sortOrder":3},
  {"id":"s_work_tdk_2_4","chapterId":"ch_work_tdk_2","text":"故曰：理國之本，刑與德也。二者相須而行，相待而成也。天以陰陽成歲，人以刑德成治，故雖聖人為政，不能偏用也。故任德多，用刑少者，五帝也；刑德相半者，三王也；仗刑多，任德少者，五霸也。純用刑，強而亡者，秦也。","sortOrder":4},
  {"id":"s_work_tdk_2_5","chapterId":"ch_work_tdk_2","text":"或曰：王霸之道，既聞命矣。敢問高、光二帝，皆拔起垅畝，芟夷禍難，遂开王業，高祖豁達以大度，光武謹細於條目，名擅其羔，龍飛鳳翔，故能拨亂庇人，拯斯涂炭。然比大德，方天威，孰為優劣乎？曹植曰：昔漢之初興，高祖因暴秦而起，遂誅強楚，光有天下，功齊湯武，業流後嗣，帝王之元勋，人君之盛事也。然而名不繼德，行不純道，身没之後，崩亡之际，果令凶婦肆酷虐之心，嬖妾被人彘之刑，趙王幽囚，禍殃骨肉，諸呂专權，社稷幾移。凡此諸事，豈非高祖寡計淺慮，以致斯哉？然其枭將畫臣，皆古今之所鮮，有歷代之希睹，彼能任其才而用之，聽其言而察之，故兼天下而有帝位也。世祖體乾靈之休德，禀貞和之純精，蹈黃中之妙理，韜亚聖之懿才；其為德也，聰達而多識，仁智而明恕，重慎而周密，樂施而愛人，值陽九無妄之世，遭炎精厄會之運，殷爾雷發，赫然神舉，奋武略以攘暴，興義兵以扫殘，軍未出於南京，莽已毙於西都；爾乃廟勝而後動，眾計走而後行師，故攻無不陷之壘，戰無奔北之卒，宣仁以和眾，邁德以來遠，故窦融聞聲而影附，馬援一見而叹息。敦睦九族，有唐虞之稱；高尚純朴，有羲皇之素；謙虛納下，有吐握之勞；留心庶事，有日昃之勤，是以計功則業殊，比隆則事異，旌德則靡僣，言行則無秽，量事則势微，論辅則臣弱，卒能握乾圖之休徵，立不刊之遐跡，金石銘其休烈，詩書載其懿動，故曰：光武其優也。","sortOrder":5},
  {"id":"s_work_tdk_2_6","chapterId":"ch_work_tdk_2","text":"或曰：班固稱周雲成康、漢言文景，斯言當乎？虞南曰：成康承文武遺跡，以周召為相，化篤厚之氓，因積仁之德，疾風偃草，未足為喻。至江漢祖开基，日不暇給，亡嬴之弊，猶有存者。太宗體茲仁恕，式遵玄默，涤秦項之酷烈，反軒昊之淳風，幾致刑厝，斯為難矣。若使不溺新垣之說，無取邓通之夢，懍懍乎庶幾近於王道。景帝之擬周康，則尚有慚德。","sortOrder":6},
  {"id":"s_work_tdk_2_7","chapterId":"ch_work_tdk_2","text":"或曰：漢武帝雄才大略，可方前代何主？虞南曰：漢武承六世之業，海內殷富，又有高人之資，故能總攬英雄，駕御豪杰，內興禮樂，外开邊境，製度憲章，煥然可述。方於始皇，則為優矣。至於驕奢暴虐，可以相亚，併功有餘而德不足。","sortOrder":7},
  {"id":"s_work_tdk_2_8","chapterId":"ch_work_tdk_2","text":"昔周成以孺子繼統，而有管蔡四國之变；漢昭幼年即位，亦有燕、蓋、上官逆亂之謀。成王不疑周公，漢昭委任霍光，二主孰為先後？魏文帝曰：周成王體聖考之休氣，禀賢妣之胎誨，周、邵為保傅，呂望為太師，口能言則行人稱辭，足能履則相者导儀，目厭威容之美，耳飽德義之聲，所謂沈渍玄流，而沐浴清風矣；猶有咎悔，聆二叔之謗，使周公東遷，皇天赫怒，顯明厥咎，然後乃寤。不亮周公之聖德，而信金縢之教言，豈不暗哉？夫漢昭父非武王，母非邑薑，養惟蓋主，相則桀光，保無仁孝之质，佐無隆平之治，所謂生於深宮之中，長於婦人之手，然而德與性成，行與禮併，在年二七，早知夙達，發燕書之诈，亮霍光之誠，豈將啟金縢、信國史，而後乃寤哉？使成、昭鈞年而立，易世而化，貿臣而治，換樂而歌，則漢不獨少，周不獨多也。","sortOrder":8},
  {"id":"s_work_tdk_2_9","chapterId":"ch_work_tdk_2","text":"或曰：漢宣帝政事明察，其光武之儔欤？虞南曰：漢宣帝起自闾阎，知人疾苦，是以留心聽政，擢用賢良，原其循名责實，峻法嚴令，蓋流出於申、韓也。古語雲：圖王不成，弊猶足霸；圖霸不成，弊將如何？光武仁義，圖王之君也；宣帝刑名，圖霸之主也。今以相辈，恐非其儔。","sortOrder":9},
  {"id":"s_work_tdk_2_10","chapterId":"ch_work_tdk_2","text":"或曰：漢元帝才藝溫雅，其守文之良主乎？虞南曰：夫人君之才，在乎文德武功而已。文則經天緯地，詞令典策；武則禁暴戢兵，安人和眾，此南面之宏圖也。至於鼓瑟吹箫，和江度曲，斯乃伶官之職，豈天子之所務乎。","sortOrder":10},
  {"id":"s_work_tdk_2_11","chapterId":"ch_work_tdk_2","text":"或曰：觀伪新王莽，謙恭禮讓，豈非一代之名士乎？至作相居尊，驕淫暴虐，何先後相背甚乎？虞南曰：王莽天姿惨酷，诈伪人也。未達之前，徇名求譽；得志之後，矜能傲物。飾情既盡，而本质存焉！愎諫自高，卒不改寤，海內冤酷，為光武之驅除焉。","sortOrder":11},
  {"id":"s_work_tdk_2_12","chapterId":"ch_work_tdk_2","text":"夏少康、漢光武皆中興之君，孰者為最？虞南曰：此二帝皆興复先緒，光啟王業，其名則同，其實則異。何者？光武之世，藉思亂之民，誅殘賊之莽，取亂侮亡、為功差易。至如少康，則夏氏之滅已二代矣，藐然遺體，身在胎孕，母氏逃亡，生於他國，不及過庭之訓，曾無強近之親，遭離亂之難，庇身非所，而能崎嶇於丧亂之閒，遂成配天之業。中興之君，斯為稱首。","sortOrder":12},
  {"id":"s_work_tdk_2_13","chapterId":"ch_work_tdk_2","text":"後漢衰亂，由於桓、靈二主，凶德誰則為甚？虞南曰：桓帝赫然奋怒，誅滅梁冀，有刚斷之節焉，然閹人擅命，党錮事起，中平亂階，始於桓帝。古語曰：天下嗷嗷，新主之資也。靈帝承疲民之後，易為善政，黎庶傾耳，鹹冀中興，而帝袭彼覆車，毒逾前辈。傾覆宗社，職帝之由，天年厭世，為幸多矣。","sortOrder":13},
  {"id":"s_work_tdk_2_14","chapterId":"ch_work_tdk_2","text":"自炎精不競，宇縣分崩，曹孟德挟天子而令諸侯，劉玄德凭蜀之阻，孫仲謀負江淮之固，三分天下，鼎足而立，皆肇开王業、光啟霸圖。三方之君，孰有優劣？虞南曰：曹公兵機智算，殆難與敵，故能肇跡开基，居中作相，實有英雄之才矣；然譎诡不常，雄猜多忌，至於殺伏後、鸩荀彧、誅孔融、戮崔琰，娄生毙於一言，桓劭勞於下拜，弃德任刑，其虐已甚，坐論西伯，實非其人；許邵所謂治世之能臣、亂世之奸雄，斯言為當。劉公待劉璋以賓禮，委諸葛而不疑，人君之德，於斯為美；彼孔明者，命世之奇才，伊呂之儔匹，臣主同心，魚水為譬，但以國小兵弱，斗絕一隅，支對二方，抗衡上國；若使與曹公易地而處，騁其長算，肆關、張之武，盡諸葛之文，則霸王之業成矣。孫主因厥兄之資，用前朝之佐，介以天险，仅得自存，比於二人，理弗能逮。","sortOrder":14},
  {"id":"s_work_tdk_2_15","chapterId":"ch_work_tdk_2","text":"晉宣帝雄謀妙算，諸葛亮冠世奇才，誰為優劣？虞南曰：宣帝起自書生，參佐帝業，濟世危難，克清王道，文武之略，實有可稱；而多杖陰謀，弗由仁義，猜忍诡伏，盈諸襟抱；至如示谬言於李勝，委鞫獄於何晏，愧心負理，君子不為。以此伪情，行之萬物，若使力均势敵，俱會中原，以仲達之奸謀，當孔明之節製，恐非儔也。","sortOrder":15},
  {"id":"s_work_tdk_2_16","chapterId":"ch_work_tdk_2","text":"或曰：晉景文兄弟孰賢？虞南曰：何晏稱唯深也，故能通天下之志，夏侯太初是也；惟幾也故能成天下之務，司馬子元是也。故知王佐之才，著於早日，及誅爽之际，智略已宣。钦、俭稱兵，全軍獨克，此足見其英圖也。雖道盛三分，而終身北面，威名振主而臣節不虧，侯服歸全，於斯為美，太祖嗣興，克寧禍亂，南定淮海，西平庸蜀，役不逾時，厥功為重，及高貴纂歷，聰明夙智，不能竭忠协贊，擬跡伊、周，遂乃伪謗士彦，委罪成濟，自貽逆節，終享惡名。斯言之玷，不可磨也。","sortOrder":16},
  {"id":"s_work_tdk_2_17","chapterId":"ch_work_tdk_2","text":"東晉自元帝以下，何主為賢？虞南曰：晉自遷都江左，強臣擅命，垂拱南面，政非己出；王敦以盤石之宗，居上流之要，負才矜地，志懷問鼎，非肅祖之明斷，王导之忠誠，則晉祚其移於王氏矣。若使降年永久，仗任群賢，因瀍涧之遺黎，乘劉、石之衰運，則克复中原，不難圖也。","sortOrder":17},
  {"id":"s_work_tdk_2_18","chapterId":"ch_work_tdk_2","text":"或曰：伪楚桓玄有奇才遠略，而遂至滅亡，何也？虞南曰：夫人君之量，必虛己應物，覆載同於天地，信誓擬於暄寒，然後萬姓樂推而不厭也。彼桓玄者，蓋有浮狡之小智，而無含宏之大德，值晉末衰亂，威不逮下，故玄得肆其爪牙；以僥幸之餘、而逢神武之運，至於夷滅，固其宜也。","sortOrder":18},
  {"id":"s_work_tdk_2_19","chapterId":"ch_work_tdk_2","text":"宋祖誅滅桓玄，再興晉室，梁代裴子野優之於宣武，其事雲何？虞南曰：魏武曹騰之孫，累葉榮顯，濯纓漢室，三十餘年。及董卓之亂，乃與山東俱起，誅滅元凶，曾非己力。晉宣歷任卿相，位極台鼎，握天下之圖，居既安之势，奉明詔而誅逆節，建瓴為譬，未足喻也。宋祖以匹夫提劍，首創大業，旬月之間，重安晉鼎，居半州之地，驅一郡之卒，斬谯縱於庸蜀，禽姚紹於崤函，克慕容超於青部，枭盧循於嶺外，戎旗所指，無往不捷，觀其豁達，則漢祖之風；製勝胸襟，則光武之匹，惜其祚短，志未可量，此為優矣。","sortOrder":19},
  {"id":"s_work_tdk_2_20","chapterId":"ch_work_tdk_2","text":"宋孝武、明帝二人孰賢。虞南曰：二帝殘忍之性，異體同心，誅戮賢良，割剪枝葉，內無平勃之相，外闕晉鄭之親，以斯大寶，委之昏稚，故使齊民乘衅，宰製天下，未逾歲稔，遂移龟玉，緘縢雖固，適為大盜之資，百慮同失，可為長叹，鼎社傾淪，非不幸也。","sortOrder":20},
  {"id":"s_work_tdk_2_21","chapterId":"ch_work_tdk_2","text":"齊建元、永明之間，號為治世，誠有之乎？虞南曰：齊高創業之主，知稼穡之艱難，且立身俭素，務存簡約；武帝則留意後庭，彫飾過度，然能委任王俭，憲章攸出，禮樂之盛，鹹稱永明，宰相得人，於斯為美。","sortOrder":21},
  {"id":"s_work_tdk_2_22","chapterId":"ch_work_tdk_2","text":"宋齊二代，废主有五，併驕淫狂暴，前後如一，或身被賊殺，或傾墜宗社，豈厥性顽凶，自貽非命，將天之所弃，用亡大業乎？虞南曰：夫上智下愚，特禀異氣；中庸之才，皆由訓習。自宋齊已來，東宮師傅，備員而已。貴賤禮隔，規獻無由，多以位升，罕由德進。此五君者，禀凡庸之性，無周、召之師，遠益友之箴規，狎宵人之近習，以斯下质，生而楚言，覆國亡身，理數然也。","sortOrder":22},
  {"id":"s_work_tdk_2_23","chapterId":"ch_work_tdk_2","text":"梁元帝聰明才學，克平禍亂，而卒致傾覆，何也？虞南曰：梁元聰明技藝，才兼文武，杖順伐逆，克雪家冤，成功遂事，有足稱者。但國難之後，傷夷未复，信強寇之甘言，袭褊心於懷楚；蕃屏宗支，自為仇敵，孤遠懸僻，莫與同忧，身亡祚滅，生人涂炭，舉鄢郢而弃之，良行惜也。","sortOrder":23},
  {"id":"s_work_tdk_2_24","chapterId":"ch_work_tdk_2","text":"後齊文宣帝，狂悖之跡，桀紂之所不為，而國富人丰，不至於亂亡，何也？虞南曰：昔齊桓奢淫亡禮，人倫所弃，假六翮於仲父，遂伯諸侯；宣武帝鄙稔忍虐，古今無比，委萬機於遒彦，保全宗國，以其任用得才，所以社稷猶存者也。","sortOrder":24},
  {"id":"s_work_tdk_2_25","chapterId":"ch_work_tdk_2","text":"陳武帝起自草萊，興創帝業，近代以來，可方何主？虞南曰：武帝以奇才遠略，懷匡复之志，龍躍海嵎，豹变嶺表，扫重氛於縫闕，复帝座於紫微，西抗周師，北夷齊寇，宏謀長算，動無遺册，實开基之令主，拨亂之雄才，比宋祖則不及，方齊高則優矣。","sortOrder":25},
  {"id":"s_work_tdk_2_26","chapterId":"ch_work_tdk_2","text":"隋文帝起自布衣，光有神器，西定庸蜀，南平江表，比於晉武，可為儔乎？虞南曰：隋文因外戚之重周室之微，負圖作宰，遂膺寶命，留心政治，務從恩泽，故能綏撫新舊，緝寧遐邇，文武製置，皆有可觀。及克定江淮，鹹同書軌，率士黎獻，企佇太平。自金陵滅後，王心奢汰，雖威加四海，而情墮萬機，荆璧填於內府，吳姬滿於下室，仁寿彫飾，事將傾宮，萬姓力殫，中民產竭，加以猜忌心起，巫蠱事興，戮愛子之妃，離上相之母，綱維已紊，禮教斯亡，牝雞晨响，皇枝剿絕，废黜不辜，树立所愛，功臣良佐，誅翦無遺，季年之失，多於晉武，卜世不永，豈天亡乎？","sortOrder":26},
  {"id":"s_work_tdk_2_27","chapterId":"ch_work_tdk_2","text":"或曰：王霸之略，請事斯語矣。敢問殁而作謚，及改正朔、易服色，以变人之耳目，其事奚象？對曰：古之立謚者，將以戒夫後代。隨行受名，君親無隱。今之臣子不論名實，務在尊崇，斯風替也久矣。昔季康子問五帝之德於孔子，孔子曰：天有五行，木火金水及土，分時化育以成物，其神為五帝緯。古之王者，易代改號，取法五行；五行更王，終始相生，亦象其義。故其生為明王者，而死配五行，是以太皞配木，炎帝配火，少皞配金，颛頊配水，黃帝配土。帝王改號，於五行之德，各有所尚，從其所王之德次焉。夏後氏以金德王而尚黑，殷人以水德王而尚白，周人以木德王而色尚赤，此三代之所以不同也。及漢之初，公孫臣、贾誼以為漢土德，以五行之傳，從所不勝，秦在水德，故謂漢據土而克之。劉向父子以為帝出於震，故庖犧氏始受木德，其後以母傳子，終而复始，自神農、黃帝下歷唐、虞、三代，而漢得火焉。故高祖始起，神母夜號，著赤帝之符，得天統矣。昔共工以水德間於木火，與秦同運，非其次，故皆不永也。以此觀之，雖百代可知也。","sortOrder":27},
  {"id":"s_work_tdk_2_28","chapterId":"ch_work_tdk_2","text":"臣行第十","sortOrder":28},
  {"id":"s_work_tdk_2_29","chapterId":"ch_work_tdk_2","text":"夫人臣萌牙未動，形兆未見，昭然獨見存亡之機、得失之要，豫禁乎未然之前，使主超然立乎顯榮之處，如此者，聖臣也。虛心盡意，日進善道，勉主以禮義，諭主以長策，將順其美，匡救其惡，如此者，大臣也。夙興夜寐，進賢不懈，數稱往古之行事，以厲主意，如此者，忠臣也。明察成败，早防而救之，塞其間，絕其源，轉禍以為福，君終已無忧，如此者，智臣也。依文奉法，任官職事，不受赠遺，食飲節俭，如此者，貞忠也。國家昏亂，所為不諛，敢犯主之嚴顏，面言主之過失，如此者，直臣也。是謂六正。","sortOrder":29},
  {"id":"s_work_tdk_2_30","chapterId":"ch_work_tdk_2","text":"安官貪祿，不務公事，與世沈浮，左右觀望，如此者，具臣也。主所言皆曰善，主所為皆曰可，隱而求主之所好而進之，以快主之耳目，偷合苟容，與主為樂，不顧後害，如此者，諛臣也。中實险诐，外貌小謹，巧言令色，又心疾賢，所欲進則明其美、隱其惡，所欲退則彰其過、匿其美，使主賞罰不當，號令不行，如此者，奸臣也。智足以佣非，辯足以行說，內離骨肉之親，外妒亂於朝廷，如此，讒臣也。专權擅势，以輕為重，私門成党，以富其家，擅矯主命，以自顯貴，如此者，賊臣也。諂主以佞邪，墜主於不義，朋党比周，以蔽主明，使白黑無別，是非無聞，使主惡布於境內、聞於四鄰，如此者，亡國之臣也。是謂六邪。","sortOrder":30},
  {"id":"s_work_tdk_2_31","chapterId":"ch_work_tdk_2","text":"子貢曰：陳靈公君臣宣淫於朝，泄冶諫而殺之，是與比幹同也，可謂仁乎？子曰：比幹於紂，親則叔父，官則少師，忠款之心在於存宗廟而已，故以必死爭之，冀身死之後而紂悔寤，其本情在乎仁也。泄冶位為下大夫，無骨肉之親，懷寵不去，以區區之一身，欲正一國之淫昏，死而無益，可謂懷矣。《詩》雲：民之多僻，無自立辟。其泄冶之謂乎？","sortOrder":31},
  {"id":"s_work_tdk_2_32","chapterId":"ch_work_tdk_2","text":"或曰：叔孫通阿二世意，可乎？司馬遷曰：夫量主而進，前晢所韙。叔孫生希世度務，製禮進退，與時变化，卒為漢家儒宗。古之君子，直而不挺，曲而不撓，大直若诎，道同委蛇，蓋謂是也。","sortOrder":32},
  {"id":"s_work_tdk_2_33","chapterId":"ch_work_tdk_2","text":"或曰：然則窦武、陳蕃，與宦者同朝廷爭衡，終為所誅，為非乎？范晔曰：桓靈之世，若陳蕃之徒，鹹能树立風聲，抗論昏俗，驅馳岨厄之中，而與腐夫爭衡，終取滅亡者，彼非不能絜情志、违埃霧也，悯夫世士，以離俗為高，而人倫莫相恤也。以遯世為非義，故屢退而不去；以仁心為己任，雖道遠而弥厲。及遭值际會，协策窦武，可謂萬代一時也，功雖不終，然其信義足以携持世心矣。","sortOrder":33},
  {"id":"s_work_tdk_2_34","chapterId":"ch_work_tdk_2","text":"或曰：臧洪死張超之難，可謂義平。范晔曰：雍丘之围，臧洪之感憤，壮矣。相其徒跣且號，束甲請舉，誠足怜也。夫豪雄之所趣舍，其與守義之心異乎？若乃締謀連衡、懷诈算以相尚者，蓋惟势利所在而已。况偏城既危，曹、袁方穆，洪徒指外敵之衡，以纾倒懸之會。忿悁之師，兵家所忌，可謂懷哭秦之節，存荆則未聞。","sortOrder":34},
  {"id":"s_work_tdk_2_35","chapterId":"ch_work_tdk_2","text":"或曰：季布壮士，而反摧刚為柔，髡鉗匪匿，為是乎？司馬遷曰：以項羽之氣，而季布以勇顯於楚，身屢典軍搴旗者數矣，可謂壮士。然至被刑戮，為人奴而不死，何其下？彼必自負其材，故受辱而不羞，欲有所用其未足也，故終為漢名將。賢者誠重其死。非夫婢妾賤人，感慨而自殺者，非勇也。其計盡無复之耳。","sortOrder":35},
  {"id":"s_work_tdk_2_36","chapterId":"ch_work_tdk_2","text":"或曰：宗壳之賤也，見輕庾業。及其貴也，請業為長史，何如？裴子野曰：夫貧而無戚，賤而無悶，恬夫天素，宏此大猷，曾、原之德也。降志辱身，俯眉折脊，忍屈庸曹之下，貴騁群雄之上，韓、黥之志也。卑身之事則同，居卑之情已異。若宗元幹無怍於草具，有韓、黥之度矣，終弃舊惡，長者哉！","sortOrder":36},
  {"id":"s_work_tdk_2_37","chapterId":"ch_work_tdk_2","text":"世稱郦寄賣交，以其绐呂祿也，於理何如？班固曰：夫賣交者，謂見利忘義也。若寄父為功臣而執劫，雖摧呂祿，以安社稷，義存君親可也。","sortOrder":37},
  {"id":"s_work_tdk_2_38","chapterId":"ch_work_tdk_2","text":"或曰：靳允违親守城，可謂忠乎？徐眾曰：靳允於曹公，未成君臣；母，至親也，於義應去。昔王陵母為項羽所拘，母以高祖必得天下，因自殺以固陵志。明心無所系，然後可得事人，盡其死節。衛公子开方仕齊，十年不歸。管仲以其不懷其親，安能愛君？不可以為相。是以求忠臣必於孝子之門，允宜先救至親。徐庶母為曹公所得，劉備乃遺庶歸。欲為天下者，恕人子之情。公又宜遣允也。","sortOrder":38},
  {"id":"s_work_tdk_2_39","chapterId":"ch_work_tdk_2","text":"魏文帝問王朗等曰：昔子產治鄭，人不能欺；子賤治单父，人不忍欺；西門豹治鄴，人不敢欺。三子之才，於君德孰優？對曰：君任德則臣感義而不忍欺，君任察則臣畏覺而不能欺，君任刑則臣畏罪而不敢欺。任德感義，與夫导德齊禮、有恥且格，等趨者也；任察畏非，與夫导政齊刑、免而無恥，同歸者也。優劣之懸，在於權衡，非徒鈞銖之覺也。","sortOrder":39},
  {"id":"s_work_tdk_2_40","chapterId":"ch_work_tdk_2","text":"或曰：季文子、公孫宏，此二人皆折節俭素，而毀譽不同，何也？范晔稱：夫人利仁者，或借仁以從利；體義者，不期體以合義。季文子妾不衣帛，魯人以為美談；公孫宏身服布被，汲黯譏其多诈。事實未殊而毀譽別者，何也？將體之與利之異乎！故前志雲：仁者安仁，智者利仁，畏罪者強仁。校其仁者，功無以殊，核其為仁，不得不異。安仁者，性善者也；利仁者，力行者也；強仁者，不得已者也。三仁相比，則安者優矣。","sortOrder":40},
  {"id":"s_work_tdk_2_41","chapterId":"ch_work_tdk_2","text":"或曰：長平之事，白起坑趙卒四十萬，可為奇將乎？何晏曰：白起之降趙卒，诈而坑其四十萬，豈徒酷暴之謂乎？後亦難以重得志矣。向使眾人豫知降之必死，則張虛拳，猶可畏也，况於四十萬被堅執銳哉？天下見降秦之將，頭臚依山；歸秦之眾，骸積成丘，則後日之戰，死當死耳，何眾肯服？何城肯下乎？是為雖能裁四十萬之命，而適足以強天下之戰；欲以要一朝之功，而乃更堅諸侯之守，故兵進而自伐其势，軍勝而還丧其計。何者？設使趙眾复合，馬服更生，則後日之戰，起非前日之對也。况今皆使天下為後日乎？其所以終不敢复加兵於邯鄲者，非但忧平原之補縫、患諸侯之救至也，徒讳之而不言耳。且長平之事，秦人十五以上，皆荷戟而向趙矣。夫以秦之強，而十五已上，死傷過半，此為破趙之功小、傷秦之败大也。又何稱奇哉？","sortOrder":41},
  {"id":"s_work_tdk_2_42","chapterId":"ch_work_tdk_2","text":"或曰：樂毅不屠二城，遂丧洪業，為非乎？夏侯元曰：觀樂生與燕惠王書，其殆乎知機合道、以禮終始者欤？夫欲極道德之量，務以天下為心者，豈其局跡當時、止於兼併而已哉？夫兼併者，非樂生之所屑；強燕而废道，又非樂生之所求。不屑苟利，不求小成，斯意兼天下者也。舉齊之事，所以運其機而動四海也。围城而害不加於百姓，此仁心著於遐邇矣；邁令德以率列國，則幾於湯武之事矣。樂生方恢大綱，以縱二城，收人明信，以待其弊，將使即墨、莒人，顧仇其上。开宏廣之路，以待田单之徒；長容善之風，以申齊士之志；招之東海，屬之華裔，我泽如春，人應如草，思戴燕主、仰風聲，二城必從，則王業隆矣。雖淹留於兩邑，乃致速於天下也。不幸之变，势所不圖；败於垂成，時变所然。若乃逼之以兵，劫之以威，奓殺傷之殘，以示四海之人，雖二城幾於可拔，則霸王之事，逝其遠矣。樂生豈不知拔二城之速了哉？顧城拔而業乖也。豈不慮不速之致变哉？顧業速與变同也。由是觀之，樂生之不屠二城，未可量也。","sortOrder":42},
  {"id":"s_work_tdk_2_43","chapterId":"ch_work_tdk_2","text":"或曰：商鞅起徒步，幹孝公，挟三術之略，吞六國之縱，使秦業帝，可為霸者之佐乎？劉向曰：夫商君，內急耕戰之業，外重戰伐之賞，不阿貴寵，不偏疏遠。雖《書》雲無偏無党，《詩》雲周道如砥、其直如矢，司馬法之厲戎士，周後稷之勸農業，無以易此。此所以併諸侯也。故孫卿曰：四世有勝，非幸也，數也。夫霸君若齊桓、晉文者，桓不倍柯之盟，文不負原之期，而諸侯信之，此管仲、咎犯之謀也。今商君倍公子卬之舊恩，弃交魏之明信，诈取三軍之眾，故諸侯畏其強而莫親信也。藉使孝公遇齊桓、晉文得諸侯之統，將合諸侯之君，驅天下之兵以伐秦，秦則亡矣。天下無桓、文之君，故秦得以兼諸侯也。衛鞅始自以為知王霸之德，原其事，不倫也。昔周邵公施美政，其死也，後世思之。蔽芾甘棠之詩，是嘗舍於树下，不忍伐其树，况害於身乎？管仲奪伯氏骈邑三百戶，無怨言。今衛鞅內刻刀鋸之刑，外深鈇鉞之誅，身死車裂，其去霸者之佐，亦遠矣。然孝公殺之，亦非也，可辅而用。使衛鞅施宽平之法，加之以恩，申之以信，庶幾霸者之佐乎。","sortOrder":43},
  {"id":"s_work_tdk_2_44","chapterId":"ch_work_tdk_2","text":"諸葛亮以馬謖败於街亭，殺之。後蒋琬謂亮曰：昔楚殺得臣，然後文公喜，可知也。天下未定，而戮智計之士，豈不惜哉？亮流涕曰：孫武所以能製勝者，用法明也。是以楊於亂法，魏絳戮之。四海分裂，兵交方始，若复废法，何用讨賊耶？習凿齒曰：諸葛亮之不能兼上國也，豈不宜哉！夫晉人视林父之後濟，故废法而收功；楚成闇得臣之益已，故殺之以重败。今蜀僻陋一方，才少上國，而殺其駿桀，退收駑下之用，明法勝才，不師三败之道，將以成業，不亦難乎！","sortOrder":44},
  {"id":"s_work_tdk_2_45","chapterId":"ch_work_tdk_2","text":"代以周勃功大霍光，何如？對曰：勃本高帝大臣，眾所歸向，居太尉位，擁兵百萬，既有陳平王陵之力，又有朱虛諸王之援，郦寄遊說，以譎諸呂，因眾之心，易以濟事。若霍光者，以仓卒之际，受寄讬之任，辅弼幼主，天下晏然，遇燕王綰之亂，誅除凶逆，以靖王室，废昌邑，立孝宣，任漢家之重，隆中興之祚，參聲伊周，為漢賢相，推验事效，優劣明矣。","sortOrder":45},
  {"id":"s_work_tdk_2_46","chapterId":"ch_work_tdk_2","text":"後漢陳蕃上疏荐徐稚、袁閎、韦著三人，帝問蕃曰：三人誰為先後？蕃曰：閎生公族，聞道漸訓；著長於三辅禮義之俗，所謂不扶自直，不鏤自彫；至於稚者，爰自江南卑薄之域，而角立杰出，宜當為先。","sortOrder":46},
  {"id":"s_work_tdk_2_47","chapterId":"ch_work_tdk_2","text":"或曰：謝安石為相，可與何人為比？虞南曰：昔顧雍封侯之日，而家人不知，前代稱其质重，莫以為偶。夫以東晉衰微，疆場日駭。况永固六夷主，親率百萬；苻融俊才名相，執銳先驅，厲虎狼之爪牙，騁長蛇之鋒鍔，先筑賓馆，以待晉君。強弱而論，鸿毛太山，不足為喻。文靜深拒桓沛之援，不喜謝元之書，則勝败之數，固已存於胸中矣。夫斯人也，豈以區區萬戶之封，動其方寸者欤？若論其度量，近古已來，未見其匹。","sortOrder":47},
  {"id":"s_work_tdk_2_48","chapterId":"ch_work_tdk_2","text":"隋煬帝在東宮，嘗謂贺若弼曰：楊素、韓擒虎、史萬歲三人，俱稱良將，其間優劣何如？對曰：楊素是猛將，非謀將；韓擒虎是斗將，非領將；史萬歲是騎將，非大將。太子曰：善。","sortOrder":48},
  {"id":"s_work_tdk_2_49","chapterId":"ch_work_tdk_2","text":"故自六正至於問將，皆人臣得失之效也。古語曰：禹以夏王，桀以夏亡；湯以殷王，紂以殷亡。阖庐以吳戰勝無敵於天下，而夫差以見擒於越；穆公以秦顯名尊號，而二世以劫於望夷。其所以君王者同，而功跡不等者，所任異也。是以成王處襁褓而朝諸侯，周公用事也；趙武靈王年五十而饿死於沙丘，任李兑也。故魏有公子無忌，削地复得；趙任蔺相如，秦兵不敢出；楚有申包胥，而昭王反位；齊有田单，而襄王得國。因斯而談，夫有國者，不能陶冶世俗、甄綜人物、論邪正之得失、撮霸王之餘議，有能立功成名者，未之前聞。","sortOrder":49},
  {"id":"s_work_tdk_2_50","chapterId":"ch_work_tdk_2","text":"德表十一","sortOrder":50},
  {"id":"s_work_tdk_2_51","chapterId":"ch_work_tdk_2","text":"孔子曰：性相近也，習相遠也。言嗜欲之本同，而遷染之涂異也。夫刻意則行不肆，牵物則志流。是以聖人导人理性，裁抑流宕，慎其所與，節其所偏。故傳曰：審好惡，理情性，而王道畢矣。治性之道，必審己之所有餘，而強其所不足。蓋聰明疏通者，戒於太察；寡聞少見者，戒於擁蔽；勇猛刚強者，戒於太暴；任愛溫良者，戒於無斷；湛靜安舒者，戒於後時；廣心浩大者，戒於遺忘。","sortOrder":51},
  {"id":"s_work_tdk_2_52","chapterId":"ch_work_tdk_2","text":"《人物志》曰：厲直刚毅，材在矯正，失在激訐；柔順安恕，美在宽容，失在少决；雄悍桀健，任在胆烈，失在多忌；精良畏慎，善在恭謹，失在多疑；強楷堅劲，用在楨幹，失在专固；論辯理繹，能在釋結，失在流宕；普搏周洽，崇在覆裕，失在溷濁；清介廉絜，節在俭固，失在拘局；休動磊硌，業在攀跻，失在疏越；沈靜Ａ１密，精在元微，失在遲懦；朴露径盡，质在中誠，失在不微。多智韜情，權在譎略，失在依违。此拘亢之材，非中庸之德也。","sortOrder":52},
  {"id":"s_work_tdk_2_53","chapterId":"ch_work_tdk_2","text":"文子曰：凡人之道，心欲小，志欲大；智欲圓，行欲方；能欲多，事欲少。所謂心小者，慮患未生，戒禍慎微，不敢縱其欲也；志大者，兼包萬國，一齊殊俗，是非輻凑，中為之轂也；智圓者；終始無端，方流四遠，深泉而不竭也；行方者，直立而不撓，素白而不污，窮不易操，達不肆志也；能多者，文武備具，動靜中儀也；事少者，執約以治廣，處靜以待躁也。","sortOrder":53},
  {"id":"s_work_tdk_2_54","chapterId":"ch_work_tdk_2","text":"夫天道極即反，盈則損。故聰明廣智，守以愚；多聞搏辯，守以俭；武力毅勇，守以畏；富貴廣大，守以狹；德施天下，守以讓。此五者，先王所以守天下也。傳曰：無始亂，無怙富，無恃寵，無违同，無傲禮，無驕能，無复怒，無謀非德，無犯非義。此九言，古人所以立身也。《玉鈐經》曰：夫以明示者淺，有過不自知者弊，迷而不反者流，以言取怨者禍，令與心乖者废，後令缪前者毀，怒而無威者犯，好眾辱人者殃，戮辱所任者危，慢其所敬者凶，貌合心離者孤，親佞遠忠者亡，信讒弃賢者惛，私人以官者浮，女謁公行者亂，群下外恩者淪，凌下取勝者侵，名不勝實者耗，自厚薄人者弃，薄施厚望者不報，賞而忘賤者不久，用人不得其正者殆，為人擇官者失，决於不仁者险，陰謀外泄者败，厚斂薄施者彫。此理之大體也。","sortOrder":54},
  {"id":"s_work_tdk_2_55","chapterId":"ch_work_tdk_2","text":"故《傅子》曰：立德之本，莫尚乎正心。心正而後身正，身正而後左右正，左右正而後朝廷正，朝廷正而後國家正，國家正而後天下正。故天下不正，修之家；家不正，修之朝廷；朝廷不正，修之左右；左右不正，修之身；身不正，修之心。所修弥近，所濟弥遠。禹、湯罪己，其興也勃焉，正心之謂也。","sortOrder":55},
  {"id":"s_work_tdk_2_56","chapterId":"ch_work_tdk_2","text":"理亂第十二","sortOrder":56},
  {"id":"s_work_tdk_2_57","chapterId":"ch_work_tdk_2","text":"夫明察六主，以觀君德，審惟九風，以定國常。探其四亂，覈其四危，則理亂可知矣。","sortOrder":57},
  {"id":"s_work_tdk_2_58","chapterId":"ch_work_tdk_2","text":"何謂六主？荀悅曰：體正性仁，心明志同，動以為人，不以為己，是謂王主；克己恕躬，好問力行，動以從義，不以從情，是謂治主；勤事守業，不敢怠荒，動以先公，不以先私，是謂存主，悖逆交爭，公私併行，一得一失，不純道度，是謂衰主；情過於義，私多於公，製度逾限，政教失常，是謂危主；親用讒邪，放逐忠賢，縱情逞欲，不顧禮度，出人遊放，不拘儀禁，賞賜行私，以越公用，忿怒施罰，以逾法理，遂非文過，而不知改，忠言擁塞，直諫誅戮，是謂亡主。","sortOrder":58},
  {"id":"s_work_tdk_2_59","chapterId":"ch_work_tdk_2","text":"何謂九風？君臣親而有禮，百寮和而不同，讓而不爭，勤而不怨，唯職是司，此禮國之風也；禮俗不一，職位不重，小臣讒疾，庶人作議，此衰國之風也；君臣爭明，朝廷爭功，大夫爭名，庶人爭利，此乖國之風也；上多欲，下多端，法不定，政多門，此亂國之風也；以侈為博，以伉為高，以濫為通，遵禮謂之拘，守法謂之固，此荒國之風也；以苛為察，以利為公，以割下為能，以上為忠，此叛國之風也；上下相疏，內外相疑，小臣爭寵，大臣爭權，此危國之風也；上不訪下，下不諫上，婦言用，私政行，此亡國之風也。","sortOrder":59},
  {"id":"s_work_tdk_2_60","chapterId":"ch_work_tdk_2","text":"何謂四亂？《管子》曰：內有疑妻之妾，此家亂也；庶有疑嫡之子，此宗亂也；朝有疑相之臣，此國亂也；任官無能，此眾亂也。","sortOrder":60},
  {"id":"s_work_tdk_2_61","chapterId":"ch_work_tdk_2","text":"何謂四危？又曰：卿相不得眾，國之危也；大臣不和同，國之危也；兵主不足畏，國之危也；民不懷其產，國之危也。此治亂之形也。","sortOrder":61},
  {"id":"s_work_tdk_2_62","chapterId":"ch_work_tdk_2","text":"凡為人上者，法術明而賞罰必者，雖無言語，而势自治；法術不明而賞罰不必者，雖曰號令，然势是亂。是故势理者，雖委之不亂；势亂者，雖勤之不治。尧、舜拱己無為而有餘，势理也；胡亥、王莽馳骛而不足，势亂也。故曰：善者求之於势，不责於人。是故明主審法度而布教令，則天下治矣。","sortOrder":62},
  {"id":"s_work_tdk_2_63","chapterId":"ch_work_tdk_2","text":"論曰：夫能匡世辅政之臣，必先明於盛衰之道、通於成败之數、審於治亂之势、達於用舍之宜，然後臨機而不惑、見疑而能斷。為王者之佐，未有不由斯者矣。","sortOrder":63},
  {"id":"s_work_tdk_2_64","chapterId":"ch_work_tdk_2","text":"《長短經》　唐　趙蕤","sortOrder":64},
  {"id":"s_work_tdk_3_1","chapterId":"ch_work_tdk_3","text":"卷三文下","sortOrder":1},
  {"id":"s_work_tdk_3_2","chapterId":"ch_work_tdk_3","text":"反經第十三","sortOrder":2},
  {"id":"s_work_tdk_3_3","chapterId":"ch_work_tdk_3","text":"臣聞三代之亡，非法亡也，御法者非其人矣。故知法也者，先王之陳跡。苟非其人，道不虛行。","sortOrder":3},
  {"id":"s_work_tdk_3_4","chapterId":"ch_work_tdk_3","text":"故《尹文子》曰：仁義禮樂、名法刑賞，此八者，五帝三王治世之術。故仁者，所以博施於物，亦所以生偏私；義者，所以立節行，亦所以成華伪；禮者，所以行敬謹，亦所以生惰慢；樂者，所以和情志，亦所以生淫放；名者，所以正尊卑，亦所人以生矜篡；法者，所以齊眾異，亦所以生乖分；刑者，所以威不服，亦所以生凌暴；賞者，所以勸忠能，亦所以生鄙爭。","sortOrder":4},
  {"id":"s_work_tdk_3_5","chapterId":"ch_work_tdk_3","text":"《文子》曰：聖人其作書也，以領理百事，愚者以不忘，智者以記事，及其衰也，為奸伪，以解有罪而殺不辜；其作囿也，以奉宗廟之具，簡士卒，戒不虞，及其衰也，馳騁弋獵，以奪人時其上賢也，以平教化，正獄訟，賢者在位，能者在職，泽施於下，萬人懷德，至於衰也，朋党比周，各推其與，废公趨私，外內鉗舉，奸人在位，賢者穩處。《韓詩外傳》曰：夫士有五反。有势尊貴，不以愛人行義理，而反以暴傲；家富厚，不以振窮救不足，而反以侈靡無度；資勇悍，不以衛上攻戰，而反以侵凌私斗；心智惠，不以端計教，而反以事奸飾诈；貌美好，不以統朝莅人，而反以蠱女從欲。","sortOrder":5},
  {"id":"s_work_tdk_3_6","chapterId":"ch_work_tdk_3","text":"太公曰：明罰則人畏慑，人畏慑則变故出；明察則人扰，人扰則人徙，人徙則不安其處，易以成变。","sortOrder":6},
  {"id":"s_work_tdk_3_7","chapterId":"ch_work_tdk_3","text":"晏子曰：臣专其君，謂之不忠；子专其父，謂之不孝；妻专其夫，謂之嫉妒。","sortOrder":7},
  {"id":"s_work_tdk_3_8","chapterId":"ch_work_tdk_3","text":"《韓子》曰：儒者以文亂法，俠者以武犯禁。","sortOrder":8},
  {"id":"s_work_tdk_3_9","chapterId":"ch_work_tdk_3","text":"子路拯溺而受牛謝。孔子曰：魯國必好救人於患也。子貢贖人而不受金於府。孔子曰：魯國不复贖人矣。子路受而勸德，子貢讓而止善。由此觀之，廉有所在而不可公行。","sortOrder":9},
  {"id":"s_work_tdk_3_10","chapterId":"ch_work_tdk_3","text":"慎子曰：忠未足以救亂代，而適足以重非。何以識其然耶？曰：父有良子而舜放瞽叟，桀有忠臣而過盈天下，然則孝子不生慈父之家，而忠臣不生聖君之下。故明主之使其臣也，忠不得過職，而職不得過官。","sortOrder":10},
  {"id":"s_work_tdk_3_11","chapterId":"ch_work_tdk_3","text":"《鬼穀子》曰：將為胠箧、探囊、發匮之盜，為之守備，則必攝緘縢、固扃鐍，此代俗之所謂智也。然而巨盜至，則負匮揭箧，擔囊而趨，唯恐緘縢扃鐍之不固也。然則向之所謂智者，有不為盜積者乎？其所謂聖者，有不為大盜守者乎？何以知其然耶？昔者齊國，鄰邑相望，雞狗之音相，罔罟之所布，耒耨之所刺，方二千餘里。阖四境之內，所以立宗廟社稷、治邑屋州闾乡里者，曷常不法聖人哉？然而田成子一朝殺齊君而盜其國。所盜者豈獨其國耶？併與聖智之法而盜之。故田成子有乎盜賊之名，而身處尧、舜之安，小國不敢非，大國不敢誅，十二代而有齊國，則是不乃竊齊國、併與其聖智之法，以守其盜賊之身乎？跖之徒問於跖曰：盜亦有道乎？跖曰：何適而無有道耶？夫妄意室中之藏，聖也；入先，勇也；出後，義也；知可否，智也；分均，仁也。五者不備，而能成大盜者，天下未之有也。由是觀之，善人不得聖人之道不立，盜跖不得聖人之道不行。天下之善人少而不善人多，則聖人之利天下也少，而害天下也多矣。","sortOrder":11},
  {"id":"s_work_tdk_3_12","chapterId":"ch_work_tdk_3","text":"由是言之，夫仁義禮樂、名法刑賞、忠孝賢智之道、文武明察之端，無隱於人，而常存於代，非自昭於尧湯之時，非故逃於桀紂之朝，用其道則天下理，用失其道而天下亂，故知製度者，代非無也，在用之而已。","sortOrder":12},
  {"id":"s_work_tdk_3_13","chapterId":"ch_work_tdk_3","text":"是非第十四","sortOrder":13},
  {"id":"s_work_tdk_3_14","chapterId":"ch_work_tdk_3","text":"夫損益殊涂，质文異政，或尚權以經緯，或敦道以镇俗。是故前志垂教，今皆可以理违。何以明之？","sortOrder":14},
  {"id":"s_work_tdk_3_15","chapterId":"ch_work_tdk_3","text":"《大雅》雲：既明且哲，以保其身。《易》曰：天地之大德曰生。《語》曰：士見危致命。又曰：君子有殺身以成仁，無求生以害仁。","sortOrder":15},
  {"id":"s_work_tdk_3_16","chapterId":"ch_work_tdk_3","text":"管子曰：疑今者察之古，不知來者视之往。古語曰：與死人同病者，不可生也；與亡國同行者，不可存也。《呂氏春秋》曰：夫人以食死者，欲禁天下之食，悖矣；有以乘舟死者，欲禁天下之船，悖矣；有以用兵丧其國者，欲偃天下之兵，悖矣。杜恕曰：夫奸臣賊子，自古及今，未嘗不有。百歲一人，是為繼踵。千里一人，是為比肩。而舉以為戒，是猶一噎而禁人食也。噎者雖少，饿者必多。","sortOrder":16},
  {"id":"s_work_tdk_3_17","chapterId":"ch_work_tdk_3","text":"孔子曰：惡訐惡以為直。《管子》曰：惡隱惡以為仁者。魏曹義《至公論》曰：夫代人所謂惡扬善者，君子之大義；保明同好者，朋友之至交。斯言之作，蓋闾阎之白談，所以救愛憎之相謗，非篤正之至理、折中之公議也。世士不料其數，而系其言，故善惡不分，以覆過為宏也；朋友忽義，以雷同為美也。善惡不分，亂實由之；朋友雷同，败必從焉。談論以當實為情，不以過難為貴；相以等分為交，不以雷同為固。是以達者存其義，不察於文；識其心，不求於言。","sortOrder":17},
  {"id":"s_work_tdk_3_18","chapterId":"ch_work_tdk_3","text":"《越絕書》曰：衒女不貞，衒士不信。《漢書》曰：大行不細謹，大禮不讓辭。","sortOrder":18},
  {"id":"s_work_tdk_3_19","chapterId":"ch_work_tdk_3","text":"黃石公曰：務廣地者荒，務廣德者強，有其有者安，貪人有者殘。殘滅之政，雖成必败。司馬错曰：欲富國者，務廣其地；欲強兵者，務富其人；欲王者，務博其德。三資者備，而後王業隨之。","sortOrder":19},
  {"id":"s_work_tdk_3_20","chapterId":"ch_work_tdk_3","text":"《傳》曰：心苟無瑕，何恤乎無家？語曰：禮義之不愆，何恤於人言？語曰：積毀銷金，積讒磨骨，默羽溺舟，群輕折軸。","sortOrder":20},
  {"id":"s_work_tdk_3_21","chapterId":"ch_work_tdk_3","text":"孔子曰：君子不器，聖人智周萬物。《列子》曰：天地無全功，聖人無全能，萬物無全用。故天職生覆，地職載井，聖職教化。","sortOrder":21},
  {"id":"s_work_tdk_3_22","chapterId":"ch_work_tdk_3","text":"孔子曰：君子坦荡荡，小人長戚戚。孔子曰：晉重耳之有霸心也，生於曹、衛；越勾踐之有霸心也，生於會稽。故居下而無忧者，則思不遠；覆身而常逸者，則志不廣。","sortOrder":22},
  {"id":"s_work_tdk_3_23","chapterId":"ch_work_tdk_3","text":"《韓子》曰：古之人，目短於自見，故以鏡觀面；智疑於自知，故以道正己。《老子》曰：反聽之謂聰，內视之謂明，自勝之謂強。","sortOrder":23},
  {"id":"s_work_tdk_3_24","chapterId":"ch_work_tdk_3","text":"唐且曰：专諸懷錐刀而天下皆謂之勇，西施被短竭而天下稱美。《慎子》曰：毛嫱、西施，天下之至姣也，衣之以皮倛，則見者皆走；易之以元緆，則行者皆止。由是觀之，則元緆色之助也，姣者辭之，則色厭矣。","sortOrder":24},
  {"id":"s_work_tdk_3_25","chapterId":"ch_work_tdk_3","text":"項梁曰：先起者製服於人，後起者受製於人。《軍志》曰：先人有奪人之心。史佚有言曰：無始禍。又曰：始禍者死。語曰：不為禍始，不為福先。","sortOrder":25},
  {"id":"s_work_tdk_3_26","chapterId":"ch_work_tdk_3","text":"《慎子》曰：夫賢而屈於不肖者，權輕也；不肖而服於賢者，位尊也。尧為匹夫，不能使其鄰家；及至南面而王，則令行禁止。由是觀之，賢不足以服物，而势位足以屈賢矣。贾子曰：自古至今，與民為仇者，有遲有速耳，而民必勝之矣。故紂自謂天王也，而桀自謂天父也，已滅之後，民以骂之也。以此觀之，則位不足以為尊，而號不足以為榮矣。","sortOrder":26},
  {"id":"s_work_tdk_3_27","chapterId":"ch_work_tdk_3","text":"漢景帝時，轅固與黃生爭論於上前。黃生曰：湯武非受命，乃殺也。固曰：不然。夫桀紂荒亂，天下之心皆歸湯武。湯武與天下之心而誅桀紂，桀紂之人弗為使而歸湯武，湯武不得已而立，非受命而何？黃生曰：冠雖敝，必加於首；履雖新，必貫於足。何者？上下之分也。今桀紂雖失道，然君上也；湯武雖聖，臣下也。夫君有失行，臣不上號言匡過以尊天子，反因過而誅之，代立南面，非殺而何？","sortOrder":27},
  {"id":"s_work_tdk_3_28","chapterId":"ch_work_tdk_3","text":"太公曰：明罰則人畏慑，人畏慑則变故出；明賞則不足，不足則怨長。故明王之理人，不知所好，不知所惡。《文子》曰：罰無度則戳而無威，賞無度則費而無恩。故諸葛亮曰：威之以法，法行則知恩；限之以爵，爵加則知榮。","sortOrder":28},
  {"id":"s_work_tdk_3_29","chapterId":"ch_work_tdk_3","text":"《文子》曰：人之化上，不從其言，從其行也。故人君好勇，而國家多難；人君好色，而國家昏。秦王曰：吾聞楚之鐵劍利而倡優拙。夫鐵劍利則士勇，倡優拙則思慮遠。以思慮御勇土，吾恐楚之圖秦也。","sortOrder":29},
  {"id":"s_work_tdk_3_30","chapterId":"ch_work_tdk_3","text":"墨子曰：雖有賢君，不愛無功之臣；雖有慈父，不愛無益之子。曹子建曰：舍罪责功者，明君之舉也；矜愚愛能者，慈父之恩也。《三略》曰：含氣之類，皆願得其申志。是以明君賢臣，屈己申人。","sortOrder":30},
  {"id":"s_work_tdk_3_31","chapterId":"ch_work_tdk_3","text":"《傳》曰：人心不同，其猶面也。曹子建曰：人各有好尚。蘭茝孫蕙之芳，眾人所好，而海畔有逐臭之夫；鹹池六英之發，眾人所樂，而墨子有非之之論。豈可同哉？語曰：以心度心，閒不容針。孔子曰：其恕乎？己所不欲，勿施於人。","sortOrder":31},
  {"id":"s_work_tdk_3_32","chapterId":"ch_work_tdk_3","text":"《管子》曰：廪實知禮節，衣食足知榮辱。古語曰：貴不與驕期而驕自至，富不與侈期而侈自來。","sortOrder":32},
  {"id":"s_work_tdk_3_33","chapterId":"ch_work_tdk_3","text":"語曰：忠無不報。《左傳》曰：亂代則讒勝直。","sortOrder":33},
  {"id":"s_work_tdk_3_34","chapterId":"ch_work_tdk_3","text":"《韓子》曰：凡人之大體，取舍同則相是，取舍異則相非。《易》曰：同聲相應，同氣相求。水流濕，火就燥。雲從龍，風從虎。《易》曰：二女同居，其志不同。語曰：一栖兩雄，一泉無二蛟。又曰：凡人情以同妒。故曰：同美相妒，同貴相害，同利相忌。","sortOrder":34},
  {"id":"s_work_tdk_3_35","chapterId":"ch_work_tdk_3","text":"《韓子》曰：釋法術而以心理，尧舜不能正一國；去規矩而以意度，奚仲不能成一輪。使中主守法術、拙匠執規矩，則萬不失矣。《淮南子》曰：夫矢之所以射遠貫堅者，弓弩力也；其所以中的剖微者，人心也。賞善罰暴者，政令也；其所以行者，精誠也。故弩雖強，不能獨中；令雖明，不能獨行。杜恕曰：世有亂人，而無亂法。若使法可专任，則唐、虞不須稷、契之佐，殷、周無貴伊、呂之辅矣。","sortOrder":35},
  {"id":"s_work_tdk_3_36","chapterId":"ch_work_tdk_3","text":"慮不先定，不可以應卒；兵不先辦，不可以應敵。《左傳》曰：豫備不虞，故之善政。《左傳》曰：士蒍謂晉侯曰：臣聞之，無丧而戚，忧必仇之；無戎而城，仇必保焉。《春秋外傳》曰：周景王將鑄大錢，单穆公曰：不可。古者天灾降戾，於是乎量資幣、權輕重，以振救人。夫備預，有未至而設之，有至而後救之，是不相入也。可先而不備，謂之怠；可後而先之，謂之召灾。周固瀛國也，天未厭禍焉，而又離人以佐灾，無乃不可乎？","sortOrder":36},
  {"id":"s_work_tdk_3_37","chapterId":"ch_work_tdk_3","text":"《左傳》曰：古人有言：一日縱敵，數代之患也。晉楚遇於鄢，范文子不欲戰，曰：吾先君之亟戰也有故。秦、狄、齊、楚皆強，不盡力，子孫將弱。今三強服矣。敵，楚而已。唯聖人能內外無患。自非聖人，外寧必有內忧。盍釋楚以為外懼乎？","sortOrder":37},
  {"id":"s_work_tdk_3_38","chapterId":"ch_work_tdk_3","text":"《三略》曰：無使仁者主财，為其多恩施而附於下。陶朱公中男殺人，囚於楚。朱公欲使其少子，裝黃金千镒，往视之。其長男固請，乃使行。楚殺其弟。朱公曰：吾固必殺其弟。是長與我俱，見苦為生之難，故重其财。如少弟先見我富，乘堅驅良，逐狡兔，豈知财所從來？固輕弃之。今長者果殺其弟，事理然也，無足悲。","sortOrder":38},
  {"id":"s_work_tdk_3_39","chapterId":"ch_work_tdk_3","text":"語曰：祿薄者不可與入亂，賞輕者不可與人難。《慎子》曰：先王見不受祿者，不臣；祿不厚者，不與入難。田单將攻狄，見魯仲子。仲子曰：將軍攻狄，弗能下也。何者？昔將軍之在即墨，坐而織蕢，立而杖插，為士卒佳，此所以破燕。今將軍東有液邑之奉，西有蕢上之娱，黃金橫帶，而馳乎淄渑之間，有生之樂，無死之心，所以鳥也。後果然。","sortOrder":39},
  {"id":"s_work_tdk_3_40","chapterId":"ch_work_tdk_3","text":"語曰：貧賤之交不可忘，糟糠之妻不下堂。語曰：交接廣而信衰於友，爵祿厚而忠衰於君。","sortOrder":40},
  {"id":"s_work_tdk_3_41","chapterId":"ch_work_tdk_3","text":"《春秋後語》曰：楚春申君使孫子為宰，客有說春申君曰：湯以毫，武王以鄗，皆不過百里，以有天下。今孫子賢人也，而君藉之百里之势，臣竊為君危之。春申君曰：善。於是使人謝孫子。孫子去之趙，趙以為上卿。客又說春申君曰：昔伊尹去夏入殷，殷王而夏亡；管仲去魯八齊，魯弱而齊強。夫賢者之所在，其君未嘗不尊，其國未嘗不榮也。今孫子賢人也，君何為辭之？春申君又曰：善。复使人請孫子。","sortOrder":41},
  {"id":"s_work_tdk_3_42","chapterId":"ch_work_tdk_3","text":"韓宣王謂扔留曰：吾兩欲用公仲、公叔，其可乎？對曰：不可。晉用六卿而國分，簡公用田成、阚止而簡公弒，魏兩用犀首、張儀而西河之外亡。今王兩用之，其多力者，內树其党；其寡力者，又籍於外權。群臣或內树其党，以擅王命；或外為势交，以裂其地，則王之國危矣。又曰：公孫衍為魏將，與其相田需不善。季文子為衍說魏王曰：王獨不見夫服牛驂骥乎？不可百步。今王以衍為可使將，固用之也。而聽相之計，是服牛驂骥之道。牛馬俱死而不成其功，則王之國傷矣。願王察之。《傅子》曰：天地至神，不能同道而生萬物；聖人至明，不能一檢而治百姓。故以異致同者，天地之道也；因物製宜者，聖人之治也。既得其道，雖有相害之物，不傷乎治體矣。水火之性，相滅也。善用之者，陳鼎釜乎其閒，爨之煮之，而能兩盡其用，不相害也。天下之物，為水火者多矣，何忧乎相害？何患乎不盡其用也？《易》曰：天地睽而其事同也，男女睽而其志通也，萬物睽而其事類也。","sortOrder":42},
  {"id":"s_work_tdk_3_43","chapterId":"ch_work_tdk_3","text":"陳登為呂布說曹公曰：養呂布，譬如養虎，常須飽其肉，不飽則噬人。曹公曰：不似卿言。譬如養鷹，飢則為人用，飽則颺去。","sortOrder":43},
  {"id":"s_work_tdk_3_44","chapterId":"ch_work_tdk_3","text":"劉備來奔曹公，曹公以之豫州牧。或謂曹公曰：備有雄志，今不早圖，後必為患。曹公以問郭嘉。嘉曰：有是。然公提劍起義兵，為百姓除暴，推誠仗信，以召雋桀，猶懼其未來也。今備有英雄之名，以窮歸已而害之，以害賢為名，則智士將自疑，回心擇主，公誰與定天下者？夫除一人之患，以沮四海之望，安危之機，不可不察。曹公曰：善。《傅子》稱郭嘉言於太祖曰：備有雄志而甚得眾心。關羽、張飛，皆萬人之敵也，為之死用。以嘉觀之，其謀未可测也。古人有言曰：一日縱敵，數世之患。宜早為之所。曹公方招懷英雄，以明大信，未得從嘉謀。","sortOrder":44},
  {"id":"s_work_tdk_3_45","chapterId":"ch_work_tdk_3","text":"《家語》曰：子路問孔子曰：請釋古之道，而行由之意，可乎？子曰：不可也。昔東夷慕諸夏之禮，有女而寡，為內私婿，終身不嫁。不嫁則不嫁矣，然非貞節之義矣。仓吾娆取妻而美，讓與其兄，讓則讓矣，然非禮酿之讓也。今子欲舍古之道而行子之意，庸知子意以非為是乎？語曰：变古亂常，不死則亡。《書》雲：事弗師古，以克永代，匪說攸閒。趙武靈王欲胡服，公子成不悅。靈王曰：夫者所以便用，禮者所以便事。聖人觀乡而順宜，因事而製禮，所以利其人而厚其國。夫剪發文身，错臂左衽，甌越之人也；黑齒雕題，鳀冠秫縫，犬戎之國也。故禮服莫同，而其便一也。乡異而用变，事異而禮易。是以聖人謀可以利其國，不一其用；謀可以便其禮，不法其故。儒者一師而俗異，中國同禮而離教，况於山穀之便乎？故去就之变，智者不能一；遠邇之服，賢聖莫能同。窮乡多異俗，曲學多殊辯。今叔父之言，俗也；吾之所言，以製俗也。叔父惡变服之名，以忘效事之實，非寡人之所望也。公子成遂胡服。","sortOrder":45},
  {"id":"s_work_tdk_3_46","chapterId":"ch_work_tdk_3","text":"移風易俗，莫善於樂。《孟子》曰：天道因則大，化則細。因也者，因人之情也。","sortOrder":46},
  {"id":"s_work_tdk_3_47","chapterId":"ch_work_tdk_3","text":"李尋曰：夫以喜怒賞誅，而不顧時禁，雖有尧舜之心，猶不能致和平。善言古者，必有效於今；善言天者，必有徵於人。設上農夫欲令冬田，雖肉袒深耕，汗出种之，猶不生者，非人心不至，天時不得也。《易》曰：時止則止，時行則行，動靜不失於時，其道光明。《書》曰：敬授人時。故古之王者，尊天地、重陰陽、敬四時月令、順之以善政，則和氣可立致，猶抱鼓之相應也。太公謂武王曰：天無益於兵，勝而將所居者九。曰法令不行而任侵誅，無德厚而日月之數，不順敵之強弱而幸於天，無智慮而候氛氣，少勇力而望天福，不知地形而歸過於時，敵人怯弱、不敢墼而信龟策，士卒不勇而法鬼神，設伏不巧而任背向之道。凡天地鬼神，视之不見，聽之不聞，不可以决勝败，故明將不法。司馬遷曰：陰陽之家，使人拘而多忌。范晔曰：陰陽之道，其弊也巫。翼奉曰：治道之要，在知下之邪正。人誠向正，雖愚為用；若其懷邪，智益為害。夫人主莫不愛己也。莫知愛己者，不足愛也。故桓子曰：捕猛獸者，不令美人舉手；釣旦魚者，不使稚子輕預。非不親也，力不堪也。奈何萬乘之主，而不擇人哉？故曰：夫犬之為猛，有非則鳴吠，而不遑於夙夜。此自效之至也。昔宋人有沽酒者，酒酸而不售。何也？以有猛犬之故。夫犬知愛其主，而不能為其主慮酒酸之患者，智不足也。","sortOrder":47},
  {"id":"s_work_tdk_3_48","chapterId":"ch_work_tdk_3","text":"語曰：巧诈不如拙誠。晉惠帝為太子，和峤諫武曰：季世多伪，而太子尚信，非四海之主，忧不了陛下家事。武帝不從。後惠帝果败。","sortOrder":48},
  {"id":"s_work_tdk_3_49","chapterId":"ch_work_tdk_3","text":"《左傳》曰：孔子叹子產曰：言以足志，文以足言。不言，誰知其志？言之無文，行而不遠。晉為伯，鄭人陳，非文辭不為功。慎辭也哉！《論語》曰：誦《詩》三百，授之以政，不達；使於四方，不能专對。雖多，亦奚以為？漢文帝登虎圈，美啬夫口辯，拜為上林令。張釋之前曰：陛下以絳侯周勃，何如人也？上曰：長者。又問曰：東楊侯張相如，何如人也？上复曰：長者。釋之曰：此兩人言事，曾不能出口。豈效此啬夫喋喋、利口捷給哉？且秦以任刀筆之吏，爭以亟疾苛察相高，然其弊，徒文具耳。亡惻隱之實，以故不聞其過，陵遲至於二世，天下土崩。今陛下以啬夫口辭而超遷之，臣恐天下隨風而靡，爭口辯，無其實。且下之化上，疾於影响，舉错之閒，不可不審。帝乃止。","sortOrder":49},
  {"id":"s_work_tdk_3_50","chapterId":"ch_work_tdk_3","text":"太史公曰：《春秋》推見至隱，《易》本隱以之顯。《大雅》言王公大人，而德逮黎庶。《小雅》譏已之得失，其流及上。所言雖殊，其合德一也。相如虛辭濫說，然其要歸，引之節俭，此與《詩》之諷諫何異？扬雄以為賦者，將以諷也，必推類而言，極麗靡之辭，閎侈鉅衍，競於使人不能加也，既乃歸之於正，然覺者已過矣。往時武帝好神仙，相如上《大人賦》，欲以諷帝。帝反縹縹有凌雲之志。由是言之，賦勸而不止，明矣！又頗類俳優，非法度所存。賢人君君子，詩賦之正也。","sortOrder":50},
  {"id":"s_work_tdk_3_51","chapterId":"ch_work_tdk_3","text":"《淮南子》曰：東海之魚名鰈，比目而行；北方有獸，名曰娄更，食更候；南方有鳥，名曰鶼，比翼而飛。夫鳥獸魚鰈，猶知假力，况萬乘之主乎？獨不知假天下之英雄俊士，與之為伍，豈不痛哉？狐卷子曰：父賢不過尧而丹朱放，兄賢不過周公而管蔡誅，臣賢不過湯武而紂伐。况君之欲治，亦須從身始，人何可恃乎？","sortOrder":51},
  {"id":"s_work_tdk_3_52","chapterId":"ch_work_tdk_3","text":"孔子曰：不患無位，患己不立。孔子厄於陳蔡，子路慍見曰：昔聞諸夫子：積善者，天報以福。今夫子積義懷仁久矣，奚居之窮也？子曰：由！未之識也。吾語汝：以仁者為必信耶？則伯夷叔齊為不饿首陽；汝以智者為必用耶？則王子比幹不見剖心；汝以忠者為必報耶？則關龍逢不見刑；汝以諫者為必聽耶？耶伍子胥不見殺。夫遇不遇者，時也；賢不肖者，才也。君子博學深謀而不遇時者眾矣，何獨仁哉？","sortOrder":52},
  {"id":"s_work_tdk_3_53","chapterId":"ch_work_tdk_3","text":"神農形悴，唐尧瘦臞，舜黎黑，禹胼胝，伊尹負鼎而幹湯，呂望鼓刀而入周，墨翟無黔突，孔子無暖席，非以貪祿位，將欲下之利，除萬人之害。李斯以書對秦二世雲：中子曰：有天下而不恣睢，命之曰以天下桎，若尧禹然，故謂之桎也。夫以人徇己，則己貴而人賤；以己徇人，則己賤而人貴。故徇人者賤，而所徇者貴。自古及今，未有不然。夫尧禹以身徇天下，謂之桎者，不亦宜乎？","sortOrder":53},
  {"id":"s_work_tdk_3_54","chapterId":"ch_work_tdk_3","text":"《論語》曰：舉逸人，天下人歸心焉！魏文侯受藝於子夏，敬段幹木，過其庐，未嘗不式。於是秦欲伐魏，或曰：魏君賢，國人稱仁，上下和洽，未可圖也。秦王乃止。由此得譽於諸侯。《韓子》曰：夫馬似鹿，此馬直千金。今有千金之馬，而無一金之鹿者，何也？馬為人用，而鹿不為人用。今處士不為人用，鹿類也。所以太公至齊而斬華士，孔子為司寇而誅少正卯。趙主父使李疵视中山可攻否，還報曰：可攻也。其君好見巖穴之士、布衣之人。主父曰：如子之言，是賢君也，安可攻？李疵曰：不然。上顯巖穴之士，則戰士殆；上尊學者，則農夫惰。農夫惰則國貧，戰士殆則兵弱。兵弱於外，國貧於內，不亡何待？主父曰：善。遂滅中山。","sortOrder":54},
  {"id":"s_work_tdk_3_55","chapterId":"ch_work_tdk_3","text":"《漢書》曰：陳平雲：吾多陰謀，道家所禁。吾世即废亡已矣，終能复起，以吾多陰禍也。其後元孫坐酎金失侯。後漢范晔論耿弇曰：三代為將，道家所忌。而耿氏累葉以功名終，將用其兵，欲以殺止殺乎？何其獨能崇也？","sortOrder":55},
  {"id":"s_work_tdk_3_56","chapterId":"ch_work_tdk_3","text":"《易》曰：崇高莫大於富貴。又曰：聖人之大寶曰位。孫子為書謝春申君曰：鄙諺曰：厲人怜王。此不恭之言也。雖然，古無虛諺，不可不審察也。此為殺死亡之主言也。夫人主年少而矜材，無法術以知奸，則大臣主斷圖私，以禁誅於已也。故殺賢長而立幼弱，废正嫡而立不義，《春秋》戒之。曰：楚王子围聘於鄭，未出境，聞王病，反問病，遂以冠纓絞王殺之，因自立也。齊崔杼之妻美，莊公通之。崔杼率其党而攻莊公，莊公走出，逾於外牆，射中其股，遂殺之，而立其弟。近代李兑用趙，饿主父於沙丘，百日而殺之。淖齒用齊，擢闵王之筋，懸於廟梁，宿昔而死。夫厲雖肿胞之疾，上比前代，未至絞纓射股也；下比近代，未至擢筋饿死也。夫殺死亡之主，心之忧勞、形之困苦，必甚於厲矣。由此觀之，厲雖怜王，可也。","sortOrder":56},
  {"id":"s_work_tdk_3_57","chapterId":"ch_work_tdk_3","text":"《易》曰：備物致用。立成器之以為天下利者，莫大於聖人。《莊子》曰：聖人不死，大盜不止。雖重聖人而治天下，則是重利盜跖也。為之斗斛以量之，則併與斗斛竊之；為之權衡以稱之，則併與權衡而竊之；為之符玺以信之，則併符玺而竊之；為之仁義以教之，則併仁義而竊之。何以知其然耶？彼竊鉤者誅，竊國者為諸侯。諸侯之門，而仁義存焉。則非竊仁義聖智耶？故逐於大道。揭諸侯，竊仁義，併斗斛權衡符玺之利，雖有軒晚之賞弗能勸，斧鉞之威弗能禁。此重利盜跖，而使不可禁者，是乃聖人之過也。故曰：國之利器，不可以示人。彼聖人者，天下之利器也，非所以明天下也。","sortOrder":57},
  {"id":"s_work_tdk_3_58","chapterId":"ch_work_tdk_3","text":"《論語》曰：君子固窮，小人窮濫矣。《易》曰：窮則变，通則久。是以自天祐之，吉無不利。太史公曰：鄙人有言：何知仁義？已饗其利者為有德。故伯夷丑周，饿死首陽山，而文武不以其故貶王；跖蹻暴戾，其徒誦義無窮。由此觀之，竊鉤者誅，竊國者為諸侯。諸侯之門，仁義存焉。非虛言也！今拘學成抱咫尺之義，久孤於代，豈若卑論儕俗，與代沈浮而取榮名哉？","sortOrder":58},
  {"id":"s_work_tdk_3_59","chapterId":"ch_work_tdk_3","text":"東平王蒼曰：為善最樂。語曰：時不與善，己獨由之。故曰：非妖則妄。","sortOrder":59},
  {"id":"s_work_tdk_3_60","chapterId":"ch_work_tdk_3","text":"庞統好人倫，勤於長養，每所稱述，多過於才。時人怪而問之，統曰：當今天下大亂，正道凌遲，善人少而惡人多。方欲興風俗，長道業，不美其談，則聲名不足慕也。不足慕，企而為善者少矣。今拔十失五，猶得其半，而可以崇邁代教，使有志者自励，不亦可乎？《人物志》曰：君子知損之為益，故功一而美二；小人不知自益之為損，故伐一而併失。由此觀之，則不伐者，伐之也；不爭者，爭之也；讓敵者，勝之也。是故卻至上人，而柳下滋甚；王叔好爭，而終於出奔。蔺相如以回車取勝於廉頗，寇恂以不斗取賢於贾复。物势之反，乃君子所謂道也。","sortOrder":60},
  {"id":"s_work_tdk_3_61","chapterId":"ch_work_tdk_3","text":"《孝經》曰：居家理，治可移於官。郦生落魄，無以為衣食業。陳蕃雲：大丈夫當扫天下，誰能扫一室？","sortOrder":61},
  {"id":"s_work_tdk_3_62","chapterId":"ch_work_tdk_3","text":"公孫宏曰：力亍近乎仁，好問近乎智，知恥近乎勇。知此三者，知所自理。知所以自理，然後知所以理人。天下未有不能自理，而能理人者也。此百代不移之道。《淮南子》曰：夫審於毫釐之計者，必遺天下之數；不失小物之選者，惑於大事之舉。今人才有欲平九州、存危國，而乃责之以閨閤之禮，修乡曲之俗，是猶以斧鬋毛、以刀伐木，皆失其宜矣。","sortOrder":62},
  {"id":"s_work_tdk_3_63","chapterId":"ch_work_tdk_3","text":"商鞅謂趙良曰：子之觀我理秦，孰與五羖大夫賢乎？趙良曰：夫五羖大夫，荆之鄙人也。聞缪公之賢，而願望見，行而無資，自鬻於秦客，披竭飯牛。缪公知之，舉之牛口之下，而加之百姓之上，秦國莫敢望焉！今君之見秦王也，因嬖人景監以為主，非所以為名也。《史記》曰：蔺相如因宦者缪賢見趙王。又曰：邹衍作《談天論》，其語閎大不經，然王公大人尊禮之。適梁，梁惠王郊迎，執賓主之禮。如燕，昭王擁篲先驅。豈與仲尼色陳蔡、孟軻困於齊梁同乎哉？衛靈公問陣於孔子，孔子不答。梁惠王謀攻趙，孟軻稱大王去邠。持方柄欲納圜凿，其能入乎？或曰：伊尹負鼎而辅湯以王。百里奚飯牛，缪公用霸。作先合，然後引之大道。邹衍其言雖不軌，亦將有牛鼎之意乎？","sortOrder":63},
  {"id":"s_work_tdk_3_64","chapterId":"ch_work_tdk_3","text":"陳仲舉體氣高烈，有王臣之節；李元禮忠平正直，有社之能。陳留蔡伯喈以仲舉強於犯上，元禮長於接下，犯上為難，接下為易，宜先仲舉而後元禮。姚信雲：夫皋陶戒舜，犯上之徵也；舜理百揆，接下之效也。故陳平謂王陵，言面折庭靜，我不如公；至安劉氏，公不如我。若犯上為優，是王陵當高於良平、朱雲當勝於吳邓乎？","sortOrder":64},
  {"id":"s_work_tdk_3_65","chapterId":"ch_work_tdk_3","text":"《史記》曰：韓子稱儒者以文亂法，而俠士以武犯禁。二者皆譏，而學士多稱於世。至如以術取宰相卿大夫，辅翼其世主，固無可言者。及若季次、原憲，讀書懷獨行，議不苟合當世，當世亦笑之。今遊俠，其行雖不軌於正義，然其言必信，其行必果，已诺必誠，不愛其軀，赴士之厄困，羞伐其德，蓋亦有足多者。且缓急人之所時有也，虞舜於井廪，伊尹負鼎俎，傅說匿於傅险，呂尚困於棘津，夷吾桎梏，百里奚飯牛，仲尼厄匡、蔡色陳蔡。此皆學士所謂有道仁人也，猶遭此菑，况以以中材而涉近代之末流乎？其遇害何可勝哉？而布衣之徒，設取予然诺，千里誦義，故士窮窘而得委命。此豈非人之所謂賢豪者耶？誠使乡曲之俠，與季次、原憲七權量力，效功於當代，不同日而論矣。曷足小哉？《漢書》曰：天子建國，諸侯立家。自卿大夫以至庶人，各有等差。是以人服事其上，而下無凯觎。孔子曰：天子有道，政不在大夫。百官有司，奉法承令，以脩所職。越職有誅，侵官有罰，故上下相順，而庶事理焉。周室既微，禮樂征伐出自諸侯。桓、文之後，大夫世權，陪臣執命。陵夷至於戰國，合縱連橫，力政爭強。由是列國公子，魏有信陵，趙有平原，齊有孟嘗，楚有春申，皆籍王公之势，為遊俠；雞鳴狗盜，無不賓禮。而趙木相虞卿，弃國捐君，以固窮交魏齊之厄；信陵無忌，竊符矯命，殺將专師，以赴平原之急，皆以取重諸侯，彰名天下，扼腕而遊，談者以四豪稱首。於是背公死党之議成，守職奉上之義废矣。及至漢興，禁網疏闊，未之匡改也。魏其、武安之屬，競逐於京師；郭解、剧孟之徒，馳鶩於闾阎，權行州域，力折公侯，眾庶榮其名跡，觊而慕之。雖陷刑辟，自與殺身成名，若季路、仇牧，死而不悔也。曾子曰：上失其道，人散久矣。非明王在上，示之好惡，齊之以禮法，人曷由知禁而反正乎？古之正法：五伯，三王之罪人也；而六國，五伯之罪人也。夫四豪者，六國之罪人也。况於郭解之倫，以匹夫之細微，竊殺生之權？其罪也，不容於誅矣。","sortOrder":65},
  {"id":"s_work_tdk_3_66","chapterId":"ch_work_tdk_3","text":"《尸子》曰：人臣者，以進賢為功；人主者，以用賢為功也。《史記》曰：鮑叔舉管仲，天下不多管仲之賢，而多鮑叔能知人也。蘇建常责大將軍青，至重而天下之賢士人夫毋稱焉，願觀古今名稱所招擇賢者。大將軍謝曰：自魏其、武安之厚賓客，天子嘗切齒。彼親附士大夫，招賢黜扒肖者，人主之柄也。人臣奉法遵職而已，何與招士？其為將如此。","sortOrder":66},
  {"id":"s_work_tdk_3_67","chapterId":"ch_work_tdk_3","text":"班固雲：昔王道既微，諸侯力政，時君世主，好惡殊方。是以諸家之術，蜂起併作，各引一端，崇其所善，以此馳說，取合諸侯。其言雖殊，譬猶水火相滅，亦能相生也。仁之與義，敬之與和，事雖相反，而皆相成也。《易》曰：天下同歸而殊途，一致而百慮。此之謂也。","sortOrder":67},
  {"id":"s_work_tdk_3_68","chapterId":"ch_work_tdk_3","text":"適变第十五","sortOrder":68},
  {"id":"s_work_tdk_3_69","chapterId":"ch_work_tdk_3","text":"昔先王當時而立法度，務而製事，法宜其時則理，事適其務故有功。今時移而法不变，務易而事以古，是則法與時诡，而時與務易。是以法立而時益亂，為而事益废。故聖人之理國也，不法古，不脩今，當時而立功，在難而能免。由是言之，故知若人者，各因其時而建功立德焉！何以知其然耶？","sortOrder":69},
  {"id":"s_work_tdk_3_70","chapterId":"ch_work_tdk_3","text":"桓子曰：三皇以道治，五帝用德化，三皇由仁義，五霸用權智。五帝以上久遠，經傳無事，唯王霸二盛之美，以定古今之理焉。夫王道之治，先除人害，而足其衣食，然後教以禮儀，而威以刑誅，使失好惡去就。是故大化四凑，天下安樂。此王者之術。霸功之大者，尊君卑臣，權統由一，政不二門，賞罰必信，法令著明，百官脩理，威令必行。此霸者之術。《道德經》曰：我無為而人自化。《文子》曰：所謂無為者，非謂引之不來、推之不往，謂其循理而舉事、因資而立功、推自然之势也。故曰：湯武聖主也，而不能與越人乘舲舟、泛江湖；伊尹賢相也，而不能與胡人騎原馬、服騶駼；孔墨博通也，而不能與山居者入榛薄、出险阻。由是觀之，人智之於物淺矣，而欲以炤海內、存萬方，不因道里之數，而专己之能，則其窮不遠。故智不足以為理，勇不足以為強，明矣！然而君人者在廟堂之上、而知四海之外者，因物以識物，因人以知人也。夫冬日之陽、夏日之陰，萬物歸之，而莫之使。至精之感，弗召自來。待目而昭見，待言而使令，其於理難矣。皋陶喑而為大理，天下無虐刑；師曠瞽而為太宰，晉國無亂政。不言之令、不视之見，聖人所以為師，此黃老之術也。","sortOrder":70},
  {"id":"s_work_tdk_3_71","chapterId":"ch_work_tdk_3","text":"孔子閒居，謂曾參曰：昔者明王內脩七教，外行三至，七教修而可以守，三至行而可以征。明王之守也，則必折冲千里之外；其征也，還師衽席之上。曾子曰：敢問七教。孔子曰：上敬老則下益孝，上敬齒則下益悌，上樂施則下益亮，上親賢則下擇交，上好德則下無隱，上惡貪則下恥爭，上廉讓則下知節，此之謂七教也。昔明王之治人也，必裂而封之，分屬而理之，使之有司月省而時考之。進賢良，退不肖，哀鳏寡，養孤獨，恤貧窮，誘孝悌，選才能，此七者修，則四海之內，無刑人矣。上之親下也如腹心，則下之親上也，如幼子之於慈母矣；其於信也如四時，而人信之也，如寒暑之必验。故视遠若邇，非道邇也，見明德也。是以兵革不動而威，用利不施而親，此之謂明王之守、折冲千里之外者也。曾子曰：何謂三至？孔子曰：至禮不讓，而天下理；至賞不費，而天下之士悅；至樂無聲，而天下之人和。何則？昔者明王必盡知天下良士之名。既知其名，又知其實。既知其實，然後因天下之爵以尊之，此謂至禮不讓而天下治。因天下之祿，以富天下之士，此之謂至賞不費而天下之士悅。如此則天下之明譽興焉，此謂之至樂無而天下之人和。故仁莫大於愛人，智者莫大於知賢，政者莫大於能官。有德之君，修此三者，則四海之內供命而已矣。此之謂折冲千里之外。故曰：明王之征，猶時雨之降，至則悅矣。此之謂還師衽席之上。故扬雄曰：六經之理，貴於未亂；兵家之勝，貴次未戰。此孔氏之術也。","sortOrder":71},
  {"id":"s_work_tdk_3_72","chapterId":"ch_work_tdk_3","text":"《墨子》曰：古之人未知宮室，就陵阜而居，穴而處。故聖王作，為宮室。為宮室之法：高足以避润濕，邊足以圉風寒，宮牆之高足以別男女之禮，謹此則止，不以為觀樂也。故天下之人，财用可得而足也。當今之王為宮室，則與此異矣。必厚斂於百姓，以為宮室台榭曲直之望、青黃刻鏤之飾。為宮室若此，故左右皆法而象之，是以财不足以待凶飢、振孤寡，故國貧而難理也。為宮室不可不節。古之人未知為衣服時，衣皮帶茭，冬則不輕而暖，夏則不輕而清。聖王以為不中人之情，故聖人作，誨婦人，以為人衣。為衣服之法：冬則練帛，足以為輕暖；夏則絺绤，足以為輕清，謹此則止，非以榮耳目、觀愚人也。是以其人用俭約而易治，其君用财節而易贍也。當今之王，其為衣服，則與此異矣。必厚斂於百姓，以為文彩靡曼之衣，鑄金以為鉤，珠玉以為佩。由此觀之，其為衣服，非為身體，此為觀好也。是以其人淫僻而難治，其君奢侈而難諫。夫以奢侈之君，御淫僻之人，欲國無亂，不可得也。為衣服不可不節。此墨翟之術也。","sortOrder":72},
  {"id":"s_work_tdk_3_73","chapterId":"ch_work_tdk_3","text":"商子曰：法令者，人之命也，為治之本。一兔走，百人逐之，非以兔可分為百，由名分之未定也。賣兔滿市，盜不敢取者，由名分之定也。故名分未定，雖尧、舜、禹、湯，且皆加務而逐之；名分已定，則貧不敢取。故聖人之為法令也、置官也、置吏也，所以定分也。名分定，則大诈貞信、巨盜願悫，而各自治也。《申子》曰：君如身，臣如手。君設其本，臣操其末。為人君者，操契以责其名。名者，天地之網，聖人之符。張天地之網，用聖人之符，則萬物無所逃矣。動者搖，靜者安，名自名也，事自定也。是以有道者，因名而正之，隨事而定之。昔者尧之治天下也，以名，其名正則天下治。桀之治天下也，亦以名，其名倚而天下亂。是以聖人貴名之正也。李斯書曰：韓子稱慈母有败子、而嚴家無格虜者，何也？則罰之加焉必也。故商君之法，刑弃灰於道者。夫弃灰薄罪也，而被刑重罰也。夫輕罪具督，而况有重罪乎？故人弗敢犯矣。今不務所以不犯，而事慈母之所以败子，則亦不察於聖人之論矣。此商鞅、申、韓之術也。","sortOrder":73},
  {"id":"s_work_tdk_3_74","chapterId":"ch_work_tdk_3","text":"由是觀之，故知治天下者，有王霸焉，有黃老焉，有孔墨焉，有申商焉，此其所以異也。雖經緯殊致，救弊不同，然康濟群生，皆有以矣。今議者或引長代之法，語救弊之言；或引帝王之風，譏霸者之政，不論時变，而以飾說。故是非論，紛然作矣。言伪而辯，順非而泽，此罪人也。故君子禁之。","sortOrder":74},
  {"id":"s_work_tdk_3_75","chapterId":"ch_work_tdk_3","text":"正論第十六","sortOrder":75},
  {"id":"s_work_tdk_3_76","chapterId":"ch_work_tdk_3","text":"孔子曰：六藝於理一也，《禮》以節人，《樂》以發和，《書》以导事，《詩》以達意，《易》以道化，《春秋》以道義。故曰：入其國，其教可知也。其為人也，溫柔敦厚，《詩》教也；疏通知遠，《書》教也；廣博易良，《樂》教也；絜靜精微，《易》教也；恭俭莊敬，《禮》教也；屬辭比事，《春秋》教也。故《詩》之失愚，《書》之失誣，《樂》之失奢，《易》之失賊，《禮》之失煩，《春秋》之失亂。其為人也，溫柔敦厚而不愚，則深於《詩》也；疏通知遠而不誣，則深於《書》也；廣博易良而不奢，則深於《樂》也；絜净精微而不賊，則深於《易》也；恭俭莊敬而不煩，則深於《禮》也；屬辭比事而不亂，則深於春秋也。","sortOrder":76},
  {"id":"s_work_tdk_3_77","chapterId":"ch_work_tdk_3","text":"自仲尼没而微言絕，七十子丧而大義乖，戰國縱橫，真伪分爭，諸子之言，紛然散亂矣。","sortOrder":77},
  {"id":"s_work_tdk_3_78","chapterId":"ch_work_tdk_3","text":"儒家者，蓋出於司徒之官，人君順陰陽、明教化者也。遊文於六經之中，留意於仁義之际，祖述尧舜，憲章文武，宗師仲尼，此其最高也。然惑者既失精微，而僻者又隨時抑扬，违離道本，苟以哗眾取寵，此僻儒之患也。道家者，蓋出於史官，歷紀成败，秉要執本，清虛以自守，卑弱以自持，此君人南面者之術也。合於尧之克讓、《易》之謙謙，此其所長也。及放者為之，則欲絕去禮樂、兼弃仁義，獨任清虛，何以為治？此道家之弊也。","sortOrder":78},
  {"id":"s_work_tdk_3_79","chapterId":"ch_work_tdk_3","text":"陰陽家者，蓋出於羲和之官，敬順昊天，歷象日月星辰，敬授人時，此其所長也。及拘者為之，則牵於禁忌，泥於小數，舍人事而任鬼神，此陰陽之弊也。","sortOrder":79},
  {"id":"s_work_tdk_3_80","chapterId":"ch_work_tdk_3","text":"法家者，蓋出於理官，信賞必罰，以辅禮製，此其所長也。及刻者為之，則亡教化，去仁愛，专任刑法，而欲以致治，至於殘賊至親，傷恩薄厚，此法家之弊也。","sortOrder":80},
  {"id":"s_work_tdk_3_81","chapterId":"ch_work_tdk_3","text":"名家者，蓋出於禮官。古者名位不同，禮亦異數。孔子曰：必也正名乎！此其所長也。及繳者為之，則鉤鈲析亂而已，此名家之弊也","sortOrder":81},
  {"id":"s_work_tdk_3_82","chapterId":"ch_work_tdk_3","text":"黑家者，蓋出於清廟之官，茅屋采椽，是以貴俭；養三老五更，是以兼愛；選士大射，是以上賢；宗祀嚴父，是以右鬼；順四時而行，是以非命；以孝示天下，是以上同，此其所長也。及蔽者為之，見俭之利，因以非禮，推樂愛之意，而不知別親疏，此墨家之弊也。","sortOrder":82},
  {"id":"s_work_tdk_3_83","chapterId":"ch_work_tdk_3","text":"縱橫家者，蓋出於行人之官。孔子曰：使乎使乎！言當權事製宜，受命不受辭，此其所長也。及邪人為之，則上诈谖而弃其信，此縱橫之弊也。","sortOrder":83},
  {"id":"s_work_tdk_3_84","chapterId":"ch_work_tdk_3","text":"雜家者，蓋出於議官，兼儒墨，合名法，知國體之有此，見王理之無貫，此其所長也。及荡者為之，則漫羨而無所歸心，此雜家之弊也。","sortOrder":84},
  {"id":"s_work_tdk_3_85","chapterId":"ch_work_tdk_3","text":"農家者，蓋出於農稷之官，播百穀，勸耕桑，以足衣食。孔子曰：所重人食。此其所長也。及鄙者為之，則欲君臣之併耕，悖上下之序，此農家之弊也。","sortOrder":85},
  {"id":"s_work_tdk_3_86","chapterId":"ch_work_tdk_3","text":"《文子》曰：聖人之從事也，所由異路而同歸。秦楚燕魏之歌，異轉而皆樂；九夷八狄之哭，異聲而皆哀。夫歌者，樂之微也；哭者，哀之效也。愔愔於中，而應於外，故在所以感之矣。","sortOrder":86},
  {"id":"s_work_tdk_3_87","chapterId":"ch_work_tdk_3","text":"論曰：范晔稱百家之言政者尚矣，大略歸乎寧固根柢、革易時弊也，而遭運無恒，意見偏雜，故是非之論，紛然相乖。嘗试論之：夫世非胥庭，人乖彀飲，理跡萬肇，情故萌生。雖周物之智，不能研其權变；山川之奧，未足况其紆险。則應俗適事，難以常條。何以言之？若夫元聖御代，則大同極軌。施舍之道，宜無殊典，而損益異運，文朴遞行。用明居晦，回穴於曩時；興戈陳俎，參考於上世。及至戴黃屋、服絺衣，丰薄不齊，而致治則一。亦有宥公族、黥國仇，宽躁已隔，而防非必同。此其分波而共源，百慮而一致者也。若篤偏情矯用，則枉直必過。故葛屦履霜，弊由崇俭；楚楚衣服，戒在窮奢。疏禁厚下，以尾大陵弱；斂威峻法，以苛薄分崩。斯曹、魏之刺，所以明乎《國風》；周、秦末軌，所以彰於微滅。故用舍之端，興败資焉。是以繁簡唯時，宽猛相濟。刑書镌鼎，事有可詳；三章在令，取貴能約。太叔致猛政之衰，國子流遺愛之涕，宣孟改冬日之和，平陽循畫一之法。斯實弛張之宏致，庶可以徵其統乎？數子之言，當世失得，皆悉究矣。然多谬通方之訓，好中一隅之說。貴清净者，以席上為腐議；束名實者，以枉下為誕辭。或推前王之風，可行於當年；有引救弊之規，宜流於長世。稽之篤論，將為蔽矣。由此言之，故知有法無法，因時為業。時止則止，時行則行，動不失其時，其道光明。非至精者，孰能通於变哉？","sortOrder":87},
  {"id":"s_work_tdk_3_88","chapterId":"ch_work_tdk_3","text":"《長短經》　唐　趙蕤","sortOrder":88},
  {"id":"s_work_tdk_4_1","chapterId":"ch_work_tdk_4","text":"卷四霸紀上","sortOrder":1},
  {"id":"s_work_tdk_4_2","chapterId":"ch_work_tdk_4","text":"霸圖第十七","sortOrder":2},
  {"id":"s_work_tdk_4_3","chapterId":"ch_work_tdk_4","text":"臣聞周有天下，其理三百餘年。成之隆也，刑错四十餘年而不用。及其衰也，亦三百餘年。故五伯更起。伯者常佐天子，興利除害，誅暴禁邪，匡正海內，以尊天子。五伯既没，賢聖莫續。天子孤弱，號令不行。諸侯恣行，強凌弱，眾暴寡。田常篡齊，六卿分晉，併為戰國，此人之始苦也。於是強國務攻，弱國務守，合縱連衡，馳車轂击，介胄生虮蝨，人無所告訴。及至秦蠶食天下，併吞戰國，一海內之政，坏諸侯之城，法嚴政峻，諂諛者眾，使蒙恬將兵北攻胡、尉他將卒以戍越，宿兵無用之地，人不聊生。始皇崩，天下大叛。陳勝、吳廣舉於陳，武臣、張耳舉於趙，項梁舉吳，田儋舉齊，景駒舉郢，周市舉魏，韓廣舉燕。窮山通穀，豪杰併起，而亡秦族矣。","sortOrder":3},
  {"id":"s_work_tdk_4_4","chapterId":"ch_work_tdk_4","text":"漢高祖名邦，字季，姓劉氏，沛國丰邑人，為泗上之亭長。秦二世元年，陳勝等起，勝自立為楚王。沛人殺其令，立高祖為沛公。時項梁止薛，沛公往從之，共立義帝。約曰：先入鹹陽者王之。秦將章邯，大败項梁於定陶。梁死，章邯以為楚不足忧，乃北伐趙。楚使項羽等救趙，遣市別將西入關。沛公遂攻宛，降之。攻武關，大破秦軍。入鹹陽，與秦人約法三章，遣兵拒關，欲王關中。是時項羽破秦軍於河北，率諸侯兵四十萬至鸿門，欲击沛公。沛公因項羽自解於羽。羽蒙遂殺子婴而東都彭城，立沛公為漢王、王巴漢。於是用韓信策，乃東伐，還定三秦。田榮怨項王之不己立，殺田市，自立為齊王。羽北击滅齊，而使九江王殺義帝於郴。漢王為之縞素發丧，臨三日，以告諸侯。漢王因項羽之击齊，率諸侯衣師五十六尤，東袭楚，破彭城。羽聞之，留其將击齊，自以精兵三萬歸击漢。漢王與羽大戰彭城下，漢王不利，出梁地。至虞，謂左右曰：孰能為使淮南王黥布，令發兵背楚，貿項王於齊數月。我之取天下，可以萬全。隨何乃使淮南，說布背楚。漢王如滎陽，使韓信击魏王豹，虜之。漢遂與楚相距於滎陽。楚围漢王，用陳平計，閒得出。入關收兵，欲复東，轅生說漢王出軍宛葉間，引項王南渡，使韓信等得集河北。羽兵果引兵南渡，如其策。韓信與張耳以兵數尤，東下井陉，击趙，破之。乃報漢，因請立張耳為趙王，以镇撫其國。漢王從之。十二月，漢王拒楚於成皋，享師欲复戰。郎中鄭忠說曰：王高壘深壁，勿與戰。使劉贾佐彭超入楚地，焚其積聚，破楚師必矣。項羽乃東击彭越，留曹咎守成皋。時漢數困滎陽成皋，計捐成皋以東，屯巩洛以距楚。用郦生計，复守成皋。羽初東，嘱曹咎曰：漢即挑戰，慎勿與戰，勺令漢得東而已。咎乃出戰死。漢王遂進兵取成皋。羽聞咎破，乃還軍廣武閒，為高壇，置太於其上。漢王遣侯公說羽，求太公。羽乃與漢約，中分天下，割鸿溝以西為漢、以東為楚，歸漢王父母及呂後。項王解而東。漢王欲西，張良曰：今漢有天下大半，而諸侯皆附，楚兵疲食盡，此天亡楚之時，不如因其東而取之。漢王乃追羽，與齊王韓信、魏相彭越期會击楚，皆不會。用張良計，信等皆引兵羽垓下，遂滅項氏。都洛陽，用娄敬策，徙都長安有告楚王韓信反，用陳平計擒之，废為准陰侯。陳豨為代相。與朝信、王黃等反，豨自立為代王。上自往破之。尉他王南越，反。高祖使陆贾賜尉他印綬，為南越王，令稱臣奉漢約。高祖在位十二年，崩，年六十二。惠帝立，呂後臨政。景帝時，吳楚反，征平之。崩，太子彻立。崩，子勿陵立。崩，立武帝孫昌邑王贺。废，立武帝曾孫詢。崩，立太子奭。崩，立太子驁。崩，立宣帝孫定陶恭王子欣。崩，立帝弟中山孝王衎。伪新室王莽者，成帝舅王曼之子，元帝王皇後之侄也。元帝崩，成帝即位，以元舅鳳為大司馬，兄弟五人皆為侯。曼早卒。鳳將薨，以莽讬太後，封為新都侯。五侯競為潛，起各第舍。莽幼孤貧，獨折節恭謹，當世名士，多為莽言。上由是賢之，拜為侍中。時帝废許後，立趙飛燕。飛燕女弟為昭儀。昭儀害後宮皇子，帝無嗣，乃立定陶王忻為皇太子。莽以發定陵侯淳於長大奸，拜為大司馬，時年三十八。成崩，哀帝即位，立皇後傅後，封後父傅晏為孔乡侯、帝母丁後曰恭皇太後、舅丁明為安陽侯。莽乞骸骨，避丁傅也。哀帝崩，時莽以侯在第。太皇太後令莽備佐丧事，复為大司馬，徵立中山王為帝。太皇太後臨朝，莽秉政，百官總己以聽於莽。平帝崩，莽徵宣帝玄孫廣成侯子婴立之，年三歲。遂謀居攝，如周公故事。東都太守翟義反，败死。莽自謂威德日盛，獲天人之助，用銅匮符命，遂即真。其九年，赤眉賊起。十四年，世祖起兵，與王匡等共立劉聖公為更始皇帝。莽遣王尋、王邑击更始，二公败於崑陽。漢兵遂入城中，人皆降。莽走漸台，藏於室中北隅。閒校尉公孫賓就斬莽，遂傳首詣更始於宛。","sortOrder":4},
  {"id":"s_work_tdk_4_5","chapterId":"ch_work_tdk_4","text":"世祖光武皇帝讳秀，字文叔，南陽蔡陽人，高皇帝之九代孫也。王莽末，天下連歲灾蝗，寇盜蜂起。時世祖避吏新野，因賣穀宛，宛人李通以圖讖說世祖。世祖於是與通弟李軼起於宛，兄伯升起於舂陵，邓晨起新野，會眾兵击長聚。新市人王匡等立劉聖公為天子，而害伯升，號更始元年，更始使世祖為偏將軍，徇崑陽。王莽聞漢帝立，大懼，號大司徒王尋、大司空王邑，將兵百萬，击世祖於崑陽。世祖破之。三辅豪杰，共誅王莽，傳首詣宛。更始以世祖行大司事，持節北渡河，镇慰州郡。王郎诈為成帝子子舆，立為天子，都邯鄲，遣使降下郡國。世祖滅之。世祖威聲日盛，更始疑慮，乃遣使立世祖為萧王，令罢兵，與諸將有功者還長安。遣苗曾為幽州牧，韐順為上穀守，併北之部。世祖辭不就徵，斬苗曾等，自是始貳於更始。是時長安政亂，四方背叛，皆平之。赤眉賊入函關，攻更始。世祖乃遣邓禹引兵而西，以乘更始赤眉之亂。於是諸將上尊號，篤命有司設壇於鄗南千秋亭五城陌，即皇帝位。十月，駕東幸洛陽，赤眉降。平隗嚣，滅公孫述，天下大定，崩於南宮，時年六十三。末孫靈帝用奄人曹節等，矯製誅太傅陳蕃、李膺，其党人皆楚錮。中平九年，黃中賊起。靈帝崩，太子辯即位。董車入朝，因废帝為宏農王，而立獻帝。李傕逼帝東遷，曹操遷市都許。操薨，帝遜位於曹丕。","sortOrder":5},
  {"id":"s_work_tdk_4_6","chapterId":"ch_work_tdk_4","text":"魏太祖武皇帝，沛國谯人也，姓曹，讳操，字孟德，靈帝時為典農校尉。漢末，奄竖擅權。何進謀誅奄竖，太後不聽。進乃召四方猛將，使引兵向京師，欲以恐劫太後。董卓至，废帝為宏農王，而立獻帝。京師大亂。太祖亡出關，至陳留，散家财，合義兵於已吾。與後將軍哀術、冀州牧韓馥、豫州刺史孔伷、兖州刺史劉岱、渤海太守遠紹，同時俱起，眾各數萬，推紹為盟主，曹公行稱奋武將軍。卓聞兵起，乃徙天子都長安。卓留兵屯洛陽。司徒王允與呂布殺卓。楊奉、韓暹以天子還洛陽。太祖至洛陽衛京邑，暹遁走。太祖以洛陽燒焚殘破，奉天子都許下。詔责袁紹以地廣兵強，专自树党，不聞勤王之師。紹遂攻許。太祖破之官渡，紹呕血死。太祖讨紹子谭尚於黎陽。尚與熙奔遼東。太守公孫康斬尚、熙，送其首，遂平河北。太祖征劉表，會表卒，子琮降。關中諸將馬超、韓遂、成宜等反，曹公破之。天子策命公為魏王。二十五年，薨於洛陽。子丕嗣，受漢禪。崩，子睿嗣，崩，子齊王芳立。废，高貴乡公髦立。废，常道乡公璜立。璜禪晉。","sortOrder":6},
  {"id":"s_work_tdk_4_7","chapterId":"ch_work_tdk_4","text":"晉祖宣皇帝名懿，字仲達，姓司馬，河內溫人也。仕於魏武之世，歷文、明二帝，居將相之位，平孟達，滅公孫度，擒王陵。魏明帝崩，遺詔使帝為太尉，與大將軍曹爽辅少主。帝誅曹爽。宣帝崩，子師代為相。镇東將軍毌丘俭、扬州刺史文钦反，征平之。景帝崩，弟昭代為相，辅政為司空。諸葛誕據寿春反，奉詔平之。伐蜀，擒劉禪。於時政出於權臣，人君主祭而已。魏帝不能容，自勒兵攻相府。太祖用長史贾充計，逆戰，舍人成濟執殺魏帝。太祖崩，子炎受魏禪。既受魏禪。用羊祜、杜預計，征吳平之。立二十五年朋，太子衷立。惠帝不惠，妃贾充女為皇後。後秉權，殺楊駿，废太後，誅太宰汝南王亮、太保衛瓘，戮楚王玮，殒太子遹，用趙王倫為相國。倫惡司空張華、仆射裴頠正直，矯詔誅之。倫遂篡帝位。於是齊王攸之子冏，與帝弟成都王穎等，起義兵誅倫。穎於是镇鄴。併州刺史東瀛公騰、安北將軍王凌，又起兵讨穎。穎败，挟天子南奔洛陽。後惠帝复位，帝弟長沙王又谮冏，誅之。由是戎狄併興，四方阻亂，遂分為三十六國。惠帝立十四年崩，弟豫章王炽立，都長安，為胡賊所殺。懷帝崩，立吳王晏子業。","sortOrder":7},
  {"id":"s_work_tdk_4_8","chapterId":"ch_work_tdk_4","text":"中宗元皇帝睿篤興於江東。帝在位十六年崩，太子紹立。王敦威哲內外，將謀為逆，肅宗征破之。三年，肅宗崩。至簡文帝為第三子孝武帝昌明立，羝賊苻堅寇淮南。晉冠軍將軍謝玄等大破堅於淝水。堅還長安。二十一年，帝崩。後遂幹弋相繼。至安帝為桓玄所篡，宋祖裕平玄。至恭帝，遂於宋。","sortOrder":8},
  {"id":"s_work_tdk_4_9","chapterId":"ch_work_tdk_4","text":"高祖武皇帝姓劉，名裕，字德舆，彭城人。桓玄篡晉，高祖與劉毅、何無忌等，潛謀匡复，起兵平玄，奉天子反正，因居將相之任，封豫章郡公。蜀賊谯縱稱王，高祖遣將征平之。姚泓僣號於西京，高祖征平之，擒泓。蘇卑慕容超據守青州，稱燕王，高祖征，擒超。賊盧循據南海，因高祖北伐燕，乘虛下袭建業。高祖還，乃平之。劉毅據荆州，貳於高祖。高祖遣將征，誅毅。荆州刺史司馬休之反，征之。晉帝加祖位相國，總百揆，扬州牧，封十郡，為宋公。晉安帝崩，大司馬琅琊王即位，徵帝入辅，禪位於宋。永初元年六月丁卯，即帝位於南郊。設壇，柴燎告天。禮畢，備法駕幸建康宮，臨太極前殿，太赦改元。在位三年，崩。立太子義符。废，立宜都王義隆。弒，立武陵王駿。崩，立太子子業。崩，立湘東王彧。崩，立太子昱。崩，立順帝淮，遜位於齊萧道成。凡八代，六十年。","sortOrder":9},
  {"id":"s_work_tdk_4_10","chapterId":"ch_work_tdk_4","text":"齊太祖高皇帝讳道成，姓萧氏，東海蘭陵人也，為辅國將軍。宋明帝初，會稽太守尋陽王子房反，在東諸郡起兵。徐州刺史薛安都據彭城，歸魏，遣從子索兒攻淮陰。晉安王勋遣臨川內史張淹自鄱道入三吳。帝併讨平之。使镇淮陰，七年徵還都。至，拜常侍。明帝崩，遺詔使與袁粲其掌機事。江州刺史桂陽王休范舉兵反，帝讨平之。遷中領軍。蒼梧王深相猜忌，常語左右陽玉夫伺織女渡報我。是夜七夕，玉夫懼，取千牛刀殺之。帝乃迎立順帝。州刺史沈攸之反，帝讨之。進位相國，封齊公，備九錫。四月，宋帝禪位於齊。甲午，即皇帝位於南郊，柴燎告天。禮畢，備法駕幸建康宮，臨太極前殿，大赦改元。建元四年崩，立太子赜。崩，之矣昭業。崩，立弟昭文。废，立西昌侯鸞。崩，立太子寶卷。崩，立和帝寶融，以位禪梁。","sortOrder":10},
  {"id":"s_work_tdk_4_11","chapterId":"ch_work_tdk_4","text":"梁高祖武皇帝名衍，姓萧氏，為巴陵王法曹，後為竟陵王子良八友。魏將王肅攻司州，帝破之，以功封建康邵男。齊明帝崩，東昏即位，遺詔以帝為都督雍州刺史。長兄懿被害，帝起義。戊申，帝發自襄陽。郢、魯諸誠及諸將併降。壬午，帝镇石頭，命眾軍围六門。衛尉張稷暫東昏，以黃油裹首送軍。平京邑，齊和帝以位禪梁。帝即位。太清元年，齊司徒侯景以十三州內屬。侯景反，至京師，幽帝而崩。侯景立武帝太子綱為帝，又為景所殺。湘東王繹於荆州，使王僧辯等平侯景，傳首江陵。景平，湘東王即位於江陵。魏使萬紐於謹來攻，梁王萧察率眾會之。帝見執，魏人戕帝。江陵既陷，王僧辯、陳霸先等議立帝子方智於江州，奉迎至建鄴即位。太平二年，禪位於陳。","sortOrder":11},
  {"id":"s_work_tdk_4_12","chapterId":"ch_work_tdk_4","text":"高祖武皇帝姓陳氏，名霸先，吳興長城人也。梁武帝時，為直閤將軍。侯景反，高祖率所領與侯景大戰，侯景败死。湘東王即位，授南徐州刺史，還镇京口。馭聖三年，西魏攻陷西台，高祖與王僧辯立晉安王，進帝位。司空僧辯又與齊氏和親，納貞侯。高祖以為不義，潛師袭王僧辯於石頭，克之。是夜縊僧辯，貞陽侯遜位。晉安王复位。徐嗣徽北引齊師，遣萧軌等四十六將，濟江至幕府山。高祖併破之，進位丞相，進爵為陳王。永定三年，梁帝禪位於陳。三年，上崩，立弟子茜。崩，立太子伯宗。废，立頊。崩，立太子叔寶，是為長城公也。叔寶在東宮，好學有文藝。及即位，耽酒色。隨文帝初受周禪，甚敦鄰好。宣帝崩，遣使赴弔，脩敵國之禮，書稱名頓首。而後主驕奢，書末雲：想彼統內如宜此，宇宙清泰。隨文帝不悅，以示朝臣。贺若弼、楊素等以為主辱，再拜請罪，併求致讨。文帝曰：我為人父母，豈阿限一衣帶水而不拯不乎？命作戰船。以晉王廣為元帥，督八十總管以致讨。韓擒虎入自南掖門，文武各官皆遁出，擒後主。晉王廣入據台城，送後主於東宮。三月癸已，後主與三公百司發自建鄴，之長安。及至京師，列陳舆服，引後主及王公，使宣詔讓後主。後主屏息不能對，封長城公。至仁寿四年，終於洛陽。隨高祖姓楊氏，名堅。周武帝初，為隨州刺史。女為太子妃。周宣帝立，拜為大司馬。宣帝崩，立靖帝，進爵為隨王，遂禪位焉。改號开皇元年。九年，平陳，废太子勇為庶人，立晉王廣為皇太子。高祖崩，太子即位。煬帝無道，盜賊蜂起。十三年幸江都，李密設壇於巩，自署為魏公。梁歸都據夏州。劉武周殺太原留守王恭，舉兵反。窦建德自號夏王。朱粲自號楚王。劉元進據吳都。煬帝聞群賊起，大懼，使冯慈明徵兵東都，詔唐國公讳镇太原。五月甲子，唐公舉義兵，遙尊煬帝為太上皇，立代王侑為天子，行伊霍故事，傳檄天下，聞之乡應。秋七月，唐公將西圖長安，仗白旗，誓眾於太原之野，被甲三萬。留公子元吉守太原，義師次霍邑。隨武牙郎將宋老生拒義師。時連雨不霁，糧運不給，又訛言突厥將袭太原，唐公懼，命旋師。用秦王諫，乃止。老生背城而陣，一戰斬之，平霍邑。冬十月，義師次長樂宮。衛文昇挟代王乘城拒守。十一月平京師，尊代王為天子，改元義寧。時煬帝將之丹陽，而大臣將卒皆北人，不願南遷，鹹思歸。宇文化及因百姓之不堪命，殺煬帝於江都。隨室王侯，無少長皆斬之。立嗣王浩為天子，化及為丞相。五月戊午，天子侑遜位於別宮，禪位於唐，都長安。己巳，王世充、段達等立越王侗為皇帝於洛陽。六月，宇文化及自江都至彭城，據黎陽，稱許。李密率大軍，壁清淇。敦煌張守一聞密一拒化及也，說越王以讨。越王不用其策，用孟琮計，與密連和。李密無東都之慮，盡銳攻化及，破之。密自败化及，益以驕傲。越王命王充击密，密不用祖君彦計，密師败績。遂西奔京師，尋謀叛，殺之。大唐武德二年，王充殺越王侗於洛陽，僣稱尊號，隨氏滅矣。","sortOrder":12},
  {"id":"s_work_tdk_4_13","chapterId":"ch_work_tdk_4","text":"論曰：幹寶稱帝王之興，必俟天命。苟有代謝，非人事也。尧舜內禪，體文德也；漢魏外禪，順大名也；湯武革命，應天人也；高光爭伐，定功業也。各因其運而得天下，隨時之義大矣哉。范晔曰：竹自古丧大業，絕宗禋，其所以致削弱禍败者，蓋漸有由矣。三代以嬖色取禍，羸氏以奢虐致灾，西京自外戚失祚，東都绿閹尹傾國。成败之來，先史商之久矣。自秦漢迄於周隨，觀其興亡，雖亦有數，然大抵得之者，皆因得賢豪，為人興利除害；其失之也，莫不因任用群小，奢汰無度。孔子曰：以約失之者鮮矣。又曰：遠佞人，去僻惡。有旨哉！","sortOrder":13},
  {"id":"s_work_tdk_4_14","chapterId":"ch_work_tdk_4","text":"《長短經》　唐　趙蕤","sortOrder":14},
  {"id":"s_work_tdk_5_1","chapterId":"ch_work_tdk_5","text":"卷五霸紀中","sortOrder":1},
  {"id":"s_work_tdk_5_2","chapterId":"ch_work_tdk_5","text":"七雄略第十八","sortOrder":2},
  {"id":"s_work_tdk_5_3","chapterId":"ch_work_tdk_5","text":"臣聞天下大器也，群生重蓄也。器大不可以獨理，蓄重不可以自守。故划野分疆，所以利建侯也；親疏相镇，所以關盛衰也。昔周監二代，立爵五等，封國八百，同姓五十五，深根固本，為不可拔者也。故盛則周邵相其治，衰則五霸扶其弱，所以夹辅王室，左右厥世。此三聖製法之意。然厚下之典，弊於尾大。自幽平之後，日以陵夷，爵祿多出於陪臣，征伐不由於天子。吳併於越，晉分為三，鄭兼於韓，魯滅於楚。海內無主，四十餘年而為戰國矣。秦據势勝之地，騁狙诈之兵，蠶食山東，山東患之。蘇秦，洛陽人也，合諸侯之縱以賓秦；張儀，魏人也，破諸侯之縱以連橫。此縱橫之所起也。","sortOrder":3},
  {"id":"s_work_tdk_5_4","chapterId":"ch_work_tdk_5","text":"蘇秦初合縱至燕，說燕文侯曰：燕東有朝鮮、遼東，北有林胡、樓煩，西有雲中、九原，南有呼迤、易水，地方二千餘里，帶甲數十萬，車六百乘，騎六千匹，粟支數年，南有碣石雁門之饒，北有棗栗之利，民雖不田作，而足於棗栗矣。此所謂天府者也。夫安樂無事，不見覆軍殺將，無過燕者。大王知其以然乎？夫燕所以不犯寇被甲者，以趙之為蔽其南也。秦趙相毙，而王以全燕製其後，此燕之所以不犯寇也。且夫秦之攻燕也，逾雲中、九原，過代上穀，弥地數千里，雖得燕城，秦計固不能守也。秦之不能害燕亦明矣。今趙之攻燕也，發號出令，不至十日，而數十萬之軍，軍於東垣矣；渡呼迤，涉易水，不至四五日，而距國都矣。故曰：秦之攻燕也，戰於千里之外；趙之攻燕也，戰於百里之內。夫不忧百里之患，而重於千里之外，計無過於此者。是故願大王與趙從親，天下為一，則燕國必無事矣。燕文侯許之。蘇秦如趙，說趙肅侯曰：臣竊為君計，莫若安民無事，且無庸有事民為也。安民之本，在於擇交。擇交而得則民安；擇交而不得，則民終身不安。請言外患：齊秦為兩敵，而民不得安。倚秦攻齊，而民不得安；倚齊攻秦，而民不得安。君誠能聽臣，燕必致氈裘狗馬之地，齊必致魚鹽之海，楚必致橘柚之園，韓、魏、中山皆可使致湯沐之奉，而貴戚父兄皆可受封侯。夫割地包利，五伯之所以覆軍擒將而求也；封侯貴戚，湯武所以放弒而爭也。今君高拱而兩有之，此臣之所為君願也。夫秦下轵道，則南陽危；劫韓包周，則趙自操兵；據衛取淇，卷則齊必入朝秦。秦欲已得乎山東，則必舉兵而向趙矣。秦甲渡河逾漳，據番吾，則兵必戰於邯鄲之下矣。此臣之所為君危也。當今之時，山東之建國，莫強於趙。趙地方二千餘里，帶甲數十萬，車千乘，騎萬匹，粟支數年，西有常山，南有河漳，東有清河，北有燕。燕固弱國，不足畏也。秦之所害於天下莫如趙，然而秦不敢舉兵而伐趙者，何也？畏韓、魏之議其後也。然則韓、魏，趙之南蔽也。秦之攻韓魏也，無名山大川之险，稍稍蠶食之，傅國都而止。韓魏不能支秦，必入臣於秦。奉無韓、魏之規，則禍必中於趙矣。此臣之為君患也。臣聞尧無三夫之分，舜無咫尺之地，以有天下；禹無百人之聚，以王諸侯；湯武之士不過三千，車不過三百乘，卒不過三萬，立為天子，誠得其道也。是故明主外料其敵之強弱，內度其士卒賢不肖，不待兩軍相當，而勝败存亡之機固已形於胸中矣。豈掩於眾人之言，而以冥冥决事哉？臣竊以天下之地圖按之：諸侯之地，五倍於秦，度諸侯之卒，十倍於秦。六國併力，西乡而攻秦，秦必破矣。今西面而事之，見臣於秦。夫破人之與見破於人、臣人之與見臣於人也，豈可同日而論哉？夫衡人者，皆欲割諸侯之地，以與秦。秦成則台榭、美宮室、聽笙竽之音，國被秦患而不與其忧。是故冲人日夜務以秦權恐偈諸侯，以求割地。願大王孰計之。臣聞明主絕疑去讒，屏流言之跡，塞朋党之門，故尊主強兵之臣，得陳忠於前矣。故竊為大王計，莫若一韓、魏、齊、楚、燕、趙，從親以叛秦。合天下之將相，會於洹水之上，通质，刑白馬而盟，約曰：秦攻楚，齊魏各出銳師以之佐之，韓絕其糧道，趙涉河漳，燕守常山之北；秦攻韓魏，則楚絕其後，齊出銳師以佐之，趙河涉漳，燕守雲中；秦攻齊，則楚絕其後，韓守成皋，魏塞其糧道，趙涉河博關，燕出銳師以佐之；秦攻燕，則趙守常山，楚軍武關，齊涉渤海，韓魏皆出銳師以佐之；秦攻趙，則韓軍宜陽，楚軍武關，魏軍河外，齊涉清河，燕出銳師以佐之。諸侯有不如約者，以五國之兵共伐之。六國從親以賓秦，則秦甲必不不敢出於函穀以害山東矣。如此則霸王之業成矣。趙王曰、善。蘇秦如韓，說韓宣王曰：韓北有巩洛成皋之固，西有宜陽商版之塞，東有宛穰洧水，南有陉山，地方九百餘里，帶甲數十萬；天下之強弓劲弩，皆從韓出；韓卒超足而射，百發不暇止，遠者括洞胸，近者鏑掩心；韓之劍戟，則龍泉太阿，皆陆斷牛馬、水截鵠雁。夫以韓卒之劲，與大王之賢，乃西面而事秦，交臂而服焉。羞社稷而為天下笑，無大於此者也。是故願大王孰計之。大王無事秦，事秦必求宜陽成皋。今茲效之，明年又复求地。與之則無地以給之，不與則弃前功而受後禍。且夫大王之地有盡，而秦之求無己。以有盡之地，而逆無己之求，此所謂市怨結禍者，不戰而地已削矣。臣聞鄙諺曰：寧為雞口，無為牛後。今王西面交臂而臣事秦，何異於牛後乎？夫以大王之賢，挟強韓之兵，而有牛後之名，竊為大王羞之。韓王勃然作色，按劍太息曰：寡人雖不肖，不能事秦。從之。蘇秦如魏，說魏襄王曰：大王之地，南有鸿溝陳汝，南東有淮潁煮棗，西有長城之界，北有河水卷衍，地方千里。地名雖小，然而田舍庐庑，曾無刍牧之地。人民之眾，車馬之多，日夜行不絕，輷鞫殷殷，若有三軍之眾。魏，天下之強國也。王，天下之賢也。今乃有意西面而事秦，稱東藩，筑帝宮，受冠帶，祠春秋。臣竊為大王恥之。臣聞越王句踐戰弊卒三千，擒夫差於幹遂；武王卒三千，革車三百乘，製紂於牧野，豈其卒眾哉？誠能奋其威也。令竊聞大王之卒，武士二十萬，仓頭、奋击各二十萬，厮徒十萬，車六百乘，騎六千匹，此過越王句踐、武王遠矣。今乃聽於群臣之說，而欲臣事秦。夫事秦必割地以效實，故兵未用而國已虧矣。夫為人臣割其主之地以外交，偷取一旦之功，而不顧其後，破公家而成私門，外挟強秦之势，以內劫其主，以求割地，願大王孰察之。《周書》曰：綿綿不絕，蔓蔓奈何？毫釐不伐，將用斧柯。前慮未定，後有大患。將奈之何？大王誠能聽臣，六國從親，专心併力，則必無強秦之患。故敝邑趙王使臣效愚計，奉明約，在大王詔之。魏王曰：謹奉教。蘇秦如齊，說齊宣王曰：齊南有泰山，東有琅邪，西有清河，北有渤海，此四塞之國也。臨菑甚富而實，其民無不吹竽鼓瑟、彈琴击筑、斗雞走狗、六博蹴踘者也。臨菑之途車轂击，人摩肩，連衽成帷，舉袂成幕，揮汗成雨，未殷人足，志氣高扬。夫以大王之賢，與齊之強，天下莫能當也。今乃西面事秦，竊為大王羞之。且夫韓、魏之所以畏秦者，為與秦接境壤界也。兵出相當，不出十日，而戰勝存亡之機决矣。韓魏戰而勝秦，則兵半折，四境不守；戰而不勝，則國已危亡隨其後也。是故韓魏之所以重與秦戰，而輕為之臣也。今秦之攻齊則不然，倍韓、魏之地，過衛晉陽之道，經乎亢父之险，車不得方軌，騎不得比行，百人守险，千人不敢過也。秦雖欲深入，則狼顧，恐韓、魏之議其後。是故恫疑虛喝，驕矜而不敢進。夫不深料秦之無奈齊何也，而欲西面事之，是群臣之計過也。今無事秦之名，而有強國之實，故願大王少留意計之。齊王曰：善。蘇秦如楚，說威王曰：楚，天下之強國也。王，天下之賢主也。西有黔中、巫郡，東有夏州、海陽，南有洞庭、蒼梧，北有陉塞、邭陽，地方五千餘里，帶甲百萬，車千乘，騎萬匹，粟支十年，此霸王之資也。夫以楚之強，大王之賢，天下莫能當也。今乃西面而事秦，則諸侯莫不西面而朝章台之下矣。秦之所害，莫如楚。楚強則秦弱，秦強則楚弱，其势不兩立。故為大王計，莫如從親以孤秦。大王不從親，秦必起兩軍，一軍出武關，一軍下黔中，則鄢郢動矣。臣聞治之其未亂也，為之其未有也。患至而後忧之，則無及也。故願大王早熟計之。大王誠能聽臣，臣請令山東之國，奉四時之獻，以承大王之明詔；委社稷，奉宗廟，練士励兵，在大王所用之。故從合則楚王，衡成則秦帝。今釋霸王之業，而有事人之名，竊為大王不取也。夫秦，虎狼之國也，有吞天下之心。秦，天下之仇讎也。衡人皆欲割諸侯之地以事秦，此所謂養仇而奉讎。大逆不忠，無過此者。故從親則諸侯割地以事楚，衡合則楚割地以事秦。此兩策者，相去遠矣。二者大王何居焉？故敝邑趙王使臣效愚計，奉明約，在大王詔之。楚王曰：善。謹奉社稷以從。六國既合縱，蘇秦為縱約長，北報趙。趙肅侯封秦為武安君。乃投縱約書於秦，秦不敢闚兵函穀十五餘年。","sortOrder":4},
  {"id":"s_work_tdk_5_5","chapterId":"ch_work_tdk_5","text":"張儀為秦連衡，說魏王曰：魏地方不至千里，卒不過三十萬，地四平，諸侯四通，條達輻凑，無名山大川之限。從鄭至梁，二百餘里，車馳人走，不待倦而至梁。南與楚境，西與韓境，北與趙境，東與齊境，卒戍西方，守亭障者不下十萬。梁之地势，固戰埸也。梁南與楚，不與齊，齊攻其東；東與齊，不與趙，趙攻其北；不合於韓，則韓攻其西；不親於楚，則楚攻其南。此所謂四分五裂之道也。且諸侯之為縱者，將以安社稷、尊主、強兵、顯名也。今為縱者，一天下約為崑弟，刑白馬以盟洹水之上，以相堅也。而親崑弟、同父母，尚有爭錢财，而欲恃诈伪反覆蘇秦之謀，其不可成亦已明矣。大王不事秦，秦下兵攻河外，據卷衍、酸棗，劫衛取晉陽，則趙不南。趙不南則梁不北，梁不北則縱道絕，縱道絕則大王之國欲無危，不可得也。秦折韓而攻梁，韓恃於秦，秦韓為一，梁之亡立可須也。此臣之所為大王患也。為大王計，莫如事秦。事秦則楚、韓必不敢動。無楚韓之患，則大王高枕而臥，國必無忧矣。大王不聽臣，秦下甲士而東伐，雖欲事秦，不可得也。且夫從人多奋辭而少可信，說一諸侯而成封侯之業。是故天下之遊談士，莫不日夜扼腕瞋目切齒以言縱之便，以說人主。人主賢其辯而牵其說，豈得無眩哉？臣聞之，積羽沈舟，群輕折軸，眾口鑠金。故願大王審計定議。魏王於是倍縱約，而請成於秦。張儀說楚懷王曰：秦地半天下，兵敵四國，被山帶河，四塞以為固，虎贲之士百有餘萬，車千乘，騎萬匹，粟如丘山，法令既明，士卒安樂，主明以嚴，將智以武，雖無出甲，席卷常山之险，必折天下之脊。天下後服者先亡矣。且夫為縱者，無以異驅群羊而攻猛虎。虎之與羊，不格明矣。今王不與虎而與群羊，臣竊以為大王之計過矣。凡天下強國，非秦而楚，非楚而秦，兩國交爭，其势不兩立。大王不與秦，下甲據宜陽，韓之上地不通，下兵河東成皋，韓必入臣，則梁亦從風而動。秦攻楚之西，韓攻其北，社稷安得無危。臣聞兵不如者，勿與挑戰；粟不如者，勿與持久。秦西有巴蜀，大船積粟，起於汶山，浮江而下，至楚三千餘里，舫舟載卒，一載五千人，日行三百里，里數雖多，然不費牛馬之力，不至十日，而拒扞關矣。扞關驚，則從境以東，盡城守矣。黔中巫郡，非王之有也。秦舉甲出武關，南面而伐，則北地絕。秦兵之攻楚也，危難在三月之內；而楚待諸侯之救，在半歲之外，此其势不相乃也。夫待弱國之救，忘強秦之禍，此臣為大王患也。大王嘗與吳人戰，五戰而三勝，陳卒盡矣。編守新城，存民苦矣。臣聞功大者易危，而人弊者怨上。夫守易危之功，而逆強秦之心，臣竊為大王危之。凡天下而以信約縱親相堅者，蘇秦封為武安君也。蘇秦相燕，即陰與燕王謀伐齊，破齊而分其地。乃佯為有罪，出走入齊。齊王因受而相之。居二年而覺，齊王大怒，車裂蘇秦於市。夫以一诈伪之蘇秦，而欲經營天下、混一諸侯，其不可成亦明矣。今秦與楚接壤界，固形親之國也。大王誠能聽臣，臣請使秦太子入质於楚，楚太子入质於秦；請以秦女為大王箕帚之妾；效萬室之都，以為湯沐之邑；長為崑弟之國，終身無相攻。臣以為計無便於此者。楚王乃與秦親。張儀如韓，說說韓宣王曰：韓地险惡山居，五穀所生，非菽而麥，地方不過九百里，無二年之食料；大王之卒，悉舉不過三十萬，而厮徒負養在其中矣。今秦帶甲百萬，車千乘，騎萬匹；虎贲之士、跿詢科頭、貫颐奋戟者，不可勝數。山東被甲蒙胄會戰，秦人捐甲徒裼以趨敵，左挈人頭，右挟生虜；秦逐山東之卒，猶孟贲之與怯夫；以輕重相壓，猶乌獲之與婴兒。諸侯不料地之弱、食之寡，而聽縱人之甘言好辭，比周以相飾。诖誤其主，無過此者。大王不事秦，下甲據宜陽，斷韓之地，東取成皋、滎陽，則鸿台之宮、桑林之苑，非王有也。夫塞成皋、絕上地，則國之國分矣。故為大王計，莫如為秦。秦之所欲，莫如弱楚。而能弱楚者，莫如韓。非以韓能強於楚也，其势然也。今西面而事秦，以攻楚，秦王必喜。夫攻楚而不私其地，轉禍而悅秦，計無便於此者。宣王聽之。張儀說濟湣王曰：天下強國，無過齊者。大臣父兄殷眾富樂，欲為大王計者，皆為一時之說，不顧百代之利。縱人說大王者，必曰：齊西有強趙，南有韓梁，齊負海之國也，地廣民眾，兵強士勇，雖有百秦將，無奈齊何也。大王賢其說，而不計其實。臣聞齊與魯三戰而魯三勝，國以危亡隨其後。雖有戰勝之名，而有破亡之實。是何也？齊大而魯小也。今秦之與齊也，猶齊之與魯也。今齊、楚嫁女娶婦，為崑弟之國。韓獻宜陽，魏效河外，趙入朝歌、渑池，割河間以事秦。大王不事秦，秦驅韓、梁攻齊之南地，悉趙兵渡清河，指博關，臨菑、即墨非王有也。國一旦見攻，雖欲事秦，不可得也。是故願大王孰計之。齊王許之。張儀說趙王曰：敝邑秦王，使效愚於大王。大王收天下以賓秦，秦兵不敢出函穀關，是大王之威，行於山東。敝邑恐懼慑伏，繕甲励兵，唯大王有意督過之也。今以大王之力，舉巴蜀，併漢中，包兩周，遷九鼎，守白馬之津。秦雖僻遠，然而心忿含怒之日久矣。今有敝甲凋兵，軍於渑池，願渡河，據番吾，會戰邯戰之下，願以甲子合戰，以征殷紂之事。故使臣先以聞於左右。凡大王之所信為從者，恃蘇秦。蘇秦熒惑諸侯，以是為非，以非為是，欲反覆齊國，而自令車裂於市。夫天下之不可混一亦明矣。今楚與秦為崑弟之國，而韓、梁稱為東藩之臣，齊獻魚鹽之地，此斷之右臂也。夫斷右臂而與人斗，失其党而孤居，求欲無危，豈可得乎？今秦發三軍，其一軍基午道，告齊使興師渡河，軍於邯鄲之東；一軍軍於成皋，驅韓、梁軍於河外；一軍軍於渑池，約四國而击趙。趙服，必四分其地。是故不匿意隱情，先以聞於左右。臣竊為大王計，莫如與秦王遇於渑池，面相見而口相約，請按兵無攻。願大王之定計。趙肅侯許之。張儀說燕昭王曰：大王之所親信，莫如趙。昔趙襄子嘗以其姊為代王妻，欲併代，約與代王遇於句註之塞，乃令工人作為金斗，長其尾，令可以击人。與代王飲，陰告厨人曰：即酒酣樂，進熱啜，反斗以击之。於是酒酣樂，取熱啜，厨人進斟，因反斗击代王，殺之，肝胁涂地。其姊聞之，因磨笄以自殺。故至今有磨笄之山，天下莫不聞。夫趙王之狼戾無親，大王之所明見。且以趙為可親乎？趙興兵攻燕，再围燕都，而劫大王。大王割十城以謝。今趙王已入朝渑池，效河間，事以秦。今大王不事秦，秦下甲雲中九原，驅趙而攻燕，則易水長城，非王有也。今王事秦，秦王必喜，趙不敢妄動。昃西有強秦之援，南無齊趙之患。是故願大王孰計之。燕王聽張儀。儀歸報秦。","sortOrder":5},
  {"id":"s_work_tdk_5_6","chapterId":"ch_work_tdk_5","text":"於是楚人李斯、梁人尉缭說於秦王曰：秦自孝公已來，周室卑微，諸侯相兼，關東為六國。秦之乘勝侵諸侯，蓋六代矣。今諸侯服秦，譬若郡縣。其君臣俱恐，若或合縱而出不意，此乃智伯、夫差、湣王所以亡也。願王無愛财，賂其豪臣，以亂其謀。秦不過亡三十萬金，則諸侯可盡。秦王從其計，陰遣謀士赍金玉以遊諸侯。諸侯名士，可與财者，厚遺給之；不肯者，利劍刺之，離其君臣之計。乃使良將隨其後，遂併諸侯。","sortOrder":6},
  {"id":"s_work_tdk_5_7","chapterId":"ch_work_tdk_5","text":"秦既吞天下，患周之败，以為弱見奪。於是笑三代，荡滅古法，削去五等，改為郡縣，自號為皇帝；而子弟為匹夫，內無骨肉本根之辅，外無尺土蕃翼之衛。吳、陳奋其白挺，劉、項隨而毙之。故曰：周過其歷，秦不及其數，國势然也。","sortOrder":7},
  {"id":"s_work_tdk_5_8","chapterId":"ch_work_tdk_5","text":"漢興之初，海內新定，同姓寡少，懲亡秦孤立之败，於是割裂疆土，立爵二等。功臣侯者，百有餘邑。尊王子弟，大啟九國。國大者，跨州兼郡，連城數十，可謂矯枉過正矣。然高祖創業，日不暇給，孝惠享國之日淺，高後女主攝位，而海內晏然，無狂狡之忧、卒折諸呂之難、成太宗之基者，亦賴之於諸侯也。夫原本以末大，流濫以致嗌。小者淫荒越法，大者睽孤橫逆，以害身丧國。故文帝采贾生之議，分齊趙。景帝用晁错之計，削吳楚。武帝施主父之策，推恩之令。景遭七國之亂，抑諸侯，减黜其官。武有淮南、衡山之謀，作左官之律，設附益之法。諸侯唯得衣食租稅，不與政事。至於哀平之际，皆繼體苗裔，親屬疏遠，生於帷牆之中，不為士民所尊。故王莽知漢中外殫微，本末俱弱，無所忌憚，生其奸心；因母後之權，假伊、周之稱，专作威福，廟堂之上，不降階序而運天下。诈謀既成，遂據南面之尊，分遣五威之吏，馳傳天下，班行符命。漢諸侯王蹶角稽首，奉上玺绂，唯恐居後。豈不哀哉！乃莽败，天下雲扰。光武中興，篡隆皇統，而猶遵覆車之遺轍，養丧家之宿疾，仅及數世，奸宄充斥。率有強臣专朝，則天下風靡；一夫縱橫，則城池自夷。豈不危哉！在周之難興王室也，放命者七臣，幹位者三子，嗣王委其九鼎，凶族據其天邑，鉦鼙震於阃宇，鋒鏑流於絳闕；然禍止畿甸，害不覃及，天下晏然，以治待亂。是以宣王興於共和，襄、惠振於晉鄭。豈若二漢階闼暫扰，而四海已沸；孽臣朝入，而九服夕亂哉？遠惟王莽篡逆之事，近覽董卓擅權之际，亿兆悼心，愚智同痛。豈世乏曩時之臣，士無匡合之志欤？蓋遠績屈於時異，雄心挫於卑势耳。魏太祖武皇帝躬聖明之姿，兼神武之略，龍飛谯沛，鳳翔兖豫；觀五代之存亡，而不用其長策，睹前車之傾覆，而不改其轍跡；子弟王空虛之地，君不使之人，權均匹夫，势齊凡庶；內無深根不拔之固，外無磐石宗盟之助，非所以安社稷，為萬世之業也。且今之州牧郡守，古之方伯諸侯，皆跨有千里之土，兼軍武之任，或比國數人，或兄弟併據，而宗室子弟，曾無一人間廁其間，與相維持，非所以強幹弱枝，備萬一之慮也。時不用其計，後遂凌夷，此周、秦、漢、魏立國之势。是以究其始終強弱之势，明鑒戒焉。","sortOrder":8},
  {"id":"s_work_tdk_5_9","chapterId":"ch_work_tdk_5","text":"論曰：周有天下八百餘年，後代衰微，而諸侯縱橫矣。至末孫王赮降為庶人，猶能枝葉相持，名為天下共主。當是時也，楚人問鼎，晉侯請隧，雖欲阚周室，而見厄諸姬。夫豈無奸雄，賴諸侯以維持之也。故語曰：百足之虫，至死不僵，扶之者眾，此之謂乎？及嬴氏擅場，懲周之失，废五等，立郡縣；君有海內，而子弟為匹夫，功臣效勤，而幹城無茅土；孤製天下，獨擅其利，身死之日，海內分崩。陳勝偏袒唱於前，劉季提劍興於後，虎嘯龍睇，遂亡秦族。夫劉、陳諸杰，布衣也，無吳、楚之势、立錐之地，然而驅白徒之眾，得與天子爭衡者，百姓思亂、無諸侯勤王之可憚也。故請曰：夫亂政虐刑，所以資英雄而自速禍也。此之謂矣。夫伐深根者難為功，摧枯朽者易為力。今五等，深恨者也；郡縣，枯朽者也。故自秦以下，迄於周、隨，失神器者非侵弱，得天下者非持久，國势然也。呜呼！郡縣而理，則生布衣之心；五等御代，則有縱橫之禍。故知法也者，皆有弊焉。非謂侯伯無可亂之符、郡縣非致理之具，但經始圖其多福，慮終取其少禍，故貴於五等耳。聖人知其如此，是以競競業業，日慎一日，修德以镇之，擇賢而使之。德修賢擇、黎元樂業，雖有湯武之聖，不能興矣。况於布衣之細，而敢偏袒大呼哉？不可不察。","sortOrder":9},
  {"id":"s_work_tdk_5_10","chapterId":"ch_work_tdk_5","text":"《長短經》　唐　趙蕤","sortOrder":10},
  {"id":"s_work_tdk_6_1","chapterId":"ch_work_tdk_6","text":"卷六霸紀下","sortOrder":1},
  {"id":"s_work_tdk_6_2","chapterId":"ch_work_tdk_6","text":"三國權第十九","sortOrder":2},
  {"id":"s_work_tdk_6_3","chapterId":"ch_work_tdk_6","text":"論曰：臣聞昔漢氏不綱，網漏凶狡。袁本初虎视河朔；劉景升鵲起荆州；馬超、韓遂，雄據於關西；呂布、陳宮，竊命於東夏；遼河海岱，王公十數，皆阻兵百萬、鐵騎千群，合縱締交，為一時之杰也。然曹操挟天子令諸侯，六七年間，夷滅者十八九。唯吳、蜀蕞爾國也，以地圖按之，才四州之土，不如中原之大都；人怯於公戰，勇於私斗，輕走易北，不敵諸華之士；角長量大，比才稱力，不若二袁、劉、呂之盛。此二雄以新造未集之國，資逆上不侔之势，然能撫劍顧眄，與曹氏爭衡；躍馬指麾，而利盡南海。何哉？則地利不同，势使之然耳。故《易》曰：王侯設险以守其國。古語曰：一里之厚，而動千里之權者，地利也。故曹丕臨江，見波涛汹涌，叹曰：此天所以限南北也。劉資稱南鄭為天獄、斜穀道為五百里石穴。稽諸前志，皆畏其深阻矣。雖雲天道順，地利不如人和，若使中材守之，而延斯挺命可也。豈區區艾、浚，得奋其長策乎？由是觀之，在此不在彼。於戲！智者之慮，必雜於利害。故不盡知用兵之害，則不能知用兵之利，有自來矣！是以采摭其要，而為此權耶！夫囊括五湖、席卷全蜀，庶知害中之利，以明魏家之略焉。","sortOrder":3},
  {"id":"s_work_tdk_6_4","chapterId":"ch_work_tdk_6","text":"天帝布政房心，致理參伐。參伐則益州分野，按《職方》則雍州之境，據《禹貢》钊梁州之域，地方五千里，提封四十郡，實一都會也。故古稱天府之國，沃野千里，其有以矣！","sortOrder":4},
  {"id":"s_work_tdk_6_5","chapterId":"ch_work_tdk_6","text":"王莽末，公孫述據蜀。益部功曹李熊說述曰：方今四海波荡，匹夫橫議，將軍割據千里，地什湯武，若奋發威德，以投天隙，霸王之業成矣。今山東飢饉，人民相食，兵所屠滅，城邑丘墟。蜀地沃野千里，土壤膏腴，果實所生，無穀而飽，女工之業，覆衣天下，名材竹幹，器械之饒，不可勝用，人有魚鹽銅鐵之利、浮水轉漕之便，北據漢中，杜褎斜之隘，東守巴郡，拒捍關之口，地方數千里，戰士不下百萬，見利則出兵而略地，無利則堅守而力農，東下漢水，以闚秦地，南順江流，以震荆扬，所謂用天因地、成功之資。今君王之聲聞於天下，而位號未定，志士狐疑，宜即大位，使遠人有所歸依。建武元年四月，遂自立為天子，號成家，色尚白。","sortOrder":5},
  {"id":"s_work_tdk_6_6","chapterId":"ch_work_tdk_6","text":"自更始败後，光武方事山東，未遑西伐。關中豪杰，多擁眾歸述。其後平陵人荆邯見東方將平，兵且西向，說述曰：兵者，帝王之大器，古今所不能废也。隗嚣遭遇運會，割有雍州，兵強士附，威加山東，不及此時摧危乘勝，以爭大命，而退欲為西伯之事，偃武息戈，卑辭事漢，喟然自以武王复出也。今漢帝釋關隴之忧，专精東伐，四分天下而有其三。使西州豪杰，鹹居心於山東，發間使，招携貳，則五分而有其四。若舉兵天水，必至沮潰。天水既定，則九分而有其八。陛下以梁州之地，內奉萬乘，外給三軍，百姓愁困，不堪上命，將有王氏自潰之变。臣之愚計，以為宜及天人之望未絕，豪杰尚可招誘，急以此時發國內精兵，令田戎據江陵，臨江南之會，倚巫山之固，筑壘堅守，傳檄吳楚。長沙以南，必隨風而靡。令延岑出中，定三辅天水，隴西拱手自服。如此，海內震搖，冀有大利。述不聽邯計。光武乃使岑彭、吳漢伐蜀，破荆門，長驅入江關。軍至成都，述出戰，兵败被刺，洞胸死。夷述妻子，焚其宮室。","sortOrder":6},
  {"id":"s_work_tdk_6_7","chapterId":"ch_work_tdk_6","text":"至靈帝時，政理衰缺，王室多故，雄豪角逐，分裂疆宇，以劉焉為益州牧。焉死，子璋立，為劉備所围，遂降。","sortOrder":7},
  {"id":"s_work_tdk_6_8","chapterId":"ch_work_tdk_6","text":"初劉備為豫州牧也，為曹公所破，走屯新野。聞諸葛亮躬耕南陽，乃三詣亮於草庐之中，屏人言曰：漢室傾頹，奸臣竊命，主上蒙尘；孤不度量力，欲信大義，行於天下；而智術淺短，遂用猖蹶，至於今日，然意猶未已。君謂計將安出？亮答曰：自董卓已來，豪杰併起。跨州連郡者，不可勝數。曹操比於袁紹，名微而眾寡；然遂能克紹，以弱為強者，非唯天時，抑亦人謀也。今操已擁百萬之眾，挟天子而令諸侯，此誠不可與爭鋒。孫權據有江東，已歷三代，國险而民附，賢能為用，此可與為援，而不可圖也。荆州北據江漢，利盡南海，東連吳會，西通巴蜀，此用武之國，而其主不能守，此殆天所以資將軍也。益州崄塞，沃野天府之土，高祖因之以成帝業。劉璋闇弱，張魯在北，民殷國富，而不知恤，智能之士，思得明後。將軍既帝室之胄，信義著於四海，總覽英雄，思賢如渴；若跨有荆益，保其巖岨，西和諸戎，南撫夷越，結好孫權，內修政理，天下有变，則命上將將荆州之軍，以向宛洛，將軍身率益州之眾，出於秦川；百姓孰不簟食壶槳，以迎將軍者乎？誠如是，則霸業可成，漢室可興矣。時曹公破荆州，先主奔吳。備用亮計，結好孫權，共拒曹公於赤壁，破之。曹公北還，權乃以荆州業備。","sortOrder":8},
  {"id":"s_work_tdk_6_9","chapterId":"ch_work_tdk_6","text":"庞統說備曰：荆州荒殘，人物单盡，東有吳孫，北有曹氏，鼎足之計，難以得志。今益州國富人強，戶口百萬，郡中兵馬，所出畢具，寶货無求於外，今可權借以定大事。備曰：今指與吾為水火者，曹操也。操以急，吾以宽；操以暴，吾以仁；操以譎，吾以忠，每與操反，事乃可成耳。今以小故而失信義於天下者，吾所不取也。統曰：權变之時，固非一道所能定也。兼弱吞昧，五伯之事，逆取順守，報之以義，各事定後，封以大國，何負於信？今日不取，終為人利耳。備乃使關關羽守荆州，欲自取蜀。會劉璋聞曹公向漢中讨張魯，內懷恐懼。別駕張松說璋曰：曹公兵強，無敵於天下；若因張魯之資，以取蜀土，誰能御之？劉豫州，使君之宗室，而曹公之深仇也。若使之讨魯，魯必破。魯破則益州強，曹公雖來，無能為也。璋然之，遣法正迎先主。先主與璋會涪。璋既還成都，先主當為璋北征漢中。統复說備曰：陰選精兵，晝夜兼道，径袭成都；璋既不武，又素無豫備，大軍卒至，一舉便定，此上計也。楊懷、高沛，璋之名將，各杖強兵，據守關頭，聞數有箋來諫璋，使發遣將軍還荆州；將軍未至遣，與相聞，說荆州有急，欲還救之，併使裝束，外作歸形，此一子俱服將軍英名，又喜將軍之去，必乘輕騎來見將軍，因此執之，進取其兵，乃向成都，此中計也。返還白帝，連引荆州，徐還圖之，此下計也。若沈吟不去，將致大困，不可久矣。先主然其中計。即斬懷等，自葭萌南還取璋。時鄭度說璋曰：左將軍袭我，兵不滿萬，士眾未附，野穀是資。計莫若盡驅巴西梓潼人，內涪水以西；其仓廪野穀，一皆燒除，高壘深溝，靜以待之。彼請戰不許，久無所資，不過百日，必將自走，走而击之，則必禽矣。璋不用度計。先主遂長驅，所過必克，而有巴蜀。","sortOrder":9},
  {"id":"s_work_tdk_6_10","chapterId":"ch_work_tdk_6","text":"群臣勸先主稱尊號，先主未許。諸葛亮曰：昔吳漢、耿純等勸世祖即帝位，世祖辭讓，前後數四。耿純進言曰：天下英雄，喁喁冀有所望，如不從議者，士大夫各歸求主，無為從公也。世祖感純言深至，遂然诺之。今曹氏篡漢，天下無主。大王劉氏苗族，紹世而起，即帝位，乃其宜也。士大夫久勤苦者，亦望尺寸之功名，如純言耳。先主於是即帝位。時曹公拔漢中，法正說先主曰：曹操一舉降張魯，定漢中，不因此势以圖巴蜀，而留夏侯淵、張郃屯守，身遽北還，此非其智不逮，力不足也，將內有忧逼故耳。今算淵、郃才略，不勝算之將率，舉眾往讨，則必克之。克之日，廣農積穀，觀衅伺隙，上可以傾覆寇敵、尊奖王室，中可以蠶食雍涼、廣境拓土，下可以固守要害、為持久之計。此蓋天以與我，時不可失也。先主善其策。乃率諸將進兵漢中，正亦從行。先主由陽平南渡　水，緣山稍前，於定軍山作營。淵將兵來爭其地，正曰：可击矣。先主命黃忠乘高鼓噪攻之，大破淵軍，淵等授首，遂奄有梁漢。時魏使夏侯楙镇長安，蜀將魏延就諸葛亮請兵從褎中出，循秦嶺而東，當子午而北，以袭長安。亮不許。其後吳孫權袭關羽，取荆州。先主怒吳，伐之，败績。還蜀，至永安而崩。後主禪即位。","sortOrder":10},
  {"id":"s_work_tdk_6_11","chapterId":"ch_work_tdk_6","text":"先是，吳主孫權請和。丞相諸葛亮慮權聞先主殂，有異計，乃遣邓芝修好於權。權果狐疑，不時見芝。芝自表請見，權語芝曰：孤誠願與蜀和親。然恐蜀主幼弱，國小势逼，為魏所乘，不自保全，以此猶豫耳。芝對曰：吳蜀二國，四州之土。大王命世之英，諸葛亮一時之杰也；蜀有重险之固，吳有三江之阻，合此二長，共為唇齒，進可兼併天下，返可鼎足而立，此理势之自然也。大王今若委质於魏，魏必上望大王之入朝，下求太子之內侍。若其不從，則奉辭伐叛，蜀必順流見可而進。如此，江南之地，非复大王之有也。權默然良久曰：君言是也。遂自絕魏，與蜀連和。","sortOrder":11},
  {"id":"s_work_tdk_6_12","chapterId":"ch_work_tdk_6","text":"時司徒華歆、司空王朗等，與諸葛亮書，陳天命，欲使舉國稱蕃。亮不答書，作正議曰：昔在項羽，起不由德，雖處華夏，秉帝者之势，卒就湯镬，為後來戒。魏不審鑒，今次之矣。免身為幸，滅在子孫。而二三子多逞蘇、張诡靡之說，奉進驩兜滔天之辭，欲以誣毀唐帝，諷解禹稷，所以徒懷文藻、煩勞翰墨。大雅君子，所不為也。又軍志曰：萬人必死，橫行天下。昔軒轅氏挈卒數萬，製四帝，定海內。况以數十萬之眾，據正道而臨有罪，可得幹擬者哉？亮死後，魏令邓艾伐蜀。蜀兵败，後主用谯周策降魏。","sortOrder":12},
  {"id":"s_work_tdk_6_13","chapterId":"ch_work_tdk_6","text":"晉時，李特复據蜀，晉桓溫滅之。至宋義熙中，谯縱又殺益州刺史毛璩於成都，稱成都王。宋使朱齡石滅之。此蜀國形也。","sortOrder":13},
  {"id":"s_work_tdk_6_15","chapterId":"ch_work_tdk_6","text":"丑為星紀，吳越之分，上應斗牛之宿，下當少陽之位。古人有言曰大江之南、五湖之間，其人輕心，楊州保強，三代要服不及以正；國有道則後服，無道則先叛。故傳曰：吳為封豕長蛇，荐食上國。為上國之患，非一日之積也。","sortOrder":15},
  {"id":"s_work_tdk_6_16","chapterId":"ch_work_tdk_6","text":"漢高帝時，淮南王英布反。反書聞，上召諸將，問布反為之奈何？汝陰侯滕公曰：臣客故楚令尹薛公有筹策，可問。上乃召見問薛公。薛公對曰：布反，不足怪也。使布出於上計，山東非漢之有也；出於中計，勝败之數，未可知也；出於下計，陛下安枕而臥矣。上曰：何謂上中下計？令尹曰：東取吳，西取楚，併齊取楚，傳檄燕、趙，固守其所，山東漢之有也。何謂中計？東取吳，西取楚，併韓取魏，據廒仓之粟，塞成皋之口，勝败之數，未可知也。何謂下計？東取吳，钿取下蔡，歸重於越，身歸刁沙，陛下安枕而臥，漢無事矣。上曰：是計將安出？令尹對曰：出下計。上曰：何為废上中計而出下計？令尹曰：布故郦山之徒也，自致萬乘之國，此皆為身不顧其後、為萬世慮者，故曰出下計。上曰：善。果如策。","sortOrder":16},
  {"id":"s_work_tdk_6_17","chapterId":"ch_work_tdk_6","text":"是後，吳王劉濞以子故而反。初發也，其大將祿田伯曰：兵屯聚而西，無他奇道，難以就功。臣願得奇兵五萬人，別循江淮而上，收淮南、長沙，入武關，與大王會，此亦一奇也。吳王太諫曰：王以反為名，此兵難以藉人，藉人亦且反王。吳王不許。其少將桓將軍复說吳王曰：吳多步兵，步兵利险阻；漢多車騎，車騎利平地。願大王所過城邑，不下，宜弃去；疾西據雒陽武库，食敖仓之粟，阻山河之险，以令諸侯。雖無人關，天下固已定矣。即大王徐行，留下城邑，漢車騎至，馳入梁楚之效，事败矣。王問諸老，諸老曰：此年少摧鋒之計耳，安知大慮？吳王不從桓將軍之計，乃自併將其兵。漢以太尉周亚夫击吳、楚，亚夫用其父客計，遂败吳","sortOrder":17},
  {"id":"s_work_tdk_6_18","chapterId":"ch_work_tdk_6","text":"淮南王劉安怨望其父厲王長死，謀為叛逆，問伍被曰：吾舉兵西向，諸侯必有應者。即無奈何？被曰：南收衡山，以击庐江，有潯陽之船，守下雉之城，結九江之浦，絕豫章之口，強弩臨江而守，以禁東郡之下；東收江都、會稽，南通劲越，屈強江淮間，猶可一舉得延歲月之寿。王曰：善。未得發，會事泄，誅。","sortOrder":18},
  {"id":"s_work_tdk_6_19","chapterId":"ch_work_tdk_6","text":"至後漢靈獻時，閹人擅命，天下提契，政在家門。時長沙太守孫堅殺南陽太守張咨，袁術得據其郡。堅與術合縱，欲奪劉表荆州，堅為流矢所中死。孫堅死，子策領其部曲，击扬州刺史劉繇，破之，因據江都。策聞魏太祖與袁紹相扶於官渡，將渡江袭許。未濟，為許貢客所殺。策死，弟權領其眾。屬曹公破袁紹，兵威日盛，乃下書责孫權，求质。張昭等會議不决，權乃獨將周瑜，詣其母前定議。瑜曰：昔楚國初封於荆山之侧，不滿百里之地，繼嗣賢能，廣土开境，立基於郢，遂據荆扬，至於南海，傳業延祚，九日餘年。今將軍承父兄餘資，兼六郡之眾，兵精精多，將士用命，鑄山為銅，煮海為鹽，境內富饒，人不思亂，沈舟舉帆，朝發夕到，士風劲勇，所向無前，有何逼迫而欲送质？质子一入，不得不與曹氏；曹氏命召，不得不往，便見製於人也。豈與南面稱孤同哉？不如勿與，徐觀其变。若曹氏率義以正天下，將軍事之未晚；若圖為暴亂，兵猶火也，不戢，必將自焚。韜勇枕威，以待天命，何送质之有？權母曰：公瑜議是也。遂不送质。後曹公荆州，劉琮舉眾降。曹操得其水軍船，步卒數十萬。吳將士聞之皆恐，孫權延見群下，問以計策。議者鹹曰：曹公豺虎也，讬名漢相，挟天子以征四方，動以朝廷為辭。今日拒之，事更不順。且將軍大势可以拒操者，長江也。今操得荆州，奄有其地。劉表治水軍，蒙冲斗艦，及以千數。操悉以沿江，兼有步兵，水陆俱下，此為長江之险，已與我共之矣。而势力眾寡，又不可論。愚謂大計，不如迎之。周瑜曰：不然。操雖讬名漢相，其實漢賊。將軍以神武之雄才，兼仗父兄之烈，割據江東，地方數千里，精兵足用，英豪樂業，尚當橫行天下，為漢家除殘去秽，况操自送死，而可迎之耶？請為將軍筹之，今使北土已安，操無內忧，能曠日持久，來爭疆場，又能與我决勝負於舟楫可也。今北上既未安，馬超、韓遂尚在關西，為操後患。且舍鞍馬、杖舟楫，與吳、越爭衡，本非中國所長。又今盛寒，馬無藁草，驅中國士眾，遠涉江湖之間，不習水土，必生疾病。此數四者，用兵之患也，而操皆冒行之。將軍擒操，宜在今日。瑜請得精兵三萬人，進住夏口，保為將軍破之。權曰：老賊欲废漢自立久矣，徒忌二袁、呂布、劉表、與孤耳。今數雄已滅，唯孫孤尚存。孤與老賊，势不兩立。君言當击，甚與孤合，此天以君授孤也。周瑜等水軍三萬，與劉備併力距曹公。用黃蓋火攻策，遂破曹公於赤壁。曹公败，径北還。權遂虎视江表。","sortOrder":19},
  {"id":"s_work_tdk_6_20","chapterId":"ch_work_tdk_6","text":"初，周瑜荐魯肅才宜佐時，權即引肅對飲，曰：今漢室傾危，四方雲扰，孤承父兄遺業，思有桓文之功。君既惠顧，何以佐之？肅對曰：昔高帝區區，欲尊事義帝而不獲者，以項羽為害也。今之曹操，猶昔項羽。將軍何由得為桓文乎？肅竊料之，漢室不可复興，猶曹操不可卒除。將軍為計，惟有鼎足江東，以觀天下之衅。規模如此，亦自無嫌。然後建號帝王，以圖天下。此高帝之業也。及是平一江滸，稱尊號，臨壇顧謂公卿曰：昔魯子敬嘗道此，可謂明於事势矣。","sortOrder":20},
  {"id":"s_work_tdk_6_21","chapterId":"ch_work_tdk_6","text":"黃武元年，魏使大司馬曹仁步騎數萬向濡須，濡須督朱桓破之。七年，又使大司馬曹休騎十萬至皖城，迎周鲂。鲂欺之，無功而返。","sortOrder":21},
  {"id":"s_work_tdk_6_22","chapterId":"ch_work_tdk_6","text":"至權薨，皓即位，窮極淫侈，割剝蒸人，崇信奸回，賊虐諫辅。晉世祖令壮預等伐吳，滅之。","sortOrder":22},
  {"id":"s_work_tdk_6_23","chapterId":"ch_work_tdk_6","text":"至晉永嘉中，中原丧亂，晉元帝复渡江王江南。宋、齊、梁、陳，皆都焉。此吳國形也。","sortOrder":23},
  {"id":"s_work_tdk_6_25","chapterId":"ch_work_tdk_6","text":"古者，天子守在四夷。天子卑弱，守在諸侯。當漢之季，奸臣擅朝，九有不澄，四郊多壘，雖复諸侯釋位以間王政，然皆包藏禍心，各圖非冀。魏太祖略不世出，靈武冠時，值炎精幽昧之期，逢風尘無妄之世，嗔目張胆，首建義旗。時韓暹楊奉挟獻帝自河東還洛陽，太祖議迎都許。或以為山東未定，不可。荀彧勸太祖曰：昔晉文納周襄王，而諸侯景從。高祖東伐，為義帝縞素，天下歸心。自天子播越，將軍首唱義兵；以山東扰亂，未能遠離關右，然猶分遣將帥，蒙险通使；雖御外難，乃心無不在王室，是將軍匡天下之素志也。今車駕旋軫，義士有存本之思，百姓感舊而增哀誠。因此時奉主上以從人望，大順也；秉至公以服雄杰，大略也；挟宏義以致英俊，大德也。天下雖有逆節，不能為累明矣。韓暹、楊奉，其敢為害？若不是定，四方生心，後雖慮之無及。太祖至洛陽，奉天子都許，維其弛紊，纫其赘旒，俾我家不失舊物矣。於是運筹演謀，鞭撻宇內，北破袁紹，南虜劉琮，東舉公孫康，西夷張魯，九州百郡，十併其八，志績未究，中世而殒。","sortOrder":25},
  {"id":"s_work_tdk_6_26","chapterId":"ch_work_tdk_6","text":"夫能扶天下之危者，則據天下之安；能除天下之忧者，則享天下之樂；能救天下之禍，則得天下之福。曹氏率義拨亂，代載其功。至文帝時，天人與能矣，遂受漢禪。","sortOrder":26},
  {"id":"s_work_tdk_6_27","chapterId":"ch_work_tdk_6","text":"王室雖靖，而二方未賓，乃門贾詡曰：吾欲伐不從命，以一天下，吳、蜀何先？對曰：攻取者先兵權，建本者尚德化。陛下應期受禪，撫臨率土，若綏之以文德，而俟其变，則平之不難矣。吳、蜀雖蕞爾小國，依阻山水，劉備有雄才，諸葛亮善治國，孫權識虛實，陆遜見兵势，據险守要，汎舟江湖，皆難卒平也。用兵之道，先勝後戰，量敵論將，故舉無遺策。臣竊料群臣無權、備對，雖以天威臨之，未見萬全之势。昔舜舞幹威而苗服，臣以為當今宜先文後武。文帝不納，後果無功。","sortOrder":27},
  {"id":"s_work_tdk_6_28","chapterId":"ch_work_tdk_6","text":"至甘露元年，始以邓艾為镇西將軍，距蜀將薑維。維軍败，退守劍閣。鍾會攻維不能克。艾上言曰：今賊摧折，宜遂乘之。從陰平由邪径經漢德陽亭，趣涪出劍閣西四百里，去成都三百餘里，奇兵冲其腹心，劍閣之守必還赴涪，則會方軌而進；劍閣之軍不還，則應涪之兵寡矣。軍志有之攻其不備，出其不意。今掩其立虛，破之必矣。冬十月，艾自陰平行無人之地七百餘里，凿山通道，山高穀深，艾以氈自裹，推轉而下，將士皆攀木緣崖，魚貫而進。先登至江由，蜀將諸葛瞻自涪還綿竹，列陣待艾。艾遣子忠等出戰，大破之，斬瞻。進軍到雒縣，劉禪遂降。至晉末，谯縱复竊蜀。宋劉裕使朱齡石伐蜀，聲言從內水取成都，败衣羸老進水口。谯縱果疑其內水上也，悉軍新城以待之。乃配朱齡石等精銳，迳從外水，直至成都，不戰而禽縱。此滅蜀形也。","sortOrder":28},
  {"id":"s_work_tdk_6_29","chapterId":"ch_work_tdk_6","text":"魏嘉平中，孫權死。征南大將軍王昶、征東大將軍胡遵、镇南將軍毌丘俭等，表征吳。朝廷以三征計異，詔诈尚書傅嘏。嘏對曰：昔夫差勝齊陵晉，威行中國，不能以免姑蘇之禍；齊闵辟士兼國，开地千里，不足以救顛覆之败。有始者不必善終，古事之明效也。孫權自破蜀兼荆州之後，志盈欲漢，凶亢已極。相國宣文王先識取亂侮亡之義，深遠宏圖大舉之策。今權已死，讬孤於諸葛恪，若矯權苛暴，蠲其虐政，民免酷烈，偷安新惠，外內齊慮，有同舟之懼，雖不能終自保完，猶足以延期挺命於深江之外矣。今議者或欲汎舟径濟，橫行江表；或欲倍道併進，攻其城壘；或欲大佃疆場，觀衅而動。此三者皆取賊之常計，然施之當機則功成，若苟不應節，必貽後患。自治兵已來，出入三載，非掩袭之軍也。賊丧元帥，利存退守，若羅船津要，堅城清野，橫行之計，其殆難捷也。賊之為寇幾六十年，君臣伪立，吉凶同患，若恪蠲其弊，天奪之疾，崩潰之應，不可卒待也。今賊設羅落，又持重密，間諜不行，耳目無聞。夫軍無耳目，投察未詳，而舉大眾以臨臣崄，此為希幸徼功、先戰而後求勝，非全軍之長策也。唯有大佃最差完牢，兵出民表，寇鈔不犯；坐食積穀，不煩運士；乘衅讨袭，無遠勞費，此軍之急務也。夫屯壘相逼，巧拙得用，策之而知得失之計，角之而知有餘不足之處，情伪將焉所逃？夫以小敵大，則役煩力竭；以貧敵富，則斂重财匮。故敵逸勞之、飽能飢之，此之謂也。然後盛眾厲兵以振之，參惠倍賞以招之，多方廣似以疑之，由不虞之道，以間其不戒，比及三年，左提右挈，虜必冰散瓦解，安受其弊，可坐算而得也。昔漢氏歷世常患匈奴，朝臣謀士，早朝晏罢。介胄之將，則陳征伐；搢紳之徒，鹹言和親；勇奋之士，思展搏噬。故樊哙願以十萬橫行匈奴，季布面折其短；李信求以二十萬獨舉楚人，而果辱秦軍。今諸將有陳越江陵之崄、獨步虜庭，即亦向時之類也。以陛下聖德，辅相賢智，法明士練，错計於全勝之地，振長策以御之，虜之崩隤，必然之數。故兵法曰：屈人之兵而非戰也，拔人之城而非攻也。若釋廟勝必然之理，而行百一不全之略，誠愚臣之所慮也。故謂大佃而逼之計最長。時不從嘏言，詔昶等征吳。吳將諸葛恪拒之，大败魏軍於東關。魏後陵夷禪晉，太祖即位。","sortOrder":29},
  {"id":"s_work_tdk_6_30","chapterId":"ch_work_tdk_6","text":"至世祖時，羊祜上平吳表曰：先帝順天應時，西平巴蜀，南和吳會，海內得以休息，兆庶有槳安之心。而吳复背信，使邊事更興。夫期雖天所授，而功業必由人而成。不一大舉扫滅，則眾役無時得安，非所以隆先帝之勋、成無為之化也。故尧有丹水之伐，舜有有曲之征，鹹以寧靜宇宙、戢兵和眾者也。蜀平之後，天下皆謂吳當併亡。自此來十三年，是謂一周，平定之期，复在今日。議者常言吳、楚有道後服，無禮先強，此諸侯之時耳。當今一統，不得與古同論。夫適道之論，皆未應權，是故謀之雖多，而决之欲獨。凡以险阻得存者，謂敵者同力足以自固。苟其輕重不齊、強弱異势，則智士不能謀，而险阻不可保也。蜀之地，非不险也，高山尋雲霓，深穀肆無景，束馬懸車，然後能濟，皆言一夫荷戟、千人莫當。及進兵之日，曾無藩篱之限，斬將搴旗，伏尸數萬，乘勝席卷，径至成都。漢中諸城，皆鳥栖而不敢出。非皆無戰心，誠力不足相抗。至劉禪降服，諸營堡者，索然俱散。今江淮之難，不過劍閣；山川之险，不過岷漢；孫皓之暴，侈於劉禪；吳越之困，甚於巴蜀。而大晉兵眾，多於前世；資储器械，盛於往時。今不於此平吳，而更阻兵相守，征夫苦役，日尋幹戈，經歷盛衰，不可長久。宜當時定，以一四海。今若引梁、益之兵，水陆俱下；荆、楚之眾，進臨江陵；平南、豫州，直指夏口；徐、扬、青、兖，併向秣陵，鼓　以疑之，多方以誤之。以一隅之吳，當天下之眾，势分形散，所備皆急。巴漢奇兵，出其空虛，一處傾坏，則上下震荡。吳緣江為國，無有內地，東西數千里，以藩篱自持，所敵者大，無有寧息。孫皓恣情任意，與下多忌，名臣重將，不复自信。是以孫秀之徒，皆畏逼而至。臣疑於朝，士困於野，無有保势之計、一定之心。平常之日，猶懷去就；兵臨之际，必有應者，終不能齊力致死，已可知也。其俗急速，不能持久；弓弩戟楯，不如中國；唯有水戰，是其所便。一入其地，則長江非复所固；還保城池，則去長入短。而官軍懸進，人有致節之志；吳人戰於其地，有凭城之心。如此，軍不逾時，克可必矣。帝深納焉。乃令王濬等滅吳，天下書同文、車同軌矣。","sortOrder":30},
  {"id":"s_work_tdk_6_31","chapterId":"ch_work_tdk_6","text":"至晉惠庸弱，胡亂中原。天子蒙尘，播遷江表，當時天下复分裂矣。出入五代，三百餘年。隨文帝受圖，始謀伐陳矣。嘗問高颎取陳之策？颎曰：江北地寒，田收差晚；江南土熱，水田早熟。量彼收獲之际，微徵士馬，聲言掩袭。賊必屯兵堅守，足使废其農時。彼既聚兵，我便解甲。再三如此，賊以為常，後更集兵，彼必不信。猶豫之頃，吾乃濟師登陆而戰，兵氣益倍。又江南土薄，舍多竹茅，所有储積，皆非地窖。密遣行人，因風縱火，待其修立，复更燒之。不出數年，自可财力俱盡。上行其策，陳人益弊。後發兵，以薛道衡為淮南道行台尚書，兼掌文翰。及王師臨江，高颎召道衡，夜坐幕下，因問曰：今師之舉，克定江東與否？君试言之。道衡答曰：凡論大事成败，先須以至理斷之。《禹貢》所載九州，本是王者封域。後漢之季，群雄競起，孫兄弟，遂有吳楚之地。晉武受命，尋即吞併。永嘉南遷，重此分割。自爾已來，戰爭不息。否終斯泰，天道之恒。郭璞有雲：江東偏王三百年，還與中國合。今數將滿矣，以運數而言，其必克一也。有德者昌，無德者亡。自古興滅，皆由此道。主上躬履恭俭，忧勞庶政。叔寶峻宇雕牆，酣酒荒色，上下離心，人神同憤，其必克二也。為國之體，在於任寄。彼之公卿，備員而已。拔小人施文慶，委以政事；尚書令江總，唯事詩酒，本非經略之才；萧摩诃任蠻奴，是其大將，一夫之勇耳，其必克三也。我有道而大，彼無德而小。量其甲士，不過十萬，西自巫峡，東至沧海，分之則援懸而力弱，聚之則守此而失彼，其必克四也。席卷之兆，其在不疑。颎忻然曰：君言成败理甚分明，吾今豁然也。本以才學相期，不意筹略乃至此也。遂進兵虜叔寶。此滅吳形也。","sortOrder":31},
  {"id":"s_work_tdk_6_32","chapterId":"ch_work_tdk_6","text":"自隨开皇十年庚戌歲滅陳，至今开元四年丙辰歲，凡一百二十六年，天下一統。","sortOrder":32},
  {"id":"s_work_tdk_6_33","chapterId":"ch_work_tdk_6","text":"論曰：《傳》稱都城過百雉，國之害也。又曰：大都偶國，亂之本。古者諸侯不過百里，山海不以封毋親、夷狹，良有以也。何者？贾生有言：臣竊跡前事，夫諸侯大抵強者先反。淮陰王楚最強，則最先反；韓信倚胡，則又反；貫高因趙資，則又反；陳豨兵精，則又反；彭越因梁，則又反；黔布用淮南，則又反；盧綰最弱，最後反。長沙乃在二萬五千戶耳，功小而最完，势疏而最忠，非獨性異人也，亦形势然也。亦形势然也。曩令樊、郦、絳、灌據數十城而王，今雖以殘亡可也。令信、越之倫，列為彻侯而居，雖至今存可也。然則天下之大計亦可知已。欲諸王之皆忠附，則莫若令如長沙王；欲臣子之勿菹醢，則莫若令如樊、郦等；欲天下之治安，則莫若眾建諸侯而少其力。以此觀之，今专城者，皆提封千里，有人民為焉，非特百里之資也；官以才居，屬非肺腑，非特毋親之疏也；吳據江湖，蜀阻天险，非特山海之利也；跨州連郡，形束壤製，非別偶國之害也。若遭萬世之变，有七子之禍，則不可讳。有國者不可不察。","sortOrder":33},
  {"id":"s_work_tdk_6_34","chapterId":"ch_work_tdk_6","text":"《長短經》　唐　趙蕤","sortOrder":34},
  {"id":"s_work_tdk_7_1","chapterId":"ch_work_tdk_7","text":"卷七權議","sortOrder":1},
  {"id":"s_work_tdk_7_2","chapterId":"ch_work_tdk_7","text":"懼誡第二十","sortOrder":2},
  {"id":"s_work_tdk_7_3","chapterId":"ch_work_tdk_7","text":"《易》曰：湯武革命，順乎天而應乎人。《書》曰：撫我則後，虐我則讎。《尸子》曰：昔周公反政，孔子非之曰：周公其不聖乎？以天下讓，不為兆人也。董生曰：雖有繼體守文之君，不害聖人之受命。古語曰：窮鼠咬貍，匹夫奔萬乘。故黃石公曰：君不可以無德，無德則臣叛。孫卿曰：能除患則為福，不能則為賊。何以明之？","sortOrder":3},
  {"id":"s_work_tdk_7_4","chapterId":"ch_work_tdk_7","text":"昔文王在酆，召太公曰：商王罪殺不辜，汝尚助餘忧人。今我何如？太公曰：王其脩身，下賢惠人，以觀天道。天道無殃，不可以先唱；人道無灾，不可以先謀。必見天殃，又見人灾，乃可以謀。與民同利，同利相救，同情相成，同惡相助，同好相趨，無甲兵而勝，無衡機攻，無渠垽而守。利人者，天下啟之，害人者，天下閉之。天下非一人之天下也。取天下若逐野獸，得之而天下皆有分肉；若同舟而濟，皆同其利，舟败皆同其害。然則皆有啟之，無有閉之者矣。無取於民者，取民者也；無取於國者，取國者也；無取於天下者，取天下者也。取民者民利之，取國者國利之，取天下者天下利之。故道在不可見，事在不可聞，勝在不可知，微哉微哉！鷙鳥將击，卑身翕翼；猛獸將搏，俛耳俯伏；聖人將動，必有愚色。唯文唯德，誰為之式？弗觀弗视，安知其極？今被殷商，眾口相惑。吾觀其野，草茅勝穀；吾觀其群，眾曲勝直；吾觀其吏，暴虐殘賊，败法亂刑，而上不覺。此亡國之則也。文王曰：善。","sortOrder":4},
  {"id":"s_work_tdk_7_5","chapterId":"ch_work_tdk_7","text":"楚恭王薨，子靈王即位。群公子因群丧職之族，殺靈王而立子幹。立未定，弟弃疾又殺子幹而自立。初，子幹之入也，韓宣子問於叔向曰：子幹其濟乎？對曰：難。宣子曰：同惡相求，如市贾焉。何難？對曰：無與同好，誰與同惡？取國有五難，有寵而無人，一也；有人而無主，二也；有主而無謀，三也；有謀而無民，四也；有民而無德，五也。子幹在晉十三年矣，晉楚之從，不聞達者，可謂無人；族盡親叛，可謂無主；無衅而動，可謂無謀；為羁終世，可謂無人；亡無愛微，可謂無德。王虐而不忌，楚君子幹涉五難以殺舊君，誰能濟之？有楚國者，其弃疾乎？君陳蔡，城外屬焉；苛慝不作，盜賊伏隱，私欲不违，民無怨心，先神命之，國人信之。芊姓有亂，必季實立，楚之常也。獲神，一也；有民，二也；命德，三也；寵貴，四也；取常，五也。有五利以去五難，誰能害之？子幹之官，則右尹也；數其貴寵，則庶子也；以神所命，則又遠之。其貴亡矣，其寵弃矣，民無懷焉，國無與焉，將何以立？宣子曰：齊桓、晉文，不亦是乎？對曰：齊桓，衛姬之子也，有寵於僖，有鮑叔牙、賓須無、隰朋以為辅佐，有莒、衛以為外主，有國、高以為內主，從善如流，下善齊肅，不藏賄，不從欲，施捨不倦，求善不厭，以是有國，不亦宜乎？我先君文公、狐季姬之子也，有寵於獻公，好學不貳，生十七年，有士五人。有先大夫子餘、子犯以為腹心，有魏犨、贾他以為股肱，有齊、宋、秦、楚以為外主，有栾、郄、狐、先以為內主。亡十九年，守志弥篤，惠懷弃民，從而與之，獻無異親，民無異望。天方相晉，將何以代之？此二君者，異於子幹。恭有寵子，國有奧主。子幹無施於民，無援於外。去晉，晉不送；歸楚，楚不逆。何以冀國？子幹果不終，卒立弃疾，如叔向言。","sortOrder":5},
  {"id":"s_work_tdk_7_6","chapterId":"ch_work_tdk_7","text":"魯昭公薨於乾侯，趙簡子問於史墨曰：季氏出其君而民服焉，諸侯與之，君死於外而莫之或罪。何也？對曰：物生有兩、有三、有五、有陪貳。故天有三辰，地有五行，體有左右，各有妃耦。王有公，諸侯有卿，皆其貳也。天生季氏，以貳魯侯，為日久矣。民之服焉，不亦宜乎？魯君世縱其失，季氏世脩其勤，民忘君矣。雖死於外，其誰矜之？社稷無常奉，君臣無常位，自古以然。故《詩》曰：高岸為穀，深穀為陵。三後之姓，於今為庶，主所知也。在《易》卦，雷乘乾曰《大壮》（）（）。天之道也。政在季氏，於此君也，四公矣。民不知君，何以得國？是以為君，慎器與名，不可以假人。","sortOrder":6},
  {"id":"s_work_tdk_7_7","chapterId":"ch_work_tdk_7","text":"孔子在衛，聞齊田常將欲為亂，而憚鮑、晏，因移其兵以伐魯。孔子會諸弟子曰：魯，父母之國，不忍觀其受敵。將欲屈節於田常以救魯，二三子誰使？子貢請使，夫子許之。遂如齊，說田常曰：今子欲取功於魯實難，若移兵於吳則可也。夫魯難伐之國，其城薄以卑，地狹以泄，其君愚而不仁，大臣伪而無用，其士民又惡甲兵之事，此不與戰。夫吳城高以厚，地廣以深，甲堅以新，士選以飽，重器精兵，盡在其中，又使明大夫守之，此易伐也。田常忿然作色曰：子之所難，人之所易；子之所易，人之所難，而以教常，何也？子貢曰：夫忧在內者攻強，忧在外者攻弱。今君忧在內矣，吾聞君三封而三不成，是則大臣不聽也。今君破魯以廣齊，戰勝以驕主，破國以尊臣，而子之功不與焉，則交日疏於主。是君上驕主心，下恣群臣，求以成大事，難矣。夫上驕則恣，臣驕則爭，是君上與主有卻、下與大臣交爭也。如此，則子之位危矣，故曰不如伐吳。伐吳而不勝民人外死，大臣內空，是君上無強臣之敵，下無民人之過；孤主製齊者，唯君也。田常曰：善。然兵業已加魯矣，不可更。如何？子貢曰：子缓師。吾請救於吳，令救魯而伐齊。子以兵迎之。田常許诺。","sortOrder":7},
  {"id":"s_work_tdk_7_8","chapterId":"ch_work_tdk_7","text":"秦始皇帝遊會稽，至沙兵疾甚。始皇令趙高為書，賜公子扶蘇。未授使者，始皇崩。趙高因留所賜扶蘇玺書，而謂公子胡亥曰：上崩，無詔封王諸子，而獨賜長子書。長子至，即位為皇帝，而子無尺寸之地，為之奈何？胡亥曰：固然也。吾聞明君知臣，明父知子。父既捐命，不封諸子，何可言也？趙高曰：不然。方今天下之權，存亡在子與高及丞相耳。願子圖之。且夫臣人與見臣於人，製人與見製於人，豈可同日而道哉？胡亥曰：废兄而立弟，是不義也；不奉父詔而畏死，是不孝也；能薄而材谫，強因人之功，是不能也。三者逆德，天下不服。高曰：臣聞湯武殺其主，天下稱義焉，不為不忠；衛君殺其父，而衛國載其德，孔子著之，不為不孝。夫大行不細謹，大德不辭讓。乡曲各有宜，而百官不同功。故顧小而忘大，後必有害；狐疑猶豫，後必有悔。斷而敢行，鬼神避之，後有成功。願子遂之也。胡亥喟然叹曰：今大行未發，豈宜佌事幹丞相哉？高曰：時乎時乎？間不及謀。嬴糧躍馬，唯恐後時。胡亥既然高之言，高乃謂丞相斯曰：上崩，賜長子書，與丧俱會鹹陽，而立為嗣。書未行，今上崩，未有知者，事將何以？斯曰：安得亡國之言耶？高曰：君自料才能，孰與蒙恬？功高孰與蒙恬？謀遠不失，孰與蒙恬？無怨於天下，孰與蒙恬？長子舊而信之，孰與蒙恬？斯曰：此五者皆不及蒙恬，而君责之何深也。高曰：高故內宮之厮役也，幸得以刀筆之吏，進入秦宮管事二十餘年，未嘗見秦免罢丞相、功臣有封及二世者也，卒皆以誅亡。皇帝二十餘子，皆君之所知。長子刚毅而武勇，信人而舊事，即位必用蒙恬為丞相；君侯終不懷通侯之印，歸於乡里矣。高受詔習胡亥學法，仁慈篤厚，輕财重士；秦之諸子，皆莫及也，可以為嗣。君計而定之。斯曰：上蔡闾巷布衣也，上幸擢為丞相者，固將以存亡安危屬臣也。豈可道哉？夫忠臣不避死而庶幾，孝子不勤勞而見危，君其勿复言。高曰：蓋聞聖人遷徙無常，龍变而從時，見末而知本，觀指而睹歸，物固有之，安得常法哉？方今天下之權，懸命於胡亥，高能得志焉。且夫從外製中謂之惑，從下製上謂之賊。故秋霜降者草華落，水風搖者萬物作，此必然之效也。君侯何見之晚也？斯曰：吾聞晉易太子，三世不安；齊桓兄弟爭位，身死為戮；紂殘親戚，不聽諫者，國為丘墟。三者逆天，宗廟不血食。斯其由人哉？安足與謀？高曰：上下合同，可以長久；中外若一，事無表里。君聽臣之計，則長有封侯，世世稱孤，必有松乔之寿、孔墨之智。今釋此而不從，禍及子孫，足為寒心。善者因败為福，君何處焉？斯乃仰天而叹，垂涕太息曰：既已不能死，安讬命哉？乃聽高立胡亥，改賜玺書，殺扶蘇蒙括。","sortOrder":8},
  {"id":"s_work_tdk_7_9","chapterId":"ch_work_tdk_7","text":"秦二世末，陳涉起靳。兵至陳，張耳陳餘說涉曰：大王興梁、楚，務在入關，未及收河北也。臣嘗遊趙，知其豪杰，願請奇兵略趙地。於是陳王許之，與卒三千，從白馬渡河。至諸郡縣，說其豪杰曰：秦為亂政虐刑，殘滅天下，北為長城之役，南有五嶺之戍，外內骚動，百姓罢敝，頭會箕斂，以供軍費，财匮力盡，重以苛法，使天下父子不相聊生。今陳王奋臂為天下唱始，莫不响應，自家為怒，各報其怨，縣殺其令丞，郡殺其守尉。今已張大楚，王陳，使吳廣、周文將卒百萬西击秦。於此時而不成封侯之業者，非人杰也。夫因天下之力，而攻無道之君，報父兄之怨，而成割地之業，此一時也。豪杰皆然其言。乃行收兵，下趙十餘城。","sortOrder":9},
  {"id":"s_work_tdk_7_10","chapterId":"ch_work_tdk_7","text":"韓信既平齊，為齊王。項王恐，使盱台人武涉往說齊王，使三分天下。信不聽。武涉已土，蒯通知天下權在韓信，欲為奇策而感動之，以相人說韓信曰：仆常受相人之術。韓信曰：先生相人何如？對曰：貴賤在於骨法，忧喜在於容色，成败在於决斷。以此參之，萬不失一。信曰：先生相寡人如何？對曰：願請間。信曰：左右遠。蒯通曰：相君之面，不過封侯，又危不安。相君之背，貴乃不可言。韓信曰：何謂也？蒯通曰：天下初發難，俊雄豪杰，建號一呼，天下之士，雲合霧集，魚鱗雜遝，煙至風起。當此之時，忧在亡秦而已。今楚漢分爭，使天下無罪之人，肝胆涂地，父子暴骸，骨肉流離於中野，不可勝數。楚人起於彭城，轉斗逐北，至於滎陽，乘利席卷，威振天下。然兵困於京索之間，迫西山而不能進者，三年於此矣。漢王將數十萬之眾，距巩洛，阻山河之险，一日數戰，無尺寸之功，折北不救，败滎陽，傷成皋，遂走宛葉之間，此所謂智勇俱困者也。夫銳氣挫於险塞，而糧食竭於內臟，百姓罢極，怨望容容無所依倚。以臣料之，其势非天下賢聖，固不能息天下之禍。當今兩主之命，懸於足下。足下為漢則漢勝，與楚則楚勝。臣願披腹心，输肝胆，效愚計，恐足下不用也。誠能聽臣之計，莫若兩利而俱存之，三分天下，鼎足而居，其势莫敢先動。夫以足下之賢聖，有甲兵之眾，據強齊，從燕趙，出空虛之地而製其後，因民之欲，西乡為百姓請命，則天下風起而响應矣。孰敢不聽？割大弱強，以立諸侯，諸侯已立，天下服聽而歸德於齊。國之故有膠泗之地，懷諸侯以德，深拱揖讓，則天下之君王，相率而朝於齊矣。蓋聞天與不取，反受其咎；時至不行，反受其殃。願足下熟慮之。韓信曰：漢王還我厚，載我以其車，衣我以其衣，食我以其食。吾聞之，乘人車者，載人之患；衣人衣者，懷人之忧；食人之食者，死人之事。吾豈可以乡利背義乎？蒯生曰：足下自以為善漢王，欲建萬世之業，臣竊以為誤矣。始常山王、成安君為布衣時，相與為刎頸之交。後爭張黡、陳泽之事，二人相怨。常山王奉項婴頭，鼠竄歸於漢王。漢王借兵東下，殺成安君泜水之南，頭足異處，卒為天下笑。此二人相與，天下至歡，然而卒相擒者，何也？患生於多欲，人心難测也。今足下欲行忠信以交於漢王，必不能固於二君之相與也，而事多大於張黡、陳泽，故臣以為足下必漢王之不危己，亦誤矣。大夫种、范蠡，存亡越，霸句踐，立功成名而身死亡。諺曰：野獸盡而獵狗烹，敵國破而謀臣亡。夫以交友言之，則不如張耳之與成安君也；忠臣言之，則不過大夫种之於句踐也。此二人者，足以觀矣。願足下深慮之。且臣聞勇略震主者身危，而功蓋天下者不賞。臣請言大王功略：涉西河，虜魏王，擒夏說，引兵下井陉，誅成安君，徇趙，胁燕，定齊，南摧楚人之兵二十萬，東殺龍且，西乡以報。此所謂功無二於天下，而略不世出者也。今足下載震主之威，挟大賞之功，以歸楚，楚人不信；歸漢，漢人震恐。足下欲持是安歸乎？夫势在人臣之位，而有震主之威，名高天下，竊為足下危之。韓信謝曰：先生且休矣。我將念之。後數日，蒯通复說曰：夫聽者，事之候；計者，事之機也。聽過計失，而能久安者，鮮矣。聽不失一二者，不可亂以言；計不失本末者，不可紛以辭。夫隨厮養之役者，失萬乘之權；守儋石之祿者，闕卿相之位。故智者，决之斷也；疑者，事之候也。審毫釐之小計，遺天下之大數，智誠知之决，不敢行者，百事之禍也。故猛虎之猶與，不如蜂蠆之致螫；騏骥之蹢躅，不如駑馬之安步；孟贲之狐疑，不如庸夫之必至也。雖有舜禹之智，沈吟而不言，不如瘖聋之指麾也。夫功者，難成而易败；時者，難得而易失也。時不再也，願足下詳察之。韓信猶豫不忍背漢，又自以為功多，漢王終不奪我齊，遂謝蒯生。蒯生曰：夫迫於苛細者，不可與圖大事；拘於臣虜者，固無君王之意。說不聽，因去，佯狂為巫。","sortOrder":10},
  {"id":"s_work_tdk_7_11","chapterId":"ch_work_tdk_7","text":"吳王濞以子故不朝，及削地書至，於是及使中大夫應高誂膠西王。無文書口報曰：吳王不肖，有宿夕之忧，不敢自外，使喻其歡心。王曰：何以教之？高曰：今者主上興於奸雄，飾於邪臣，好小善，聽讒賊，擅变更律令，侵奪諸侯之地，徵求滋多，誅罰良善，日以益甚。語有之曰：舐糠及米，吳與膠西。知名諸侯也。一時見察，恐不得安肆矣。吳王身有內病，不能朝請二十餘年，常患見疑，無以自白。今胁肩累足，猶懼不見釋。竊聞大王以爵事有適，所聞諸侯削地，罪不至此，此恐不得削地而已。王曰：然，有之。小將奈何？高曰：同惡相助，同好相留，同情相成，同欲相趨，同利相死。今吳王自以為與大王同忧，願因時脩理，弃軀以除患害於天下，抑亦可乎？王矍然駭曰：寡人何敢如是？今主雖急，固有死耳。安得勿戴？高曰：御史大夫晁错熒惑天子，侵奪諸侯，蔽忠塞賢，朝廷疾怨，諸侯皆有背叛之意，人事極矣。彗星夕出，蝗虫數起，此萬世一時，而愁勞聖人之所起也。故吳王內欲以晁错為詩，外隨大王後車，傍佯天下，所乡者降，所指者下，天下莫敢不服。大王誠幸而許之一言，則吳王帥楚王，略函穀關，守滎陽、敖仓之粟，距漢兵，治次舍，須大王。大王有幸而臨之，則天下可併，兩主分割，不亦可乎？王曰：善。七國皆反，兵败伏誅。","sortOrder":11},
  {"id":"s_work_tdk_7_12","chapterId":"ch_work_tdk_7","text":"淮南王安怨望，厲王死，欲謀叛逆，未有因也。及削地之後，其為謀益甚，與左吳等日夜按舆地圖，部署兵所從入。召伍被與謀，被曰：上宽赦大王，王复安得亡國之言乎？臣聞子胥諫吳王，吳王不用。子胥曰：臣今見麋鹿遊於姑蘇之台。臣今亦見宮中生荆棘，霧露霑衣也。臣聞聰者聽於無聲，明者見於未形，故聖人萬舉萬全。昔文王一動，而功顯於世，列為三代。此所謂因天心以動作者也，故海內不期而隨此。千歲之可見者。夫百年之秦，近世之吳、楚，亦足以喻國家之存亡矣。臣不敢避子胥之誅，願大王無為吳王之聽。昔秦絕聖人之道，殺術士，燔《詩》《書》，弃禮義，尚诈力，任刑罰，轉負海之粟，致之西河。當是之時，男子疾耕，不足於糟糠；女子績紡，不足以蓋形。遣蒙恬筑長城，東西數千里，暴兵露師，常數十萬，死者不可勝數，僵尸千里，流血頃畝，百姓力竭，故欲為亂者，十家而五。又使徐福人海求異物，及延年益寿之藥，還為伪辭曰：臣見海中大神曰：以令名振男女，與百工之事，即得之矣。秦皇大悅，遣振男女三千人，資之五穀种种百工而行。徐福得平原廣泽，止王不來。於是百姓悲痛相思，欲為亂者，十家而六。又使尉他逾五嶺，攻百越。尉他知中國勞極，止王不來，使人上書，求女無夫者三萬人，以為士卒衣補。秦皇可其萬五千人。於是百姓離心瓦解，欲為亂者，十家而七。客謂高皇帝曰：時可矣。高皇帝曰：待之。聖人當起東南間。不一年，陳勝、吳廣發矣。高皇始於丰沛一唱，天下不期而响應者，不可勝數也。此所謂蹈瑕候間，因秦之亡而動者也。百姓願之，若旱之望雨。故起於行陣之中，而立為天子，功高三王，德傳無窮。今大王見高皇得天下之易也，獨不觀近世之吳楚乎？夫吳王賜為劉氏祭酒，受幾杖而不朝，王四郡之眾，地方數千里，內鑄銅以為錢，東煮海以為鹽，上取江陵木為船，國富人眾，舉兵而西，破於大梁，败於狐父，奔走而東，至於丹徒，越人擒之，身死絕祀，為天下笑。夫以吳楚之眾，不能成功者，何也？誠逆天道而不知時也。方今大王之兵眾，不能十分吳楚之一；天下安寧，又萬倍於秦時。願大王從臣之計。大王不從臣之計，今見大王事必不成而語先泄也。臣聞微子過故國而悲，於是作《麥秀》之歌，是痛紂之不用王子比幹也。故孟子曰：紂貴為天子，死曾不若匹夫，是紂先自絕於天下久矣，非死之日而天下去之也。今臣亦竊悲大王弃千乘之君，必且賜絕命之書，為群臣先死於東宮也。於是王氣怨結而不扬，涕滿眶而橫流，即起歷階而去。後复問伍被曰：漢庭治亂？被曰：竊睹朝廷之政，君臣之義、父子之親、夫婦之別、長幼之序，皆得其理；上之舉措，遵古之道；風俗綱紀，未有所缺；南越賓服，羌僰入獻，東甌入降，廣長楊，开朔方，匈奴折翅傷翼，失援不振。雖不及古太平之時，然猶為治也。王欲舉事，臣見其將有禍而無福也。王怒，被謝死罪。王曰：陳勝、吳廣無立錐之地，千人之眾起於大泽，奋臂大呼，而天下响應，西至於戲，而兵百萬。今吾國雖小，然而勝兵者可得十餘萬，非直適戍之眾，釠凿棘矜也。公何以言有禍無福？被曰：秦無道，殘賊天下，興萬乘之駕，作阿房之宮，太半之賦，發闾左之戍，父不寧子，兄不便弟，政苛刑峻，天下敖然若焦，民皆引領而望、傾耳而聽，悲號仰天，扣心而怨上，故陳勝一呼，天下响應。當今陛下臨製天下，一齊海內，汎愛蒸庶，布德施惠，口雖未言，聲疾雷霆，令雖未出，化馳如神，心有所懷，威動萬里，下之應上，猶影响也。而大將軍材能，不特章邯、扬熊也。大王以陳勝、吳廣喻之，被以為過。王曰：苟如公言，不可僥幸耶？被曰：被有愚計。王曰：奈何？被曰：今朔方之郡，田地廣，水草美，民徙者，不足以實其地。可伪為丞相、御史請書，徙郡國豪杰任使，及有耐罪以上，赦令除家產五十萬以上者，皆徙其家屬朔方之郡；益發甲卒，急其會日；又伪為左右都司空、上林中都官詔獄逮諸侯太子幸臣，如此則民怨，諸侯懼。即使辯武隨而說之，傥可僥幸，十得一乎？王曰：此可也。欲如伍被計。使人伪得罪而西，事大將軍、丞相，一日發兵，使人即刺殺大將軍青，而說丞相下之，如發蒙耳。又欲令衣求盜衣，持羽檄，從東方來，呼曰：南越兵入。欲因以發兵。未得發，會事泄誅。","sortOrder":12},
  {"id":"s_work_tdk_7_13","chapterId":"ch_work_tdk_7","text":"後漢靈帝以皇甫嵩為將軍，讨破黃巾，威震天下，而朝政日亂，海內虛困。故信都令阎忠來說嵩曰：難得而易失者，時也；時至不旋踵者，機也。故聖人順時以動，智者因機以發。今將軍遭難得之運，蹈易駭之機，而踐運不撫，臨機不發，將何以保大名乎？嵩曰：何謂也？忠曰：天道無親，百姓與能。今將軍受鉞於暮春，收功於末冬，兵動如神，謀不再計，摧強易於折枯，消堅甚於湯雪，旬月之間，神兵電扫，封戶刻石，南向以報德，威名震本朝，風聲馳海外，雖湯武之舉，未有高將軍者也。今身建不賞之功，體兼高人之德，而北面庸主，何以求安乎？嵩曰：夙夜在公，心不忘忠。何故不安？忠曰：不然。昔韓信不忍一餐之過，而弃三分之業，利劍已揣甚喉，方發悔毒之叹者，機失而謀乖也。今主上势弱於劉、項，將軍權重於淮陰，指揮足以震風雲，叱吒可以興雷電，赫然奋發，因危抵頹，崇恩以綏先附，振武以臨後服，徵冀方之士，動七州之眾，羽檄先馳於前，大軍响振於後，蹈流漳河，飲馬孟津，誅閹宦之罪，除群怨之積，雖童兒可使奋拳以致力，女子可使褰裳以用命。况厲熊羆之卒，因迅風之势哉？功業已就，天下已順，然後請呼上帝，示以天下，混齊六合，南面稱製，移寶器於將興，推亡漢於已墜，實神機之至會，風發之良時也。夫既朽之木不雕，衰世之朝難佐，若欲辅難佐之朝，彫朽败之木，是猶逆坂走丸、迎流縱棹，豈雲易哉？且今宦竖群居，同惡如市，上命不行，權歸近習，昏主之下，難以久居，不賞之功，讒人侧目，如不早圖，後悔無及。嵩懼曰：非常之謀，不施於有常之势。創國大功，豈庸才所致？黃巾細孽，敵非秦、項，新結易散，難以濟業。且民未忘主，天下祐逆，若虛造不冀之功，以速朝名之禍，孰與委忠本朝，守其臣節？雖雲多讒，不過放废；猶有令名，死且不朽。反常之論，所不敢聞。忠知說不用，因亡去。","sortOrder":13},
  {"id":"s_work_tdk_7_14","chapterId":"ch_work_tdk_7","text":"王莽時，寇盜群發，莽遣將軍廉丹伐山東。丹辟冯衍為掾，與俱至定陶。莽追詔丹曰：將軍受國重任，不能捐身中野，無以報恩塞责。丹惶恐，夜召衍，以書示之。衍因說丹曰：衍聞之，順而成者，道之所大也；逆而功者，權之所貴也。是故期於有成，不問所由；論於大體，不守小節。昔逢丑父伏軾而使其君取飲，稱於諸侯；鄭祭仲立突而出忽，終得复位，美於《春秋》。蓋以死易生，以存易亡，君子之道也；诡於眾意，寧國存身，賢者之慮也。故《易》曰：窮則变，变則通，通則久。是以自天祐之，吉無不利。若夫知其不可而必為之，破軍殘眾，無補於主，身死之日，負義於世，智者不為，勇者不行。且衍聞之，得時無怠。張良以五代相韓，椎秦始皇於博浪之中，勇冠乎贲育，名高於太山。將軍之先，為信臣；新室之興，英雋不附。今海內潰亂，民懷漢德，甚於詩人之思召公也。愛其甘棠，而况子孫乎？民所歌舞，天必從之。方今為將軍計，莫若屯據大郡，镇撫吏士，砥砺其節，百里之內，牛酒日賜，納雄杰之士，詢忠智之謀，要將來之心，待縱橫之变，興社稷之利，除萬人之害，則福祿流於無窮、功烈著於不滅。何與軍覆於中原，身膏於草野，功败名丧，恥及先祖哉？聖人轉禍而為福，智士因败而為功。願將軍深計而無與俗同。丹不能從。進及睢陽，复說丹曰：蓋聞明者見於未形，智者慮於未萌。况其昭晰者乎！凡患生於所忽，禍發於細微，败不可悔，時不可失。公孫鞅曰：有高人之行，必負非於世；有獨見之慮，必見赘於民。故信庸庸之論，破金石之策；袭當世之操，失高明之德。夫决者，智之君也；疑者，事之役也。時不再來，公勿再計。丹不聽，進及無鹽，與赤眉戰死。衍乃亡命河東。","sortOrder":14},
  {"id":"s_work_tdk_7_15","chapterId":"ch_work_tdk_7","text":"來歙說隗嚣遣子入侍。嚣將王元以天下成败未可知，不願专心內事，遂說嚣曰：昔更始西都，四方响應，天下喁喁，謂之太平。一旦坏败，大王幾無所措。今南有子陽，北有文伯，江湖海岱，王公十數，而欲率儒生之說，弃萬乘之基，羁旅危國，以求萬全，此循覆車之軌，計之不可者也。今天水完富，士馬最強，北取西河上郡，東收三辅之地，案秦舊跡，表里山河，元請一丸泥為大王東封函穀關，此萬代一時也。若計不及此，宜蓄糗糧，養士馬，據隘自守，曠日持久，以待四方之变，圖王不成，其弊猶足以霸。要之，魚不可脱於泉；神龍失势，即還與蚯蚓同。嚣然元計，雖已遣子入质，猶負於险厄，欲专製方面，遂背漢。","sortOrder":15},
  {"id":"s_work_tdk_7_16","chapterId":"ch_work_tdk_7","text":"魏太祖與呂布戰於濮陽，不利。袁紹使人說太祖連和，使太祖家居鄴。太祖將許之，程昱見曰：竊聞將軍欲遣家居鄴，與袁紹連和，誠有之乎？太祖曰：然。昱曰：意者，將軍殆臨事而懼。不然，何慮之不深也？夫袁紹據燕、趙之地，有併天下之心，而智不能濟也。將軍自度能為之下乎？將軍以龍虎之威，可為韓、彭之事耶？昱愚不識大旨，以為將軍之志，不如田橫。田橫，齊一壮士耳，猶羞為高祖之臣。今將軍欲遣家往鄴，將北面而事袁紹。夫以將軍之聰明神武，而反不羞為袁紹之下，竊為將軍恥之。今兖州雖殘，尚有三城；能戰之士，不下萬人。若與文若昱等收而用之，霸王之業可成也。願將軍更慮之。太祖乃止。","sortOrder":16},
  {"id":"s_work_tdk_7_17","chapterId":"ch_work_tdk_7","text":"袁紹為盟主，有驕色，陳留太守張邈正義责之。紹令曹操殺邈，操不聽。邈心不自安，及操東击陶謙，令其將陳宮屯東郡。宮因說邈曰：今天下分崩，雄杰併起，君擁十萬之眾，當四戰之地，撫劍顧盼，亦足以為人豪，而反受製於人，不亦鄙乎？今州軍東征，其處空虛，呂布壮士，善戰無前。若迎之共據兖州，觀天下之形势，俟時事之变通，此亦縱橫之一時也。邈從之而反曹公。","sortOrder":17},
  {"id":"s_work_tdk_7_18","chapterId":"ch_work_tdk_7","text":"鍾會、邓艾既破蜀，蜀主降，會構艾。艾槛車徵，會陰懷異圖，厚待蜀將薑維等。維見而知其心，謂可構成扰亂，徐圖克复也，乃诡說之曰：聞君自淮南以來，算無遺策。晉道克昌，皆君為之。今复定蜀，威德震世，民高其功，而主畏其謀，欲以此安歸乎？夫韓信不背漢於扰攘，而見疑於既平；大夫种不從范蠡於五湖，卒伏劍而妄死。豈闇主愚臣哉？利害使之然也。今君大功既立，大德已著，何不法陶朱汎舟絕跡，全功保身，登峨眉之嶺，而從赤松遊乎？會曰：君言遠，我不能行。且為今之道，或未盡於此也。維曰：其他則君智力之所能，無煩於老夫矣。由是情好歡甚。會自稱益州牧以叛，欲授維兵五萬人，使為前驅。魏將士憤發，殺會及薑維。","sortOrder":18},
  {"id":"s_work_tdk_7_19","chapterId":"ch_work_tdk_7","text":"晉懷帝時，遼東太守庞本私憾東夷校尉李臻。鮮卑索連木津等為臻興義，實因而為亂，遂攻陷諸將。大单於慕容廆之長子翰言於廆曰：臣聞求諸侯莫如勤王，自古有為之君，靡不杖此以成事業者也。今連津跋扈，王師覆败，蒼生暑鱠，豈甚此乎？竖子外以庞本為名，內實幸而為寇，遼東傾没，乘便二周，中原兵亂，州師屢败，勤王杖義，今其時也。单於宜明九伐之威，救倒懸之命，數連津之罪，合義兵以誅之；上則興复遼邦，下則併吞二部，忠義彰於本朝，私利歸於我國，此則吾鸿漸之始也，終可以得志於諸侯。廆善之。遂戒器讨連津，斬之，立遼東郡。","sortOrder":19},
  {"id":"s_work_tdk_7_20","chapterId":"ch_work_tdk_7","text":"後秦秦王符生殺害忠良。秦人度於一時，如過百日。權翼及說東海王堅曰：今主上昏虐，天下離心。有德者昌，無德受殃，天之道也。一旦有風尘之变，非君王而誰？神器業重，不可令他人取之。願君王行湯武之事，以從民心。堅然之，引為謀主。遂废生立堅為秦王。","sortOrder":20},
  {"id":"s_work_tdk_7_21","chapterId":"ch_work_tdk_7","text":"宋孔熙先者，廣州刺史默之子也，有奸才，善占星氣，言江州分野出天子，上當見弒於骨肉。及大將軍彭城王義康幽於安城郡，熙先謂為其人也，遂說王詹事范晔曰：先君昔去廣州，朝謗紛紜，藉大將軍深相救解，得免艱危，曩受遺命，以死報德。今主上昏僻，殆天所弃。大將軍英斷聰敏，人神相屬，失職南垂，天下憤怨。今人情骚動，星文舛错。時至則不可拒，此之謂乎？若順天人之心，收慕義之士，內連寵戚，外結英豪，潛圖構於表里，疾雷奋於肘腋，然後誅除異義，崇奉聖明，因人之望，以號令天下，誰敢不從？小人維以七尺之驅、三寸之舌，立功立事，而歸諸君子。大人謂為何如？晔甚愕然。熙先重曰：昔毛琢竭節，不容於魏武；張溫畢議，見逐於孫權。彼二人者，國之信臣，時之俊乂。豈疵瑕暴露，言行玷缺然後至於禍哉？皆以廉直劲正，困於邪枉；高行妙節，不得久容。丈人之於本朝，不深於二主；人間雅譽，有過於兩臣，讒夫侧目，為日久矣。比肩競逐，庸可遂乎？近者殷鐵一言，而劉班碎首，彭城斥逐，徐童見疑，彼豈父母之讎、為代之怨？尋戈拔棘，自幼而然。所爭不過榮名势利，先後之間耳。及其末也，唯恐陷之不深，發之不早。戮及百口，猶曰不厭。是豈書籍遠事？可為寒心悼栗者也。今建大動，奉賢哲，圖難於易，以安易危，比之泰山，而去累卵，何苦不就？且崇树聖明，至德也；身享卿相，大業也；鸿名美號，三王五霸所以覆軍殺將而爭之也。一朝包括，不亦可乎？又有邇於此者，愚則未敢道。晔曰：何謂？熙先曰：丈人奕葉清華，而不得連姻帝室。國家作禽獸相處，丈人曾未恥之？晔門無內行，故熙先以此為激。晔默然。自是情好，遂密陰謀構矣。熙先专為謀主。事露，皆伏誅。","sortOrder":21},
  {"id":"s_work_tdk_7_22","chapterId":"ch_work_tdk_7","text":"周大將軍郭榮奉使詢隋高祖。高祖謂榮曰：吾雅尚山水，不好纓绂；過藉時來，遂叨名位。願以侯歸第，以保餘年。何如？榮對曰：今主上無道，人懷危懼。天命不常，能者代有。明公德高西伯，望極國華，方據六合以慰黎庶，反效童兒女子投坑落阱之言耶？高祖大驚曰：無妄言。族矣！及高祖作相，笑謂榮曰：前言果中，後竟代周室。","sortOrder":22},
  {"id":"s_work_tdk_7_23","chapterId":"ch_work_tdk_7","text":"隨高祖崩，葬於太陵。初疾也，玺書徵漢王谅。谅聞高祖崩，流言楊素篡位，大懼，以為诈也。發兵自守，陰謀為亂。南袭蒲州，取之。司馬參軍裴文安說谅曰：兵以拙速，不聞巧遲。今梓宮尚在仁寿，比其微兵東進，動移旬朔。若驍勇萬騎，卷甲宵行，直指長安，不盈十日。不逞之徒，擢授高位，付以心膂，共守京城，則以東府縣，非彼之有。然後大王鼓行而西，聲势一接，天下可指麾而定也。谅不從，乃親率大軍，屯於併介之間。上聞之，大懼，召贺若弼議之。弼曰：漢王先帝之子、陛下之弟，居連率之重，總方嶽之任，聲名震响，為天下所服，其舉事畢矣。然而進取之策有三：長驅入關，直據京師，西拒六軍，東收山東，上策也，如是則天下未可量；頓大軍於蒲州，使五千騎閉潼關，复齊舊境，據而都之，中策也，如是以力爭；若親居太原，徒遣其將來，下策也，如是成擒耳。上曰：公试為朕筹之，計將何出？弼曰：萧摩诃亡國之將，不可與圖大事；裴文安少年雖賢，不被任用。餘皆群小，顧恋妻孥，苟求自安，不能遠涉。必遣軍來攻蒲州，親居太原，為之窟穴。臣以為必出下策。果如弼所筹，乃以楊素為將，破之。","sortOrder":23},
  {"id":"s_work_tdk_7_24","chapterId":"ch_work_tdk_7","text":"隋煬帝親御六軍伐高麗，禮部尚書楚國公楊玄感據黎陽反。李密說玄感曰：天子遠征遼左，地去幽州，懸隔千里，南有臣海之限，北有胡戎之患，中間一道，理極艱危。今公權兵出其不意，長驅入蒯，直扼其喉，前有高麗，退無歸路，不過旬月，赍糧必盡。舉麾一召，其眾自降，不戰而克，計之上也。關中四塞，天府之國，有衛文昇，不足為意。今若率眾西入長安，天子雖還，失其襟帶，據险臨之，故當必克，萬全之策，計之中也。若隨近逐便，先向東都，頓兵堅城之下，勝負都未可知，此計之下也。玄感利洛陽寶货，曰：公之下策，我之上策也。遂围之。玄感失利，宵潰。王師追斬之。李密乃亡歸翟讓。","sortOrder":24},
  {"id":"s_work_tdk_7_25","chapterId":"ch_work_tdk_7","text":"隋煬帝初猜忌唐。高祖知之，常懷危懼。為太原留守，以讨击不利，恐為煬帝所譴，甚忧之。時太宗從在軍中，知隋將亡，潛圖義舉，以安天下。及進曰：大人何忧之甚也？當今主上無道，百姓愁怨，城門之外，皆已為賊，獨守小節，必旦暮死亡。若起義兵，實當人欲。且晉陽用武之地，足食足兵，大人居之，此乃天授，正可因機轉禍，以就功業。既天與不取，忧之何益？高祖大驚，深拒之。太宗趨而出，明日复進說曰：此為萬全之策，以救滅族之事。今王綱弛紊，盜賊遍天下，大人受命讨捕，其可盡乎？賊既不盡，自當獲罪。且又世傳李氏姓膺圖箓，李金才位望隆貴，一朝族滅。大人既能平賊，即又功當不賞，以此求活，其可得乎？高祖意少解，曰：我一夜思量汝言，大有道理。今日破家滅身，亦由汝；化家為國，亦由汝。於是定計，乃命太宗與晉陽令劉文靜，及門下客長孫順德、劉弘基等募兵。旬日之間，眾且一萬。斬留守副王威、高君雅，以诡請高祖祈雨於晉祠，將為不利故也。用裴寂計，准伊尹放太甲、霍光废昌邑故事，尊煬帝為太上皇，立代王侑以安隋室，傳檄諸郡，以彰義舉。秋七月，以精甲三萬，西圖關中。高祖杖白旗，誓眾於太原之野，引師即路，遂亡隋族，造我區夏。","sortOrder":25},
  {"id":"s_work_tdk_7_26","chapterId":"ch_work_tdk_7","text":"由此觀之，是知天下者，非一人之天下也，天下之天下也。所以王者必通三統，明天命所受者博，非獨一姓也。昔孔子論《詩》，至於殷士膚敏、灌將於京，喟然叹曰：富貴無常。不如是，王公其何以誡慎、民萌其何以勸勉？《易》曰：安不忘危，存不忘亡。是以身安而國家可保也。故知懼而思誡，乃有國之福者矣。","sortOrder":26},
  {"id":"s_work_tdk_7_27","chapterId":"ch_work_tdk_7","text":"時宜第二十一","sortOrder":27},
  {"id":"s_work_tdk_7_28","chapterId":"ch_work_tdk_7","text":"夫事有趨同而势異者，非事诡也，時之变耳。何以明其然耶？昔秦末，陳涉起靳。兵至陳，陳豪杰說涉曰：將軍被堅執銳，帥士卒以誅暴秦，复立楚社稷，功德宜為王。陳涉問陳餘張耳兩人，兩人對曰：將軍瞋目張胆，出萬死不顧一生之計，為天下除殘賊，今始至陳而王之，示天下以私；願將軍無王，急引兵而西，遣人立六國後，自為树党。如此，野無交兵，誅暴秦，據鹹陽以令諸侯，則帝業成矣。今獨王陳，恐天下解也。及楚漢時，郦食其漢謀撓楚權曰：昔湯伐桀，封其後於杞；武王伐紂，封其後於宋。今秦失德弃義，侵伐諸侯社稷，滅六國之後，使無立錐之地。陛下誠能复立六國後，此其君臣百姓，必皆戴陛下德，莫不向風慕義，願為臣妾，德義以行。陛下南面稱霸，楚必斂衽而朝。漢王曰：善。張良曰：誠用客之謀，陛下事去矣。漢王曰：何哉？良因發八難，其略曰：昔者湯伐桀，封其後於杞者，度能製桀之死命也。今陛下能製項籍之死命乎？其不可一也，武王入殷，表商容之闾，釋箕子之囚，封比幹之墓，今陛下能封聖人之墓、褒賢者之闾乎？其不可二也。發巨桥之粟，散鹿台之财，以赈貧民，今陛下能散府库以賜貧窮乎？其不可三也。殷事已畢，偃革為軒，倒載幹戈，示天下不复用武，今陛下能偃武修文，不复用兵乎？不可四也。放馬華山之陽，示無所，今陛下能放馬不复用乎？其不可五也。休牛桃林之野，示天下不复输積，今陛下能乎？其不可六也。且夫天下遊士，離親戚，弃墳墓，去故舊，從陛下者，日夜望咫尺之地；今复六國，立韓、魏、燕、趙、齊、楚、之後，餘無复立者，天下遊士，各歸事其主，從親戚，反故舊，陛下與誰取天下乎？其不可七也。且楚唯無強，六國者复撓而從之，陛下安得而臣之哉？其不可八也。誠用客之謀，則大事去矣。時王方食，吐哺骂郦生曰：竖儒幾败我事。趣令銷印，此異形者也。","sortOrder":28},
  {"id":"s_work_tdk_7_29","chapterId":"ch_work_tdk_7","text":"七國時，秦王謂陳軫曰：韓、魏相攻，期年不解。或曰救之便，或曰勿救便。寡人不能决，請為寡人决之。軫曰：昔卞莊子方刺虎，馆竖子止之曰：虎方食牛，牛甘必爭，爭必斗；斗則大者傷，小者死。從傷而刺之，一舉必有兩虎之名。今韓、魏相攻，期年不解，必是大國傷，小國亡。從傷而伐之，一舉必有兩實。此卞莊刺虎之類也。惠王曰：善。果如其言。初諸侯之叛秦也，秦將章邯围趙王於鉅鹿。楚懷王使項羽、宋義等北救趙，至安陽，留不進。羽謂義曰：今秦軍围鉅鹿，疾引兵渡河，楚击其外，趙應其內，破秦軍必矣。宋義曰：不然。夫摶牛之虻，不可以破蝨。今秦攻趙，戰勝則兵罢，我承其弊；不勝，則我引兵鼓行而西，必舉秦矣。故不如斗秦、趙。夫击輕銳，我不如公；坐運筹策，公不如我。羽曰：將軍戮力而攻秦，久留不行。今歲飢民貧，士卒食半菽，軍無見糧。乃飲酒高會，不引兵渡河、因趙食、與併力击秦，乃曰承其弊。夫以秦之強，攻新造之趙，其劫必舉趙。趙舉而秦強何弊之承？且國兵新破，王不安席，扫境內而屬將軍，國家安危，在此一舉。今不恤士卒而徇私，非社稷臣也。即夜入義帳中斬義，悉兵渡河，沈舟破釜，示士卒必死，無還心，大破秦軍。此異势者也。","sortOrder":29},
  {"id":"s_work_tdk_7_30","chapterId":"ch_work_tdk_7","text":"韓信伐趙，軍井陉，選輕騎二千人，人持一赤幟，從間道昇山而望趙軍。誡曰：趙見我走，必空壁逐我；若疾入趙壁，拔趙幟，立漢赤幟。信乃使萬人先行，出背水陣。平旦，信建大將之旗，鼓行出井陉口，趙开壁击之，大戰良久。於是信弃旗鼓，走水上軍。水上軍开入之，复疾戰。趙空壁爭漢旗鼓，逐韓信。韓信等已入水上軍，軍皆殊死戰，不可败。信所出奇兵二千騎，共候趙空壁逐利，則馳入趙壁，皆拔趙旗，立漢赤幟二千。趙軍已不能得信等，欲還歸壁，皆漢赤幟而大驚，以為皆已得趙王將矣。遂亂，遁走。趙將雖斬之，不能禁也。於是漢兵乘击大破之，虜趙軍。諸將效首虜，皆贺信，因問曰：兵法石背山陵，前左水泽。今者反背水陣，然竟以勝，此何術也？信曰：兵法不曰：陷之死地而後生，置之亡地而後存。且信非得素撫循士大夫也，此所謂驅市人而戰之，其势非置之死地，使人人自為戰。今與之生地皆走，寧尚可得而用之？又高祖劫五諸侯兵，入彭城。項羽聞之，乃引兵去齊，與漢大戰睢水上，大破漢軍，多殺士卒，睢水為之不流。此異情者也。","sortOrder":30},
  {"id":"s_work_tdk_7_31","chapterId":"ch_work_tdk_7","text":"漢王在漢中，韓信說曰：今士卒皆山東人，跂而望歸，及其鋒，東向可以爭天下。後漢光武北至蒯，聞邯戰兵到，世祖欲南歸，召官屬計議。耿弇曰：今兵從南來，不可南行。漁陽太守彭寵、公之邑人；上郡太守即弇父也。發此兩郡控絃萬騎，邯戰不足慮也。世祖官屬不從，遂南馳。官屬各分散。後漢李催等追困天子於曹陽，沮授說袁紹曰：將軍累葉台辅，世濟忠義。今朝廷播越，宗廟殘毀。觀諸州郡，雖外讬義兵，內實相圖，未有忧在社稷、恤人之意。且今州城粗定，兵強士附，西迎大駕，即宮鄴都，挟天子而令諸侯，畜士馬以讨不庭，誰能御之？若不早定，必有先之者。夫權不失機，功不厭速，願其圖之。紹不從，魏武果迎漢帝，紹遂败。梁武帝萧衍初起義，杜思冲勸帝迎南康王都襄陽，正尊號，帝不從。張弘策曰：今以南康置人手中，彼挟天子以令諸侯，節下前去，為人所使。此豈歲寒之計耶？帝曰：若前途大事不捷，故自蘭艾同焚。若功業克建，誰敢不從？豈是碌碌受人處分於江南，立新野郡，以集新附哉？不從，遂進兵克建鄴而有江左。此情與形势之異者也。隨時变通，不可執一矣。","sortOrder":31},
  {"id":"s_work_tdk_7_32","chapterId":"ch_work_tdk_7","text":"《長短經》　唐　趙蕤","sortOrder":32},
  {"id":"s_work_tdk_8_1","chapterId":"ch_work_tdk_8","text":"卷八雜說","sortOrder":1},
  {"id":"s_work_tdk_8_2","chapterId":"ch_work_tdk_8","text":"釣情第二十二","sortOrder":2},
  {"id":"s_work_tdk_8_3","chapterId":"ch_work_tdk_8","text":"孔子曰：未見顏色而言，謂之瞽。又曰：未信，則以為謗己，孫卿曰：語而當，智也；默而當，知也。尸子曰：聽言耳目不懼，视聽不深，則善言不往焉。是知將語者，必先釣於人情，自古然矣。","sortOrder":3},
  {"id":"s_work_tdk_8_4","chapterId":"ch_work_tdk_8","text":"故《韓子》曰：夫說之難也，在知所說之心，可以吾說當之。說之以厚利，則見下節而遇卑賤，必弃遠矣。說之以名高，則見無心而遠事情，必不收矣。事以密成，語以泄败，未必其身泄之也，而說及其所匿之事，如是者身危。貴人有過端，而說者明言善議以推其惡者，身危。貴人得計而欲自以為功，說者與知焉，則身危。強之以甚所不為，止之以其所不能已者，身危。又曰：與之論大人，則以為間己；與之論細人，則以為粥權。論其所愛，則以為供資；論其所惜，則以為嘗己。順事陳意，則曰怯懦而不盡；慮事廣肆，則曰草野而倨侮。此不可不知也。彼自知其計，則無以其失窮之；自勇其斷，則無以其敵怒之。","sortOrder":4},
  {"id":"s_work_tdk_8_5","chapterId":"ch_work_tdk_8","text":"荀悅曰：夫臣下之所以難言者，何也？言出乎身，則咎悔及之矣。故曰：舉過揭非，則有幹忤之咎；勸励教誨，則有俠上之譏。言而當，則恥其勝己也；言而不當，則賤其愚也。先己而同，則惡其奪己明也；後己而同，則以為從順也。违下從下，則以為諂諛也；违上從下，則以為雷同也。與眾共言，則以為順負也；违眾獨言，則以為专美也。言而淺露，則簡而薄之；深妙弘遠，則不知而非之。特見獨智，則眾惡其蓋之也，雖是而不見稱；與眾同智，則以為附隨也，雖得之不以為功。謙讓不爭，則以為易窮；言而不盡，則以為懷隱；進說竭情，則以為不知。量言而不效，則受其怨责；言而事效，則以為固當。利於上不利於下，或便於左則不便於右，或合於前而忤於後，此下情所以常不通。仲尼發憤稱予欲無言者，蓋為語之難也。","sortOrder":5},
  {"id":"s_work_tdk_8_6","chapterId":"ch_work_tdk_8","text":"何以明其難耶？昔宋有富人，天雨牆坏。其子曰：不筑，且有盜。其鄰人亦雲。暮而果大亡，其家智其子而疑鄰人之父。鄭武公欲伐胡，乃以其子妻之。因問群臣：吾欲用兵，誰可伐者？關其思曰：胡可。乃戮關其思，曰：胡，兄弟之國也。子言伐之，何也？胡君聞之，以鄭為親己而不備鄭。鄭人袭胡取之。此二說者，其智皆當矣。然而甚者為戮，薄者見疑。非智之難也，處智則難。衛人迎新婦，婦上車，問驂馬誰馬也？御曰：御籍之。新婦謂仆曰：拊驂無苦服。車至門，拔，教逆毋滅橹，將失火。入室，見臼曰：徙牖下，妨往來者。主人大笑之。此三言皆要言也，然而不免為笑者，早晚之時失矣。此說之難也。","sortOrder":6},
  {"id":"s_work_tdk_8_7","chapterId":"ch_work_tdk_8","text":"說者知其難也，故語必有釣，以取人情。何以明之？昔齊王後死，欲置後而未定，使群臣議。薛公田婴欲中王之意，因獻十珥而美其一。旦日，因問美珥所在，因勸立以為王後。齊王大悅，遂重薛公。此情可物釣也。申不害始合於韓王，然未知王之所欲也，恐言而未必中於王也。王問申子曰：吾誰與而可？對曰：此安危之要，國家之大事也。臣請深惟而苦思之。乃微謂趙卓、韓晁曰：子皆國之辯士也。夫為人臣者，言何必用？盡忠而已矣。二人各進議於王以事。申子微视王之所說，以言於王。王大悅之。此情可以言釣也。吳伐越，越栖於會稽。句踐喟然叹曰：吾終此乎？大夫种曰：湯系夏台，文王囚羑里，重耳奔翟，齊小白奔莒，其卒霸王。由是觀之，何遽不為福乎？句踐乃得免，務報吳。大夫种曰：臣觀吳王政驕矣，請嘗之。乃貸粟以卜其事，子胥諫勿與，王遂與之。子胥曰：王不聽諫，後三年，吳其墟矣。太宰嚭聞之，讒曰：伍員貌忠而實忍人。吳遂殺子胥。此情可以事釣也。客以淳髡見梁惠王。惠王屏左右，再見之，終無言。惠王怪之，讓客。客謂淳於髡，髡曰：吾前見王，王志在馳逐；後复見王，王志在音聲，是以默然。客具以報王。王大駭曰：淳於先生、誠聖人也。前有獻善馬，寡人未及试，會生來；後有獻謳者，未及试，又會生來。寡人雖屏人，然私心在彼。此情可以志釣也。智伯從韓、魏之君伐趙，韓、魏用趙臣張孟談之計，陰謀叛智伯。張孟談因朝智伯，遇智果於轅門之外。智果入見智伯曰：二主殆將有变。臣遇張孟談，察其志矜而行高，見二君色動而变，必背君矣。智伯不從。智果出，遂更其姓為辅氏。張孟談入見趙襄之曰：臣遇智果於轅門之外，其视有疑臣之心，入見智伯而更其族。今暮不击，必後之矣。襄子曰：诺。因與魏、韓殺守隄之吏，决水灌智伯軍。此情可以视釣也。殷浩仕晉有盛名，時人觀其出處，以卜江左興亡。此情可以賢釣也。《鈐經》曰：喜色〈石鳥〉然以出，怒色麃然以侮，欲色熰然以愉，懼色憚然以下，忧色懼然以靜。此情可以色釣也。","sortOrder":7},
  {"id":"s_work_tdk_8_8","chapterId":"ch_work_tdk_8","text":"由是觀之，夫人情必見於物。能知此者，可以納說於人主矣。","sortOrder":8},
  {"id":"s_work_tdk_8_9","chapterId":"ch_work_tdk_8","text":"诡信第二十三","sortOrder":9},
  {"id":"s_work_tdk_8_10","chapterId":"ch_work_tdk_8","text":"孔子曰：君子貞而不谅。又曰：信近於義，言可覆也。由是言之，唯義所在，不必信也。何以明之？","sortOrder":10},
  {"id":"s_work_tdk_8_11","chapterId":"ch_work_tdk_8","text":"葉公問孔子曰：吾党有直躬者，其父攘羊，而子證之。孔子曰：吾党有直躬者，異於是。父為子隱，子為父穩，直在其中矣。","sortOrder":11},
  {"id":"s_work_tdk_8_12","chapterId":"ch_work_tdk_8","text":"楚子围宋，宋求救於晉。晉侯使解楊如宋，使為降楚，曰：晉師悉起，將至矣。鄭人囚而獻諸楚。楚子厚賂之，使反其言，許之。登諸樓車，使呼宋人而告之，遂致其君命。楚子將殺之，使與之言曰：爾既許不穀而反之，何故？非我無信，汝則弃之。速即爾刑。對曰：臣聞之，君能製命為義，臣能承命為信，信載義而行之為利。謀不失利，以衛社稷，民之主也。義無二信，信無二命。君之賂臣，不知命也。受命以出，有死無霣，又何賂乎？臣之許君，以成命也。死而成命，臣之祿也。寡君有信臣，下臣獲考，死又何求？楚子舍之以歸。","sortOrder":12},
  {"id":"s_work_tdk_8_13","chapterId":"ch_work_tdk_8","text":"顏率欲見公仲，公仲不見。顏率謂公仲之謁者曰：公仲必以率為伪也，故不見率。公仲好內，率曰好士；公仲啬於财，率曰散施；公仲無行，率曰好義。自今以來，率且正言之而已矣。公仲之謁者以告公仲，公仲遽起而見之。","sortOrder":13},
  {"id":"s_work_tdk_8_14","chapterId":"ch_work_tdk_8","text":"齊伐燕，得十城。燕王使蘇秦說齊，齊歸燕十城。蘇秦還燕，人或毀之曰：蘇秦左右賣國，反覆臣也，將作亂，燕王意疏之，舍而不用。蘇秦恐被罪，入見王曰：臣東周之鄙人也，無尺寸之功，而王親拜之於廟，禮之於庭。今臣為王卻齊之兵，而功得十城，宜以益親。今來而王不官臣者，人必有以不信傷臣於王者。且臣之不信，王之福也。使臣信如尾生、廉如伯夷、孝如曾參，三者天下之高行，而以事王，可乎？燕王曰：可也。蘇秦曰：有此臣，亦不事王矣。孝如曾參，義不離其親、宿昔於外，王又安得使之步行十里，而事弱燕之危王哉？廉如伯夷，義不為孤竹君之嗣，不　為武王之臣，不受封侯，而饿死於首陽之下，有廉如此者，王又安能使之步行十里，而進取於齊哉？信如尾生，與女子期於梁柱之下，女子不來，水至不去，抱梁柱而死，有信如此，何肯扬燕、秦之威，卻齊之強兵哉。且夫信行者，所以自為也，非所以為人也。皆自覆之術，非進取之道也。且三王代興，五霸迭盛，皆不自覆。君以自覆可乎？則齊不益於營丘，足下不窥於邊城之外。且臣之有老母於東周，離老母而事足下，去自覆之術，而行進取之道，臣之趨固不與足下合者。足下者，自覆之君也；仆者，進取之臣也。臣所謂以忠信得罪於君也。燕王曰：夫仆信又何罪之有也？對曰：足下不知也。臣鄰家有遠為吏者，其妻私人。其夫且歸，其私者忧之。其妻曰：公勿忧也，吾已為藥酒待之矣。後二日夫至，其妻使妾奉卮酒進之。妾知其藥酒也，進之則殺主父，言之則逐主母，乃佯僵弃酒。主父大怒而笞之。妾之弃酒，上以活主父，下以存主母。忠至如此，然不免於笞。此以忠信得罪也。臣之事適不幸而類妾之弃酒也。且臣之事足下，亢義益國，今乃得罪，臣恐天下後事足下者，莫敢自必也。且臣之說齊，曾不欺之也。後之說齊者，莫如臣之言，雖尧舜之智，不敢取之。燕王曰：善。复厚遇之。","sortOrder":14},
  {"id":"s_work_tdk_8_15","chapterId":"ch_work_tdk_8","text":"由此觀之，故知譎即信也，诡即忠也。夫诡譎之行，乃忠信之本焉。","sortOrder":15},
  {"id":"s_work_tdk_8_16","chapterId":"ch_work_tdk_8","text":"忠疑第二十四","sortOrder":16},
  {"id":"s_work_tdk_8_17","chapterId":"ch_work_tdk_8","text":"夫毀譽是非，不可定矣。以漢高之略，而陳平之謀，毀之則疏，譽之則親；以文帝之明，而魏尚之忠，繩之以法則為罪，施之以德則為功。知世之聽者，多有所尢，多有尢即聽必悖矣。何以知其然耶？","sortOrder":17},
  {"id":"s_work_tdk_8_18","chapterId":"ch_work_tdk_8","text":"《呂氏春秋》雲：人有亡鈇者，意其鄰之子，视其行步、顏色、言語、動作、態度，無為而不竊鈇者也。竊掘其穀而得其斧，他日复見其鄰之子，動作態度無似竊鈇者也。其鄰子非变也，己則变之。变之者無他，有所尢矣。邾之故，為甲裳以帛。公息忌謂邾之君曰：不若以組。邾君曰：善。下令令官為甲必以組。公息忌因令其家皆為組。人有傷之者曰：公息忌之所以欲用組者，其家為因裳多為組也。邾君不悅，於是乎止，無以組。邾君有所尢也。邪之故為甲，以組而便也，公息忌雖多為組，何傷？以組不便，公息忌雖無以為組，亦何益？為組與不為組，不足以累公息忌之說也。","sortOrder":18},
  {"id":"s_work_tdk_8_19","chapterId":"ch_work_tdk_8","text":"凡聽有不可不察。樓缓曰：公父文伯仕於魯，病而死。女子為自殺於房中者二人，其母聞之弗哭。其相室曰：焉言子死而弗哭乎？其母曰：孔子賢人也，逐於魯而是人弗隨之。今死，婦人為自殺。若是者，必其於長者薄，而於婦人厚。故從母言之，是為賢母；從妻言之，是不免於妒妻也。故其言一也，言者異則人心变矣。樂羊為魏將而攻中山，其子在中山。中山之君烹其子而遺之羹，樂羊盡啜之。文侯曰：樂羊以我故，食其子之肉。堵師贊曰：其子且食之，其誰不食？樂羊罢中山，文侯賞其功而疑其心。《淮南子》曰：親母為其子扢禿，出血至耳，見者以為愛子之至也。使在於繼母，則過者以為悷也。事之情一也，所從觀者異耳。從城上视牛如羊，视羊如豚，所居高也。窥面於盤水則圓，於拓則〈阝耆〉。面形不变其故，有所圓有所〈阝耆〉者，所自窥之異也。今吾雖欲正身而待物，庸詎知世之所自窥我者乎？是知天下是非，無所定也。世各是其所是，非其所非。今吾欲擇是而居之、擇非而去之，不知世之所是非者，孰是孰非哉？故有忠而見疑者，不可不察。","sortOrder":19},
  {"id":"s_work_tdk_8_20","chapterId":"ch_work_tdk_8","text":"用無用第二十五","sortOrder":20},
  {"id":"s_work_tdk_8_21","chapterId":"ch_work_tdk_8","text":"古人有言曰：得鳥者，羅之一目；然張一目之羅，終不能得鳥矣。鳥所以能遠飛者，六翮之力也；然無眾毛之助，則飛不能遠矣。以是推之，無用之為用也大矣。故惠子謂莊子曰：子言無用矣。莊子曰：知無用而始可與言用矣。夫天地非不廣且大也，人之所用容足耳。然則削足而墊之至黃泉，人尚有用乎？惠子曰：無用。莊子曰：然則無用之為用也亦明矣。昔陳平智有餘而見疑，周勃质朴忠而見信。夫仁義不足相懷，則智者以有餘見疑，而朴者以不足取信矣。漢徵處士樊英、楊厚，朝廷若待神明，至竟無他異。李固、朱穆以為處士純盜虛名，無益於用。然而進希之以成器，世主禮之以得眾。原其無用，亦所以為用也。而惑者忽不踐之地，賒無用之功，至乃誚謲遠術，賤斥國華，不亦過乎？","sortOrder":21},
  {"id":"s_work_tdk_8_22","chapterId":"ch_work_tdk_8","text":"恩生怨第二十六","sortOrder":22},
  {"id":"s_work_tdk_8_23","chapterId":"ch_work_tdk_8","text":"《傳》稱諺曰：非所怨勿怨，寡人怨矣。是知幾怨者，不怨於所疏，必怨於親密。何以明之？高子曰：《小弁》，小人之詩也。孟子曰：何以言之？高子曰：怨乎！孟子曰：固哉！夫高叟之為《詩》也。有越人於此，關弓而射我，我則談笑而道之。無他，疏之也。兄弟關弓而射我，我則泣涕而道之。無他，戚之也。然而《小弁》之怨，親親也。親親，仁也。晉使韓簡子视秦師，雲：師少於我，斗士倍我。公曰：何故？對曰：出因其資，人用其寵，飢食其粟，三施而不報，所以來也。杜鄴說王音曰：鄴聞人情恩深者其養謹，愛至者其求謹。夫戚而不見異，親而不見殊，孰能無怨？此《棠棣》《角弓》之所作也。由此觀之，故知怨也者，親之也；恩也者怨之所生也，不可不察。","sortOrder":23},
  {"id":"s_work_tdk_8_24","chapterId":"ch_work_tdk_8","text":"诡順第二十七","sortOrder":24},
  {"id":"s_work_tdk_8_25","chapterId":"ch_work_tdk_8","text":"趙子曰：夫雲雷世屯、瞻乌未定，當此時也，在君為君委质治人，各為其主用職耳。故高祖賞季布之罪，晉文嘉寺人之過，雖前窘莫之怨也，可謂過於大體矣。","sortOrder":25},
  {"id":"s_work_tdk_8_26","chapterId":"ch_work_tdk_8","text":"昔晉文公初出亡，獻公使寺人披攻之蒲城，披斬其袪。及反國，呂郄畏偪，將焚公宮而殺之。寺人披請見，公使讓之曰：蒲城之役，君命一宿，汝即至。其後餘從狄君以田渭濱，汝為惠公來求殺餘，命汝三宿，汝中宿至。雖有君命，何其速也？對曰：臣謂君之入也，其知之矣。若猶未也，又將及難。君命無二，古之製也。除君之惡，唯力是视。蒲人、狄人，餘何有焉？今君即位，其無蒲狄乎？齊桓公置射鉤而使管仲相，君若易之，何辱命焉？行者甚眾，豈唯刑臣？軫見之，以難告，得免呂郄之難。","sortOrder":26},
  {"id":"s_work_tdk_8_27","chapterId":"ch_work_tdk_8","text":"陳軫與張儀俱事秦惠王，惠王皆重之。二人爭寵，儀惡軫於王曰：軫重幣輕使秦楚之間，將為國交也。今楚不善於秦而善於軫，軫為楚厚、為秦薄也。軫欲去秦而之楚，王何不聽之？王乃召軫而問之，軫曰：臣願之楚，臣出必故之楚，且明臣為楚與不也。昔楚有兩妻者，王聞之乎？王曰：弗聞。軫曰：楚有兩妻者，人挑其長者，長者骂之；挑其少者，少复者挑之。居無幾何，有兩妻者死。客為挑者曰：為汝娶少者乎？長者乎？挑者曰：娶長者。客曰：長者骂汝，少者挑汝汝何故娶長者？挑者曰：居人之所，則欲其挑我；為我之妻，則欲其骂人。今楚王明主，昭陽賢相，使軫為臣，常以國情输楚，楚王將不留臣，昭陽將不與臣從事矣。臣何故之楚？臣出必故之楚，足以明臣為楚與不也。軫出，儀人問王曰：軫果欲之楚不？王曰：然。儀曰：軫不為楚，楚王何為欲之？王复以儀言謂軫。軫曰：然。王曰：儀之言果信矣。軫曰：非獨儀知之，行道之人盡知之矣。子胥忠於君，而天下皆爭以為臣；曾參、孝己愛於親，而天下皆願以為子。故賣仆妾不出闾巷售者，良軫妾也；出婦嫁於乡曲者，必善婦也。今軫若不忠於君，楚亦何以為臣乎？忠且見弃，軫不之楚，將何歸乎？王以其言為然，遂厚待之。惠王終相張儀，軫遂奔楚。","sortOrder":27},
  {"id":"s_work_tdk_8_28","chapterId":"ch_work_tdk_8","text":"韓信初為齊王時，蒯通說使三分天下，信不聽。後知漢畏惡其能，乃與陳豨謀反。事泄，呂太後以計擒之。方斬，曰：吾悔不聽蒯通之計，乃為兒女子所诈。豈非天哉？高祖歸，乃詔齊捕通。通至，上曰：若教淮陰侯反耶？曰：然。臣固教之。竖子用臣之計，陛下安得而夷之乎？上怒曰：烹之。通曰：嗟乎！冤哉烹也！上曰：若教韓信反，何冤？對曰：秦之綱弛而維絕，山東大扰，異姓併起，英雋乌聚。秦失其鹿，天下共逐之，於是高材疾足者先得焉。跖之狗吠尧，尧非不仁，狗固次非其主。當是時，臣獨知韓信，非知陛下也。且天下銳精持鋒，欲為陛下所求者甚眾，故力不能耳。又可盡烹耶？高帝曰：置之。乃釋通之罪也。","sortOrder":28},
  {"id":"s_work_tdk_8_29","chapterId":"ch_work_tdk_8","text":"初吳王濞與七國謀反，及發，濟北王欲自殺。齊人公孫玃謂濟北王曰：臣請试為大王明說梁王，通意天子。說而不用，死未晚也。公孫玃遂見梁王曰：夫濟北之北東接強齊，南牵吳越，北胁燕趙，此四分五裂之國。權不足以自守，劲不足以扞寇，又非有奇佐之士以待難也，雖墜言於吳，非其正計也。昔鄭祭仲許宋人立公子突以活其君，非義也。《春秋》記之，為其以生易死，以存易亡也。乡使濟北見情，實示不從之端，則吳必先歷齊，軍濟北，招燕趙而總之。如此，則山東之從結而無隙矣。今吳楚之王，練諸侯之兵，驅白徒之眾，西與天子爭衡，濟北獨底節堅守不下。便吳失與而無助，跬行獨進，瓦解土崩，破败而不救者，未必非濟北之力也。夫以區區之濟北，而與諸侯爭強，是以羊犢之弱，而捍虎狼之敵也。守職不撓，可謂誠一矣。功義如此，尚見疑於上，胁肩低首，累足撫襟，有自悔不前之心，非社稷之利也。臣恐藩臣守職者疑之。臣竊料之，能歷西山、径長樂、抵未央、攘袂而正議者，獨大王耳。上有全亡之功，下有安百姓之名，德淪於骨髓，恩加於無窮，願大王留意詳惟之。孝王大說，使人馳以聞。濟北王得不坐，徙封於菑川。","sortOrder":29},
  {"id":"s_work_tdk_8_30","chapterId":"ch_work_tdk_8","text":"陳琳典袁紹文章。袁氏败，琳歸太祖。太祖謂曰：卿昔為本初移書，但可罪状孤而已，惡止其身，何乃上及祖父耶？琳謝曰：楚漢未分，蒯通進策於韓信；乾時之戰，管仲肆力於子糾。唯欲效計其主，取福一時。故跖之客，可以刺由；桀之狗，可使吠尧也。今明公必能進賢於忿後，弃愚於愛前，四方革面，英豪宅心矣。唯明公裁之。太祖曰：善。厚待之。","sortOrder":30},
  {"id":"s_work_tdk_8_31","chapterId":"ch_work_tdk_8","text":"由此觀之，是知晉侯殺里克，漢祖戮丁公，石勒誅棗嵩，劉備薄許靖，良有以也。故范晔曰：夫人守義於故主，斯可以事新主；恥以其眾受寵，斯可以受大寵。若乃言之者雖誠而聞之者未譬，豈苟進之悅，易以情納；持正之忤，難以理求？誠能釋利以循道，居方以從義，君子之概也。","sortOrder":31},
  {"id":"s_work_tdk_8_32","chapterId":"ch_work_tdk_8","text":"難必第二十八","sortOrder":32},
  {"id":"s_work_tdk_8_33","chapterId":"ch_work_tdk_8","text":"夫人主莫不欲其臣之忠，而忠未必信。故伍員流於江；萇弘死於蜀，其血三年而化為碧。凡人親莫不欲其子之孝，而孝未必愛。故孝己忧而曾參悲，此難必者也。何以言之？","sortOrder":33},
  {"id":"s_work_tdk_8_34","chapterId":"ch_work_tdk_8","text":"魏文侯問狐卷子曰：父子兄弟君臣之賢足恃乎？對曰：不足恃也。何者？父賢不過尧而丹朱放，子賢不過舜而瞽叟拘，兄賢不過舜而象傲，弟賢不過周公而管蔡誅，臣賢不過湯武而桀紂伐。望人者不至，恃人者不久。君欲理亦從身始，人何可恃乎？漢時，梁孝王藏匿羊勝、公孫诡。韓安國泣說梁孝王曰：大王自度於皇帝，孰與太上皇之與高皇帝、及皇帝之與臨江王親？孝王曰：弗如也。安國曰：夫太上、臨江，親父子間，然而高帝曰：提三尺劍，取天下者，朕也。故太上終不得製事，居櫟陽。臨江王，適長太子也，以言過废王臨江，用宮垣事卒自殺中尉府。何者？治天下終不以私害公。語曰：雖有親父，安知其不為孝？雖有親兄，安知其不為狼？今大王列在諸侯，說一邪臣，浮說犯上，禁撓明法，天子以太後故，不忍致法於王。太後日夜泣涕，幸大王自改，而大王終不覺悟。有如太後車即晏駕，大王尚誰攀乎？語未卒，孝王出羊勝等。由是觀之，安在其可必哉？","sortOrder":34},
  {"id":"s_work_tdk_8_35","chapterId":"ch_work_tdk_8","text":"語曰：以權利合者，權利盡而交疏。又曰：以色事人者，色衰則愛絕。此言财色不可必也。墨子曰：雖有慈父，不愛無益之子。黃石公曰：主不可以無德，無德則臣叛。此言臣子不可必也。《詩》雲：自求伊祐。有旨哉！有旨哉！","sortOrder":35},
  {"id":"s_work_tdk_8_36","chapterId":"ch_work_tdk_8","text":"運命第二十九","sortOrder":36},
  {"id":"s_work_tdk_8_37","chapterId":"ch_work_tdk_8","text":"夫天道性命，聖人所稀言也。雖有其旨，難得而詳。然校之古今，错綜其紀，乘乎三势，亦可以仿佛其略。何以言之？","sortOrder":37},
  {"id":"s_work_tdk_8_38","chapterId":"ch_work_tdk_8","text":"荀悅雲：凡三光精氣变異，此皆陰陽之精也。其本在地，而上發於天。政失於此，則变見於彼。不其然乎？今稱《洪范》咎徵，則有尧湯水旱之灾；消灾复異，則有周宣《雲漢》寧莫我聽；《易》稱積善餘慶，則有顏冉短折之凶。善惡之報，類变萬端，不可齊一。故视聽者惑焉！常试言之。孔子曰：死生有命。又曰：不得其死。又曰：幸而免者。夫死生有命，其正理也；不得其死者，未可以死而死也；幸而免者，可以死而不死也。此皆性命三势之理也。推此以及教化，則亦如之。人有不教化而自成者，有待教化而後成者，有雖加教化而終不成者。故上智與下愚不移，至於中人則可上可下。推此以及天道，則亦如之。灾祥之應，無所疑焉。故尧湯水旱，天數也。《洪范》咎徵，人事也。魯僖霪雨，可救之應也；周宣旱甚，難变之势也；顏、冉之凶，性命之本也。","sortOrder":38},
  {"id":"s_work_tdk_8_39","chapterId":"ch_work_tdk_8","text":"易曰：有天道焉，有地道焉，有人道焉。言其異也。兼三才而兩之，言其同也。故天人之道，有同有異。據其所以異，而责其所以同，斯則惑矣。守其所以同，而求其所以異，則取弊矣。遲速深淺，变化错乎其中，其故參差難得而均也。天地人物之理，莫不同之。故君子盡心焉、盡力焉，以邀命也。《易》曰：窮理盡性以至於命。此之謂矣。","sortOrder":39},
  {"id":"s_work_tdk_8_40","chapterId":"ch_work_tdk_8","text":"大私第三十","sortOrder":40},
  {"id":"s_work_tdk_8_41","chapterId":"ch_work_tdk_8","text":"《管子》曰：知與之為取，政之寶也。《周書》曰：將欲取之，必故與之。何以徵其然耶？黃石公曰：得前勿有，立而勿取，為者則已，有者則士，焉知利之所在。彼為諸侯，已為天子，使城自仔，令士自取，王者之道也。《尸子》曰：尧養無告，禹愛辜人。此先王之所以安危而懷遠也，聖人於大私之中也為無私。湯曰：朕身有罪，無及萬方；萬方有罪，朕身受之。湯不私其身而私萬方。文王曰：苟有仁人，何必周親？文王不私親而私萬國。先王非無私也。所私者與人不同，此知大私者也。由是言之，夫唯不私，故能成其私；不利而利之，乃利大者矣。","sortOrder":41},
  {"id":"s_work_tdk_8_42","chapterId":"ch_work_tdk_8","text":"败功第三十一","sortOrder":42},
  {"id":"s_work_tdk_8_43","chapterId":"ch_work_tdk_8","text":"文子曰：有功離仁義者即見疑，有罪不失仁心者必見信。故仁義者，天下之尊爵也。何以言之？昔者楚恭王有疾，召其大夫曰：不穀不德，少主社稷。失先君之緒，覆楚國之師，不穀之罪也。若以宗廟之靈，得保首領以没請為靈若厲。大夫許緒！及其卒也，子囊曰：不然。夫事君者從其善，不從其過。赫赫楚國而君臨之，撫征南海及諸夏，其寵大矣。有是寵也，而知其過，可不謂恭乎？大夫從之。此因過以為功者也。魏將王昶、陳泰兵败，大將軍以為已過。習凿齒論曰：司馬大將軍引二败以為已過，過銷而業昌，可謂智矣。夫忘其败而下思其報，雖欲勿康，其可得乎？若乃讳败推過，歸咎萬物，上下離心，賢愚釋體，是楚再败而晉再克，谬之甚矣。夫人君苟統斯理，而以御國，行雖失而名扬，兵雖挫而戰勝。百败猶可，况再败乎？此因败以成功也。故知智者六舉事也，因禍為福，轉败為功，自古然矣。","sortOrder":43},
  {"id":"s_work_tdk_8_44","chapterId":"ch_work_tdk_8","text":"昏智第三十二","sortOrder":44},
  {"id":"s_work_tdk_8_45","chapterId":"ch_work_tdk_8","text":"夫神者，智之淵也，神清則智明；智者，心之符也，智公則心平。今士有神清智明而闇於成败者，非愚也，以聲色势利怒愛昏其智矣。何以言之？","sortOrder":45},
  {"id":"s_work_tdk_8_46","chapterId":"ch_work_tdk_8","text":"昔孔子攝魯相，齊景公聞而懼曰：孔子為政，魯必霸。霸則吾地近焉，我之為先併矣。犁且曰：去仲尼猶吹毛耳。君何不延之以重祿，遺哀公以女樂？哀公親樂之，必怠於政。仲尼必諫，諫不聽，必輕絕魯。於是選齊國中女子好者八十人，皆衣文繡之衣而舞康樂，遺魯君。魯君受齊女樂，怠於事，三日不聽政。孔子曰：彼婦人之口，可以出走。遂適衛。此昏於聲色者也。","sortOrder":46},
  {"id":"s_work_tdk_8_47","chapterId":"ch_work_tdk_8","text":"太史公曰：平原君翩翩濁代之佳公子也，然不睹大體。語曰：利令智昏。平原君貪冯亭邪說，使趙陷長平四十餘萬，邯戰幾亡。此昏於利者也。","sortOrder":47},
  {"id":"s_work_tdk_8_48","chapterId":"ch_work_tdk_8","text":"《後漢　班固傳》評曰：昔班固傷司馬遷雲：遷博物洽聞，不能以智免極刑。然固身亦自陷大戮，可謂智及之而不能守。古人所以致論於目睫邪？此昏於势者。","sortOrder":48},
  {"id":"s_work_tdk_8_49","chapterId":"ch_work_tdk_8","text":"《尸子》曰：夫吳越之國，以臣妾為殉，中國聞而非之。及怒，則以親戚殉一言。夫智在公則愛吳越之臣，妾在私則忘其親戚。非智損也，怒弇之也。好亦然矣。語曰：莫知其子之惡。非智損也，愛弇之也。是故論貴賤、辨是非者，必且自公心言之自公心聽之，而後可知也。故范晔曰：夫利不在身，以之謀事則智；慮不私已，以之斷義則厲。誠能回觀物之智，而為反身之察，則能恕而自鑒。","sortOrder":49},
  {"id":"s_work_tdk_8_50","chapterId":"ch_work_tdk_8","text":"卑政第三十三","sortOrder":50},
  {"id":"s_work_tdk_8_51","chapterId":"ch_work_tdk_8","text":"《淮南子》曰：齊溺人以金玉，不如尋常之纏。《韓子》曰：百日不食，以待梁肉，饿者不肯。此言政貴卑以濟事者也。何以言之？韓非曰：所謂知者微妙之言，上知之所難也。今為眾人法，而以為上知之所難也，則人無從識之矣。故糟糠不厭者，不待梁肉而飽；短褐不完者，不須文繡而好。以是言之，夫治世之事，急者不得，則缓者非務也。今所治之政，人間之事。夫婦之所明知者不用，而慕上知之所難論，則其於人過遠矣。是知微妙之言，非人務也。故《君文子》曰：凡有理而無益於治者，君子不言；有能而無益於事者，君子不為。故君子所言者不出於名法權術，所為者不出於農稼軍陣，同務而已。今世之人，行欲獨賢，事欲獨能，辯欲出群，勇欲絕眾。夫獨行之賢，不足以成化；獨能之事，不足以周務；出群之辯，不可為戶說；絕眾之勇，不可與正陣。凡此四者，亂之所由生也。故聖人任道以通其险，立法以理其差，使賢愚不相弃、能鄙不相遺，此至理之術。故叔孫通欲起禮，漢高帝曰：得無難乎？對曰：夫禮若，因時世人情而為之節文者也。張釋之言便宜事，文帝曰：卑之，無甚高論，令今可施行。由是言之，夫理者不因時俗之務而貴奇異，是饿者百日以待粱肉、假人金玉以救溺子之說矣。","sortOrder":51},
  {"id":"s_work_tdk_8_52","chapterId":"ch_work_tdk_8","text":"善亡第三十四","sortOrder":52},
  {"id":"s_work_tdk_8_53","chapterId":"ch_work_tdk_8","text":"《易》曰：積善之家，必有餘慶。又曰：善不積，不足以成名。何以徵其然耶？《孟子》曰：仁之勝不仁也，猶水之勝火也。今為仁者，猶以一杯水，救一車薪之火，火不息，則謂水不勝火。此又與於不仁之甚者也。又五穀种之美者，苟為不熟，不如稊稗。夫仁亦在熟之而已矣。《尸子》曰：食所以肥也，一飯而問人曰：奚若？則皆笑之。夫治天下大事也，譬今人皆以一飯而問人奚若者也。由是觀之，故知善也者，在積而已。今人見徐偃亡國，謂仁義不足杖也；見承桑失統，謂文德不足恃也。是猶杯水救火、一飯問肥之說，惑亦甚矣。","sortOrder":53},
  {"id":"s_work_tdk_8_54","chapterId":"ch_work_tdk_8","text":"诡俗第三十五","sortOrder":54},
  {"id":"s_work_tdk_8_55","chapterId":"ch_work_tdk_8","text":"夫事有順之而為失，義有愛之而為害，有惡於已而為美，有利於身而損於國者。何以言之？劉梁曰：昔楚靈王驕淫，暴虐無度。芊尹申亥從王之欲，以殯於乾溪，殉之以二女。此順之而失義者也。鄢陵之役，晉楚對戰，穀陽獻酒，子反以毙。以愛之而害者也。臧武仲曰：孟孫惡我，藥石也；季孫之愛我，美疢也。疢毒滋厚，藥石猶生我，此惡之而為美者也。韓子曰：為故人行私，謂之不弃；以公财分施，謂之仁人；輕祿重身，謂之君子；枉法曲親，謂之有行；弃官寵交，謂之有俠；離俗遁世，謂之高悫；交爭逆令，謂之刚材；行惠取眾，謂之得人。不弃者，吏有奸也；仁人者，公财損也；君子者，人難使也；有行者，法製毀也；有俠者，官職曠也；高悫者，人不事也；刚材者，令不行也；得人者，君上孤也。此八者，匹夫之私譽，而人主之大败也。由是觀之，夫俗之好惡，與事相诡。唯明者能察之。","sortOrder":55},
  {"id":"s_work_tdk_8_56","chapterId":"ch_work_tdk_8","text":"息辯第三十六","sortOrder":56},
  {"id":"s_work_tdk_8_57","chapterId":"ch_work_tdk_8","text":"中論曰：水之寒也，火之熱也，金石之堅刚也，彼數物未嘗有言，而人莫不知其然者，信著乎其體。故知行有本，事有跡。審觀其體，則無所竄情。何謂行本？孔子曰：立身有義矣，而孝為本；丧紀有禮矣，而哀為本；戰陣有列矣，而勇為本。太公曰：人不盡力，非石人也；吏不絜愛人，非吾吏也；宰相不能富國強兵、調和陰陽、安萬乘之主、簡練群臣、定其名實、明其令罰，非吾宰相。此行本者也。何謂事跡？昔齊威王召即墨大夫而語之曰：自子之居即墨也，毀日至。然吾使人视即墨，田野辟，人民給，官無留事，東方以寧。是子不事吾左右以求譽也。封之萬家。召阿大夫而語之曰：自夫子之守阿也，譽日聞。然吾使人视阿，田野不辟，人貧苦。趙攻甄，子不能救；衛取薛陵，子不能知。是子常以幣事吾左右以求譽也。是日烹阿大夫及左右常譽之者，齊國大理。漢元帝時，石顯专權。京房宴見問上曰：幽厲之君何以危？所任者，何人也？上曰：君不明而所任巧佞。偏曰：知其巧佞而用之也，將以為賢？上曰：賢之。房曰：然則今何以知其不賢也？上曰：以其時亂而君危知之。此事跡者也。由是言之，夫立身從政，皆有本矣；理亂能否，皆有跡矣。若操其本行，以事跡繩之，譬如水之寒、火之熱，則善惡無所逃矣。","sortOrder":57},
  {"id":"s_work_tdk_8_58","chapterId":"ch_work_tdk_8","text":"量過第三十七","sortOrder":58},
  {"id":"s_work_tdk_8_59","chapterId":"ch_work_tdk_8","text":"孔子曰：人之過也，各於其党。觀過，斯知仁矣。何以言之？太史公雲，昔管仲相齊，九合諸侯，一匡天下。然孔子小之，曰：管仲之器小哉！豈不以周道衰，桓公既賢而不勉之至王，乃稱霸哉？虞卿說魏王曰：夫楚亦強大矣，天下無敵，乃且攻燕。魏王曰：向也子雲天下無敵，今也子雲乃且攻燕者，何也？對曰：今謂馬多力則有之矣，若曰勝千鈞則不然者。何也？夫千鈞，非馬之任也。今謂楚強大則有矣，若夫越趙、魏而开兵於燕，則豈楚之任哉？由是觀之，夫管仲九合諸侯，一匡天下，而孔子小之；楚人不能伐燕，虞卿反以為強大、天下無敵，非诡議也，各從其党言之耳。不可不察。","sortOrder":59},
  {"id":"s_work_tdk_8_60","chapterId":"ch_work_tdk_8","text":"势運第三十八","sortOrder":60},
  {"id":"s_work_tdk_8_61","chapterId":"ch_work_tdk_8","text":"夫天下有君子焉，有小人焉，有禮讓焉。此數事者，未必其性也，未必其行也，皆势運之耳。何以言之？文子曰：夫人有餘則讓，不足則爭。讓則禮義生，爭則暴亂起。物多則欲省，求贍則爭止。《淮南子》曰：遊者不能拯溺，手足有所爭急也；灼者不能救火，身體有所痛也；林中不賣薪、湖上不鬻魚者，有所餘也。故世治則小人守正，而利不能誘也；世亂則君子為奸，而刑不能禁也。故《莊子》曰：當尧舜而天下無窮人，非智得也；當桀紂而天下無通人，非智失也，時势適然。《新語》以近河之地濕、近山之木長者，以類相及也。四渎東流，則百川無西行者，小象大而少從多也。是知世之君子，未必君子；世之小人，未必小人；世之禮讓，未必禮讓。夫势運者，不可不察。","sortOrder":61},
  {"id":"s_work_tdk_8_62","chapterId":"ch_work_tdk_8","text":"傲禮第三十九","sortOrder":62},
  {"id":"s_work_tdk_8_63","chapterId":"ch_work_tdk_8","text":"《左傳》曰：無傲禮。《曲禮》曰：無不敬。然古人以傲為禮，其故何也？欲彰於人德者耳。何以言之？昔侯嬴為大梁夷門監，魏公子聞之，乃置酒大會。賓客坐定，公子從車騎，虛左，自迎夷門侯生。侯生引公子過市，及至家，以為上客。侯生謂公子曰：今日嬴之為公子亦足矣。嬴乃夷門抱關者也，而公子親枉車騎。稠人廣眾之中，不宜有所過，今公子故過之。然嬴欲就公子之名，故久立公子車騎市中，以觀公子，公子愈恭。市人皆以嬴為小人，而以公子為長者能下士也。張釋之居廷中，三公九卿盡會立。王生老人曰：吾襪解。顧謂張廷尉為我結襪。人或謂王生曰：獨柰何廷辱張廷尉？王生曰：吾者且賤，自度終無益於張廷尉。張廷尉方今天下名臣，吾故聊辱廷尉，使跪結襪，欲以重之。諸公聞之，賢王生而重張廷尉。由是觀之，以傲為禮，可以重人矣。","sortOrder":63},
  {"id":"s_work_tdk_8_64","chapterId":"ch_work_tdk_8","text":"定名第四十","sortOrder":64},
  {"id":"s_work_tdk_8_65","chapterId":"ch_work_tdk_8","text":"夫理得於心，非言不畅；物定於彼，非名不辯。言不畅志，則無以相接；名不辯物，則識鑒不顯。原其所以，本其所由。非物有自然之名、理有必定之稱也，欲辯其實則殊其名，欲宣其志則立其稱。故稱之曰道德仁義禮智信——夫道者，人之所蹈也；居知所為，行知所之，事知所乘，動知所止，謂之道。德者，人之所得也；使人各得其所欲，謂之德。仁者，愛也；致利除害，兼愛無私，謂之仁。義者，宜也；明是非，立可否，謂之義。禮者，履也；進退有度，尊卑有分，謂之禮。智者，人之所知也，以定乎得失是非之情，謂之智。信者，人之所承也；發號施令，以一人心，謂之信。見本而知末，執一而應萬，謂之術。","sortOrder":65},
  {"id":"s_work_tdk_8_66","chapterId":"ch_work_tdk_8","text":"《說苑》曰：從命利君，謂之順；從命病君，謂之諛；逆命利君，謂之忠；逆命病君，謂之亂；君有過失，將危國家，有能盡言於君，用則留，不用則去，謂之諫；用則可，不用則死，謂之諍；能率群下以諫於君，解國之大患，除國之大害，謂之辅；抗君之命，反君之事，安國之危，除主之辱，謂之弼。","sortOrder":66},
  {"id":"s_work_tdk_8_67","chapterId":"ch_work_tdk_8","text":"《莊子》曰：莫之顧而進，謂之佞，俙意导言，謂之諂；不擇是非而言，謂之諛；好言人惡，謂之讒；稱譽诈伪以败惡人，謂之匿；不擇善否，兩容頰適，偷拔其所欲，謂之险。古語曰：以可濟否，謂之和；好惡不殊，謂之同；以賢代賢，謂之奪；以不肖代賢，謂之伐；缓令急誅，謂之暴；取善自與，謂之盜；罪不知愆，謂之虐；敬不中禮，謂之野；禁而不止，謂之逆；禁非立是，謂之法；知善不行，謂之狂；知惡不改，謂之惑。太公曰：收天下珠玉美女、金銀采帛，謂之殘；收暴虐之吏，殺無罪之人，非以法度，謂之賊；賢人不至，謂之蔽；忠臣不至，謂之塞；色取人而實违之，謂之虛；不以誠待其臣，而望其臣以誠事已，謂之愚；分於道，謂之性；形於一，謂之命。","sortOrder":67},
  {"id":"s_work_tdk_8_68","chapterId":"ch_work_tdk_8","text":"凡人函五常之性，而刚柔、缓急、音聲不同。系水土之氣，謂之風；好惡取舍，動靜無常，隨君上之情Q欲Y，謂之俗。","sortOrder":68},
  {"id":"s_work_tdk_8_69","chapterId":"ch_work_tdk_8","text":"或曰：樂與音同乎？對曰：昔魏文侯問子夏曰：吾端冕而聽古樂，唯恐臥；聽鄭衛之音，則不知倦。敢問古樂之如彼、新樂之如此，何也？子夏曰：今君之所問者樂也，所好者音也。夫樂者與音相近而不同。文侯曰：敢問何如？子夏曰：夫古樂者，天地順而四時當，民有德而五穀昌，疾疫不作而無妖祥，此之謂大當。然後聖人為父子君臣，以為之紀綱。紀綱既正，天下大定。天下大定，然後正六律、和五聲、絃歌詩頌，此之謂德音。德音之謂樂。《詩》雲：莫其德音，其德克明。克明克類，克長克君。王此大邦，克順克比。比於文王，其德靡悔。既受帝祉，施於孫子。此之謂也。今君之所好者，溺音乎？鄭音好濫，淫志也；宋音燕女，溺志也；衛音趨數，煩志也；齊音傲僻，驕志也。四者皆淫於色而害於德，是以祭祀弗用。此音樂之異也。","sortOrder":69},
  {"id":"s_work_tdk_8_70","chapterId":"ch_work_tdk_8","text":"或曰：音與樂既聞命矣，敢問儀與禮同乎？對曰：昔趙簡子間揖讓周旋之禮於子太叔，太叔曰：是儀也，非禮也。吉也聞諸先大夫子產曰：夫禮，天之經也，地之義也，民之行也天地之經，民實則之。則天之明，因地之性，生其六氣，用其五行。氣為五味，發為五色，章為五聲，淫則昏亂，民失其性，是故以禮以奉之。人有好惡喜怒哀樂，生於六氣。是故審則宜類，以製六志：哀有哭泣，樂有歌舞，喜有施舍，怒有戰斗。哀樂不失，乃能协於天地之性，是以長久。故人能曲直以從禮者，謂之成人。或曰：然則何謂為儀？對曰：養國子，教之六儀：祭祀之容，穆穆皇皇；賓客之客，俨恪矜莊；朝廷之容，濟濟蹌蹌；丧紀之容，累累顛顛軍旅之容，暨暨詻詻；車馬之容，騑騑翼翼，此禮儀之異心。","sortOrder":70},
  {"id":"s_work_tdk_8_71","chapterId":"ch_work_tdk_8","text":"夫定名之弊，在於鉤鈲折辭。苟無其弊，則定名之妙也。","sortOrder":71},
  {"id":"s_work_tdk_8_72","chapterId":"ch_work_tdk_8","text":"論曰：班固九流，其九曰雜家，兼儒墨，合名法。傳子九品，其九曰雜才，以長諷議。由是觀之，雜說之益，有自來矣。故著此篇，蓋立理叙事，以示將來君子矣。","sortOrder":72},
  {"id":"s_work_tdk_8_73","chapterId":"ch_work_tdk_8","text":"《長短經》　唐　趙蕤","sortOrder":73},
  {"id":"s_work_tdk_9_1","chapterId":"ch_work_tdk_9","text":"卷九兵權","sortOrder":1},
  {"id":"s_work_tdk_9_2","chapterId":"ch_work_tdk_9","text":"趙子曰：《詩》雲允文允武，《書》稱乃武乃文。孔子曰：君子有文事，必有武備。《傳》曰：天生五材，民併用之，废一不可，誰能去兵？黃帝與蚩戰，颛頊與共工爭，尧伐驩兜，舜伐有苗，啟伐有扈，湯伐有夏，文王伐崇，武王伐紂，漢高有京索之戰，光武興崑陽之師，魏動官渡之軍，晉平吳之役。故《呂氏春秋》曰：聖王有仁義之兵，而無偃兵。《淮南子》曰：以废不義而授有德者也。是知取威定霸，何莫由斯？自古兵書，殆將千計。若不知合变，雖多，亦奚以為？故曰：少則得，多則惑。所以舉體要而作《兵權》雲。","sortOrder":2},
  {"id":"s_work_tdk_9_3","chapterId":"ch_work_tdk_9","text":"出軍第一","sortOrder":3},
  {"id":"s_work_tdk_9_4","chapterId":"ch_work_tdk_9","text":"夫兵者，凶器也；戰者，危事也。兵戰之場，立尸之所。帝王不得已而用之矣。","sortOrder":4},
  {"id":"s_work_tdk_9_5","chapterId":"ch_work_tdk_9","text":"故曰：救亂誅暴，謂之義兵，兵義者王。敵加於己，不得已而用之，謂之應兵，應兵者勝。爭恨子故，不勝慎怒者，謂之忿兵，兵忿者败。利人土地寶货者，謂之貪兵，兵貪者破。恃國之大、矜人之眾，欲見威於敵，謂之驕兵，兵驕者滅。是知聖人之用兵也，非好樂之，將以誅暴讨亂。","sortOrder":5},
  {"id":"s_work_tdk_9_6","chapterId":"ch_work_tdk_9","text":"夫以義而誅不義，若决江而溉螢火、臨不测之淵而欲墮之，其克之必也。所必優遊恬泊者何？重傷人物。故曰：遠人不服，則修文德以來之。不以德來，然後命將出師矣。","sortOrder":6},
  {"id":"s_work_tdk_9_7","chapterId":"ch_work_tdk_9","text":"夫將者，國之辅也，人之司命也。故曰：將不知兵，以其主與敵也；君不擇將，以其國與敵也。將既知兵，主既擇將，天子居正殿而召之曰：社稷安危，一在將軍。今某國不臣，願煩將軍應之。乃使太史卜斋擇日，授以釜鉞。君入太廟，西面而立，將軍北面而立。君親操鉞，持其首，授其柄，曰：從是以上至天者，將軍製之。乃复操柄授與刃，曰：從是以下至淵者，將軍製之。將既受命，拜而報曰：臣聞國不可從外理，軍不可從中御，二心不可以事君，疑志不可以應敵。臣既受命专釜鉞之威，臣不敢還諸。乃辭而行，凿凶門而出。故《司馬法》曰：進退唯時，無曰寡人。《孫子》曰：將在軍，君命有所不受。古語曰：阃以內，寡人製之；阃以外，將軍製之。《漢書》曰：唯聞將軍之命，不聞天子之詔。故知合軍聚眾，在於阃外，受推轂之寄，當秉旄之重，無天於上，無地於下，無敵於前，無君於後，乃可成大業矣。故曰：將能而君不御者勝。此之謂也。","sortOrder":7},
  {"id":"s_work_tdk_9_8","chapterId":"ch_work_tdk_9","text":"練士第二","sortOrder":8},
  {"id":"s_work_tdk_9_9","chapterId":"ch_work_tdk_9","text":"夫王者帥師，必簡練英雄，知士高下，因能授職，各取所長，為其股肱羽翼，以成威神，然後萬事畢矣。","sortOrder":9},
  {"id":"s_work_tdk_9_10","chapterId":"ch_work_tdk_9","text":"腹心一人；謀士五人，天文三人，地形三人，兵法九人，通糧四人，奋威四人；鼓旗三人，股肱四人，通材三人，權士三人，耳目七人，爪牙五人，羽翼四人，遊士八人，術士二人，法算二人，方士二人。","sortOrder":10},
  {"id":"s_work_tdk_9_11","chapterId":"ch_work_tdk_9","text":"軍中有大勇敢死樂傷者，聚為一卒。有勃氣壮勇暴強者，聚為一卒。有學於奇正，長劍雕弧、接武齊列者，聚為一卒。有破格舒鉤、強梁多力，能潰破金鼓、絕滅旌旗者，聚為一卒。有能逾高超遠、輕足善走者，聚為一卒。有故王臣失势、欲复見其功者，聚為一卒。有死罪之人、崑弟為其將報仇者，聚為一迕。有貧窮忿怒、將快其志者，聚為一卒。有故赘婿入虜、欲昭跡提名者，聚為一卒。有辯言巧辭、善毀譽者，聚為一卒。有故胥靡免罪之人、欲逃其恥者，聚為一卒。有材伎過人、能負重行數百里者，聚為一卒。","sortOrder":11},
  {"id":"s_work_tdk_9_12","chapterId":"ch_work_tdk_9","text":"夫卒強將弱曰弛，吏強卒弱曰陷，兵無選鋒曰北，必然之數矣。故曰：兵眾孰強？士卒孰練？知之者勝，不知之者不勝，不可忽也。","sortOrder":12},
  {"id":"s_work_tdk_9_13","chapterId":"ch_work_tdk_9","text":"結營第三","sortOrder":13},
  {"id":"s_work_tdk_9_14","chapterId":"ch_work_tdk_9","text":"太公曰：出軍征戰，安營置陣，以六為法。將軍自取九天之上，竟一旬，复徙开牙門；常背建向破，不飲死水，不居死地，不居地柱，不取地獄，無休天竈，無當龍首。故曰：凡結營安陣，將軍居青龍，軍鼓居逢星，士卒居明堂，伏兵於太陰，軍門居天門，小將居地戶，斬斷居天獄，治罪居天庭，軍糧居天牢，軍器居天藏。此謂法天結營，物莫能害者也。","sortOrder":14},
  {"id":"s_work_tdk_9_15","chapterId":"ch_work_tdk_9","text":"道德第四","sortOrder":15},
  {"id":"s_work_tdk_9_16","chapterId":"ch_work_tdk_9","text":"夫兵不可出者三：不和於國，不可以出軍；不和於軍，不可以出陣；不和於陣，不可以出戰。故孫子曰：一曰道。道者，令人與上同意者也。故可與之死，可與之生，而人不畏危。黃石公曰：軍井未達，將不言渴；軍幕未辦，將不言倦；冬不服裘，夏不操扇，是謂禮將。與之安，與之危，故其眾可合而不可離、可用而不可疲，接之以禮，励之以辭，則士死之。是以含蓼問疾，越王霸於諸侯；吮疽恤士，吳起凌於腋國。陽門恸哭，勝三晉之兵；单醪投河，感一軍之士。勇者為之斗，智者為之忧，视死若歸，計不旋踵者，以其恩養素畜、策謀和同也。故曰：畜恩不倦，以一取萬。語曰：積恩不已，天下可使。此道德之略也。","sortOrder":16},
  {"id":"s_work_tdk_9_17","chapterId":"ch_work_tdk_9","text":"禁令第五","sortOrder":17},
  {"id":"s_work_tdk_9_18","chapterId":"ch_work_tdk_9","text":"孫子曰：卒未专親而罰之，則不服，不服則難用；卒已专親而罰不行，則不可用矣。故曰：视卒如婴兒，故可與之赴深溪；视卒如愛子，故可與之居死地。厚而不能使，愛而不能令，亂而不知理，譬若驕子，不可用也。經曰：兵以賞為表，以罰為里。又曰：令之以文，齊之以武，是謂必取。故武侯之軍禁有七：一曰輕，二曰慢，三曰盜，四曰欺，五曰背，六曰亂，七曰誤。此治軍之禁也。若期會不到，聞鼓不行，乘宽自留，回避務止，初近而後遠，唤名而不應，軍甲不具，兵器不備，此謂輕軍。受令不傳，傳之不審，以惑吏士，金鼓不聞，旌旗不睹，此謂慢軍。食不廪糧，軍不部兵，賦賜不均，阿私所親，取非其物，借貸不還，奪人頭首，以獲功名，此謂盜軍。若变易姓名，衣服不鮮，金鼓不具，兵刃不磨，器仗不堅，矢不著羽，弓弩無絃，主者吏士、法令不從，此謂欺軍。聞鼓不行，叩金不止，按旗不伏，舉旗不起，指麾不隨，避前在後，縱發亂行，折兵弩之势，卻退不斗，或左或右，扶傷轝死，因讬歸還，此謂背軍。出軍行將，士卒爭先，紛紛扰扰，軍騎相連，咽塞道路，後不得前，呼唤喧譁，無所聽聞，失行亂次，兵刃中傷，長將不理，上下縱橫，此謂亂軍。屯營所止，問其乡里，親近相隨，共食相保；呼召不得，越入他位，幹誤次第，不可呵止；度營出入，不由門戶，不自啟白；奸邪所起，知者不告，罪同一等；合人飲食，阿私所受；大言驚語，疑惑吏士，此謂誤軍。斬斷之後，萬事乃理。所以乡人盜笠，呂蒙先涕而後斬；馬逸犯麥，曹公割發而自刑。故太公曰：刑上極，賞下通。孫子曰：法令孰行？賞罰執明？吾以此知勝此之謂也。","sortOrder":18},
  {"id":"s_work_tdk_9_19","chapterId":"ch_work_tdk_9","text":"教戰第六","sortOrder":19},
  {"id":"s_work_tdk_9_20","chapterId":"ch_work_tdk_9","text":"孔子曰：不教人戰，是謂弃之。故知卒不服習起居，不精前击後解，與金鼓之指相失，百不當一，此弃之者也。故領三軍故教之戰者，必有金鼓約令，所以整齊士卒也，教令操兵、起居、旌旗指麾之变。故教使一人學戰，教成合之十人；十人學戰，教成合之百人，漸至三軍之眾。大戰之法，為其校陣，各有其道。左校青龍，右校白虎，前校朱雀，後校玄武，中校軒轅。大將之所處，右鋒左戟，前楯後弩，中央鼓旗。興動俱起，聞鼓則進，聞金則止，隨其指麾，五陣乃理。故曰：治眾如治寡，分數是也；斗眾如斗少，形名是也。言不相聞，故為鼓铎；视不目見，故為旌旗。夫金鼓旌旗，所以一人耳目也。是知鼓鞞金铎，所以威耳；旌旗麾章，所以威目；禁令刑罰，所以威心。耳威於聲，不可不清；目威於色，不可不明；心威於罰，不可不嚴。三者不立，雖勝必败。故曰：將之所麾，莫不從移；將之所指，莫不前死。紛紛紜紜，斗亂而不可亂；混混沌沌，形圓而不可败，此用眾之法也。卒服習矣，器用利矣，將軍乃秉旄麾眾而誓之。於是氣励青雲，雖赴湯蹈火可也。此教戰之法也。","sortOrder":20},
  {"id":"s_work_tdk_9_21","chapterId":"ch_work_tdk_9","text":"天時第七","sortOrder":21},
  {"id":"s_work_tdk_9_22","chapterId":"ch_work_tdk_9","text":"《孫子》曰：二曰天時。天時者，陰陽寒暑時節製也。《司馬法》曰：冬夏不興師，所以兼愛吾人。太公曰：天文三人，主占風氣，知天心去就。故經曰：能知三生，臨刀勿驚。從孤击虛，一女當五丈夫。故行軍必背太陰，向太陽，察五緯之光芒，觀二曜之薄蚀；必當以太白為主，辰星為候；合宿有必斗之期，格出明不戰之势，避以日耗，背以月刑，以王击困，以生击死。是知用天之道、順天行誅，非一日也。若細雨汰軍，臨機必有捷；回風相觸，道還而無功；雲類群羊，必走之道；氣如驚鹿，必败之势。黑雲出壘，赤氣臨軍，六窮起風，三刑生霧，此皆見師之出而不見者入也。若煙非煙，此慶雲也；若星非生，此歸邪也；若霧非霧，此泣軍也；若雷非雷，此天鼓也。慶雲开有德，歸邪有降人，泣軍多殺將，天鼓多败軍。是知風雲之占、歲月之候，其來久矣。故古者初立將，始出門首建牙之時，必觀風氣之氣。若風不旁勃，旌旗晕晕，順風而扬舉，或向敵終日，軍行有功，勝候也。若逆風來應，氣旁勃，牙扛折，陰不見日，旌幡激扬，败候也。若下輕其將，妖怪併作，眾口相惑，當修德審令，繕砺鋒甲，勤誠誓士，以避天怒。然後复擇吉日祭牙旗，具太牢之饌，震鼓铎之音，誠心啟請，以備天問，觀其祥應，以占吉凶。若人馬喜躍、旌旗皆前指高陵、金铎之聲扬以清、鞞鼓之音宛以鳴，此得神明之助持，以安於眾心，乃可用矣。雖雲任賢使能，則不占而事利；令明法審，則不筮而計成；封功賞勞，則不祷而福從；共苦同甘則犯逆而功就，然而臨機製用，有五助焉：一曰助謀，二曰助势，三曰助怯，四曰助疑，五曰助地。此五者，助勝之術。故曰：知地知天，勝乃可全，不可不審察也。","sortOrder":22},
  {"id":"s_work_tdk_9_23","chapterId":"ch_work_tdk_9","text":"地形第八","sortOrder":23},
  {"id":"s_work_tdk_9_24","chapterId":"ch_work_tdk_9","text":"《孫子》曰：三曰地利。地利者，遠近险易、廣狹死生也。故不知山林险阻沮泽之形者，不能行軍；不用乡导，不能得地利。故用兵有散地，","sortOrder":24},
  {"id":"s_work_tdk_9_25","chapterId":"ch_work_tdk_9","text":"有輕地，有爭地，有交地，有衢地，有重地，有汜地，有围地，有死地。諸侯自戰其地，為散地；入人之地而不深者，為輕地；我得則利、彼得亦利者，為爭地；我可以往、彼可以來，為交也：諸侯之地三屬，先至而得天下之眾者，為衢地；入人難反之地，深倍城邑多者，為重地；行山林险阻沮泽，凡難行之道者，為汜地；所由入者隘，所從歸者迂，彼寡可以击吾眾者，為围地；疾戰則存、不疾則亡，為死地。是故散地無戰，爭地則無攻，交地則無絕，衢地則合交，重地則掠，汜地則行，围地則謀，死地則戰。","sortOrder":25},
  {"id":"s_work_tdk_9_26","chapterId":"ch_work_tdk_9","text":"又有六地：有通，有掛，有支，有隘，有险，有遠。我可以往，彼可以來，曰通。居通地，先處其高陽，利糧道，以戰則利。可以往，難以反，曰掛。掛形曰：敵無備，出而勝之；敵有備，出而不勝，難以反，不利。我出而不利，彼出而不利，曰支。支形曰：敵雖利我，我無出引而去也，令敵半出而击之利。隘形曰：我先居之，必盈之而待敵。若敵先居之，盈而勿從也，不盈而從之。险形曰：我先居之，必居高陽以待敵。若敵先居，則引而去之，勿從也。夫遠形鉤势，難以挑，戰而不利。凡此六者，地之道也，皆將之至任，不可不察。","sortOrder":26},
  {"id":"s_work_tdk_9_27","chapterId":"ch_work_tdk_9","text":"故曰：深草蓊秽者，所以遁逃也；深穀阻险者，所以止御車騎也；隘塞山林者，所以所少击眾也；沛泽杳冥者，所以匿其形也。丈五之溝漸車之水、山林石径、涇川丘阜、草木所在、步兵之地，車騎二不當一；丘陵漫衍相屬、平原廣野，此車騎之地，步兵十不當一；平原相遠、仰高臨下，此弓弩之地，短兵十不當一；兩陣相近、平地淺草、可前可後，此長戟之地，劍楯三不當一；萑苇竹萧、草木蒙籠、枝葉茂接，此矛鋋之地，長戟二不當一；道相伏、险扼相薄，此劍楯之地，弓弩三不當一。","sortOrder":27},
  {"id":"s_work_tdk_9_28","chapterId":"ch_work_tdk_9","text":"故曰：地形者，兵之助。又曰：用兵之道，地利為寶。趙奢趨山，秦師所以覆败；韓信背水，漢兵由是克勝。此用地利之略也。","sortOrder":28},
  {"id":"s_work_tdk_9_29","chapterId":"ch_work_tdk_9","text":"水火第九","sortOrder":29},
  {"id":"s_work_tdk_9_30","chapterId":"ch_work_tdk_9","text":"經曰：以水佐攻者強，以火佐攻者明。是知水火者，兵之助也。","sortOrder":30},
  {"id":"s_work_tdk_9_31","chapterId":"ch_work_tdk_9","text":"故火攻有五：一曰火人，二曰火積，三曰火辎，四曰火库，五曰火燧。行火必有因。煙火素具，發火有時，起火有日。時者，天之燥也。日者，宿在箕、壁、參、軫也。凡此四宿者，風起之日也。","sortOrder":31},
  {"id":"s_work_tdk_9_32","chapterId":"ch_work_tdk_9","text":"太公曰：強弩長兵，所以逾水戰。孫子曰：水可以絕。謂灌城也。又曰：絕水必遠水。客絕水而來，迎之於水內，令敵半渡而击之利。欲戰，無附於水而迎客也。謂處水上之軍。故曰：以水佐攻者強。何以言之？昔韓信定臨淄，走齊王田廣。楚使龍且來救齊，齊王廣、龍且併軍，與信合戰，夹濰水陣。韓信乃夜令人為萬餘囊，盛沙壅水上流，引軍半渡击龍且，佯不勝，還走。龍且果喜曰：固知信恃也。乘追。信渡水，信使决壅囊。水大至，龍且軍太半不得渡，即急击之，殺龍且。龍且水軍東散走。此反半渡之势。盧綰佐彭越攻下梁地十餘城。項羽聞之，謂其大司馬曹咎曰：謹守成皋。即漢挑戰，慎勿與戰。漢果挑楚軍，楚軍不出，使人辱之。大司馬怒，渡汜水。卒半渡，漢击大破之。此欲戰無附於水势也。","sortOrder":32},
  {"id":"s_work_tdk_9_33","chapterId":"ch_work_tdk_9","text":"故知水火之变可以製勝，其來久矣。秦人毒涇上流，晉軍多死。荆王燒楚積聚，項氏以擒。曹公决泗於下邳，呂布就戮。黃蓋火攻於赤壁，魏祖奔衄。此將之至任，蓋軍中亢急者矣，不可不察。","sortOrder":33},
  {"id":"s_work_tdk_9_34","chapterId":"ch_work_tdk_9","text":"五間第十","sortOrder":34},
  {"id":"s_work_tdk_9_35","chapterId":"ch_work_tdk_9","text":"《周禮》曰：巡國傳諜者，反間也。呂望雲：間構飛言，聚為一卒。是知用間之道，非一日也。","sortOrder":35},
  {"id":"s_work_tdk_9_36","chapterId":"ch_work_tdk_9","text":"故間有五間：有因間，有內間，有反間，有生間，有死間。五間俱起，莫知其道。因間者，因其乡人而用之者也；內間者，因其官人而用之者也；反間者，因敵間而用之者也；生間者，反報者也；死間者，為誑事於外，令吾間知之，而待於敵間者也。","sortOrder":36},
  {"id":"s_work_tdk_9_37","chapterId":"ch_work_tdk_9","text":"昔漢西域都護班超，初為將兵長史，悉發諸國步騎二萬五千击莎車。莎車求救龟茲。龟茲王遣左將軍發溫宿姑墨尉頭，合五萬人助之。超召部曲及於闐疏勒王議曰：兵少不敵，計莫如各解散去。於闐從此東，長史亦從此西歸，夜半聞鼓聲便發。眾皆以為然。乃陰缓擒得生口，生口歸，以超言告龟茲。龟茲聞之喜，使左將軍將萬騎於西眾遮超、溫宿王將八千騎於東眾遮於闐王。人定後，超密令諸司馬勒兵励士。至雞鳴，馳赴莎車軍營，掩覆之，胡皆驚走，斬首五千級。莎車遂降。又耿弇讨張步。步聞之，乃使其大將費邑軍歷下，又分兵屯祝阿，別於太山鐘城列營數十以待弇。弇渡河先击祝阿，拔之，故开围一角，令其眾得奔鐘城。鐘城人聞祝阿已潰，大懼，遂空壁亡去。費邑分遣其弟敢守巨里。弇進兵先胁巨里，多伐树木，扬言填塞坑垽。數日有降者，言邑聞弇欲攻巨里，謀來救之。弇乃嚴令軍中趣治攻具，後三日當悉攻巨里。陰缓生口，令得亡歸。歸者以弇期告邑，邑至日果自將來救之。弇喜謂諸將曰：吾所修攻具者，欲誘致邑耳。今來，適吾所求也。即分三千人守巨里，自引精兵上岗坂，乘高合戰，大破之，臨陣斬邑。此用因間之势也。晉時，益州牧羅尚遣隗伯攻李雄於郫城，迭有勝負。雄乃募武都人朴泰，鞭之見血，使譎羅尚，欲為內應，以火為期。尚信之，悉出精兵遣隗伯等率領從泰。李雄先使李驤於道設伏。泰以長梯倚城而舉火。伯軍見火起，皆爭绿梯。泰又以繩汲上尚軍百餘人，皆斬之。雄因放兵，內外击之，大破尚軍。此用內間之势也。鄭武公欲伐胡，先以其子妻故，因問群臣曰：我欲用兵，誰可伐者？大夫關其思曰：胡可伐。武公怒而戮之曰：胡，兄弟之國。子言伐之，何也？胡君聞之，以鄭為親已而不備鄭。鄭袭胡，取之。此用死間之势也。陳平以金縱反間於楚軍，間范增。楚王疑之。此用反間者也。故知三軍之親莫親於間，賞莫厚於間，事莫密於間，非聖智莫能用間，非密微莫能得間之實。此三軍之要，唯賢將之所留意也。","sortOrder":37},
  {"id":"s_work_tdk_9_38","chapterId":"ch_work_tdk_9","text":"將體第十一","sortOrder":38},
  {"id":"s_work_tdk_9_39","chapterId":"ch_work_tdk_9","text":"《萬機論》曰：雖有百萬之師，臨時吞敵，在將也。《吳子》曰：凡人之論將，恒觀之於勇。勇之於將，乃萬分之一耳。故《六韜》曰：將不仁則三軍不親，將不勇則三軍不為動。《孫子》曰：將者，勇、智、仁、信、必也。勇則不可犯，智則不可亂，仁則愛人，信則不欺人，必則無二心，此所謂五才者也。三軍之眾，百萬之師，張設輕重，在於一人，謂之氣機。道峡路险，名山大塞，十人所守，千人不過，是謂地機。善行間諜，分散其眾，使君臣相怨，是謂事機。車堅舟利，士馬閉習，是謂力機。此所謂四機也。","sortOrder":39},
  {"id":"s_work_tdk_9_40","chapterId":"ch_work_tdk_9","text":"夫將可樂而不可忧，謀可深而不可疑。將忧則內疑，謀疑則敵國奋。以此征人，則可致亂。","sortOrder":40},
  {"id":"s_work_tdk_9_41","chapterId":"ch_work_tdk_9","text":"故將能清能靜、能平能整、能受諫、能聽訟、能納人，能采善言、能知國俗、能圖山川、能裁厄難、能製軍權、危者安之、懼者懽之、叛者還之、冤者原之、訴者察之、卑者貴之、強者抑之、敵者殘之、貪者丰之、欲者使之、畏者隱之、謀者近之、讒者覆之、毀者复之、反者废之、橫者挫之、服者活之、降者說之、獲城者割之、獲地者裂之、獲國者守之、獲厄塞之、獲難屯之、獲财散之、敵動伺之、敵強下之、敵凌假之、敵暴安之、敵勃義之、敵睦携之、順舉挫之、因势破之、放言過之、四網羅之、此為將之道也。","sortOrder":41},
  {"id":"s_work_tdk_9_42","chapterId":"ch_work_tdk_9","text":"故將拒諫則英雄散，策不從則謀士叛，善惡同則功臣倦，將专已則下歸咎，將自臧則下少功，將受讒則下有離心，將貪财則奸不禁，將內顧則士卒淫。將有一則眾不服，有二則軍無试，有三則軍乖背，有四則禍及國。","sortOrder":42},
  {"id":"s_work_tdk_9_43","chapterId":"ch_work_tdk_9","text":"《軍志》曰：將謀欲密，士眾欲一，攻敵欲疾。將謀密則奸心閉，士眾一則群心結，攻敵疾則诈不及。設軍有此三者，則計大奪。將謀泄則軍無势，以外闚內則禍不製，财入營則眾奸會。將有此三者，軍必败。將無慮則謀士去，將無勇則吏士恐，將遷怒則軍士懼。慮也、謀也，將之所重；勇也、怒也，將之所用意。故曰：必死可殺也，必生可慮也，忿速可侮也，廉絜可辱也，愛人可煩也。此五者，將軍之過、用兵之灾。","sortOrder":43},
  {"id":"s_work_tdk_9_44","chapterId":"ch_work_tdk_9","text":"故凡戰之要，先占其將而察其才，因刑用權，則不勞而功興也。將愚而信人，可謀而诈；貪而忽名，可货而賂；輕变，可勞而困；上富而驕、下貧而桀，可離而間；將怠士懈，可潛而袭。智而心缓者，可追也；勇而輕死者，可暴也；急而心速者，可誘也；貪而喜利者，可袭也、可遺也；仁而不忍於人者，可勞也；信而喜信於人者，可誑也；廉絜而不愛人者，可侮也；刚毅而自用者，可事也；懦心喜用於人者，可使人欺也。此皆用兵之要、為將之略也。","sortOrder":44},
  {"id":"s_work_tdk_9_45","chapterId":"ch_work_tdk_9","text":"料敵第十二","sortOrder":45},
  {"id":"s_work_tdk_9_46","chapterId":"ch_work_tdk_9","text":"夫兩國治戎，交和而合刀，以冥冥决事，必先探於敵情。故《孫子》曰：勝兵先勝而後戰。又曰：策之而知得失之計，候之而知動靜之理，因形而作勝於眾，用兵之要也。","sortOrder":46},
  {"id":"s_work_tdk_9_47","chapterId":"ch_work_tdk_9","text":"若欲先知敵將，當令賤而勇者，將輕銳以當之。觀敵之來，一起一坐，其政以理，其追北佯為不及，其見利佯為不知，如此者，將必有智，勿與輕戰。若其眾讙旗亂，其卒自止自行，其兵或縱或橫，其追北恐不及，見利恐不得，如此者，將必無謀，雖眾可獲。","sortOrder":47},
  {"id":"s_work_tdk_9_48","chapterId":"ch_work_tdk_9","text":"故曰：敵近而靜者，恃其险也；敵遠而挑人者，欲人之進也；眾树動者，來也；眾草多障者，疑也；鳥起者，伏也；禽駭者，覆也；尘卑而廣者，徒來也；散而條遠者，薪來也；少而往來者，營軍也；辭卑而益備者，進也；辭強而進驅者，退也；無約而請和者，謀也；半進半退者，誘也；杖而立者，飢也；汲而先飲者，渴也；見利不進者，勞也；鳥集者，虛也；夜呼者，恐也；軍扰者，將不重也；旗動者，亂也；吏怒者，倦也；粟馬食肉、軍無懸涶，不及其舍者，窮寇也；淳淳翕翕、徐言入人者，失其眾也；數賞者，害也；數罰者，困也；數顧者，失其群也；來委謝者，欲休息也。兵怒而相近，久而不合，又不相去，必謹察之。敵來新到，行陣未定，可击也；陣雖定，人馬未食，可击也；涉長道，後行未息，可击也；行坂涉险，半隱半出，可击也；涉水半渡，可击也；险道狹路，可击也；旌旗亂動，可击也；陣數動移，可击也；人馬數顧，可击也；凡見此者，击之而勿疑。然兵者诡道也，能而示之不能，用而示之不用。故匈奴示弱，漢祖有平城之围；石勒藏鋒，王浚有幽州之陷，即其效也，可不慎也！","sortOrder":48},
  {"id":"s_work_tdk_9_49","chapterId":"ch_work_tdk_9","text":"势略第十三","sortOrder":49},
  {"id":"s_work_tdk_9_50","chapterId":"ch_work_tdk_9","text":"《孫子》曰：勇怯势也，強弱形也。又曰：水之弱至於漂石者，势也。何以明之？昔曹公征張魯、定漢中，劉晔說曰：明公以步卒五千，讨誅董卓，北破袁絕，南征劉表，九州百郡、十併其八，威雲天下，势氵習海外。今舉漢中，蜀人望風，破胆失守，推此而前，蜀可傳檄而定也。劉備、人杰也，有智而遲，得蜀日淺，蜀人未恃。今破漢中，蜀人震恐，其势自傾。以公之神明，因其傾而壓之，無不克也。若小缓之，諸葛亮明於理而為相，關羽、張飛勇冠三軍而為將，蜀人既定，據险守要，則不可犯也。今不取，必為後忧。曹公不從。居七日，蜀降者說蜀中一日數十驚，備斬之而不能禁也。曹金延問晔曰：今尚可击否？晔曰：今已小定，未可击也。又太祖征呂布至下邳？布败，固守城，攻不拔。太祖欲還，荀攸曰：呂布勇而無謀，今三軍皆北，其銳氣衰。三軍以將為主，主衰則軍無奋意。夫陳宮有智而遲，今及布氣之未复，宮謀之未定，進急攻之，布可收也。乃引沂泗灌城，城潰，生擒布。以此觀之，當是時，雖諸葛之智、陳宮之謀、呂布之勇、關張之功，無所用矣。此謂勇怯势也、強弱形也。救兵有三势，善戰者恒求之於势。势之來也，食其缓頰，下齊七十餘城；謝石渡淝，摧秦百萬之眾。势之去也，項羽有拔山之力，空泣虞姬；田橫有負海之強，終然刎頸。故曰：戰勝之威，人百其倍；败兵之卒，没世不复。故水之弱至於漂石，此势略之要也。","sortOrder":50},
  {"id":"s_work_tdk_9_51","chapterId":"ch_work_tdk_9","text":"攻心第十四","sortOrder":51},
  {"id":"s_work_tdk_9_52","chapterId":"ch_work_tdk_9","text":"《孫子》曰：攻心為上，攻城為下。何以明之？戰國時有說齊王曰：凡伐國之道，攻心為上，攻城為下；心勝為上，兵勝為下。是故聖人之伐國攻敵也，務在先服其心。何謂攻其心？絕其所恃，是謂攻其心也。今秦之所恃為心者，燕趙也，當收燕趙之權。今說燕趙之君，勿虛言空辭，必將以實利，以回其心，所謂攻其心者也。沛公西入武關，欲以二萬人击秦峣關下軍，張良曰：秦兵尚強，未可輕也。臣聞其將屠子贾竖，易動以利。願沛公且留壁，使人先行，為五萬人具食，益張旗幟諸山之上，為疑兵。令郦食其持重寶啗秦將。秦等果欲連和，俱西袭鹹陽。沛公欲聽之，良曰：此獨其將欲叛，士卒恐不從，不從必危。不如因其懈击之。沛公乃引兵击秦軍，大破之。此攻心者也。","sortOrder":52},
  {"id":"s_work_tdk_9_53","chapterId":"ch_work_tdk_9","text":"伐交第十五","sortOrder":53},
  {"id":"s_work_tdk_9_54","chapterId":"ch_work_tdk_9","text":"《孫子》曰：善用兵者，使交不得合。何以明之？昔楚莫敖將盟貳軫，郧人軍於蒲骚，將以隨、絞、州、蓼伐楚師。莫敖患之。斗廉曰：郧人軍於其郊，必不誡，且日虞四邑之至。君之於郊郢以御四邑，我以銳師宵加於郧。郧有虛心而恃其城，莫有斗志，若败郧師，四邑必離。莫敖從之。遂败郧師於蒲骚。漢宜帝時，先零與罕併羌解仇，合党為寇。帝命趙充國先誅罕併。充國守便宜，不從，上書曰：先零羌虜欲為背叛，故與罕併解仇，然其私心不能亡，恐漢兵至而罕併背之也。臣愚以為其計常欲赴罕併之急，以堅其約。先击罕羌，先零必助之。今虜馬肥、糧方饒，击之恐不能傷害，適使先零得施德於罕羌也。堅其約，合其党，虜交堅党合，誅之用力數倍。臣恐國家忧累，由此十數年，不一二歲而已。先誅先零，則罕併之屬，不煩兵服矣。帝從之，果如策。魏太祖初伐關中，賊每一部到，太祖辄喜。賊破之後，諸將問其故。太祖曰：關中道遠，若各依险阻，征之不一二年，不可定也。今皆來集，眾雖多，莫能相服。軍無適主，一舉可滅，為攻差易。吾是以喜。語曰：連雞不俱栖，可離而解。曹公得之矣。此伐交者也。","sortOrder":54},
  {"id":"s_work_tdk_9_55","chapterId":"ch_work_tdk_9","text":"格形第十六","sortOrder":55},
  {"id":"s_work_tdk_9_56","chapterId":"ch_work_tdk_9","text":"《孫子》曰：安能動之。又曰：攻其所必趨。何以明之？昔楚子围宋，宋公使如晉告急。晉狐偃曰：楚始得曹而新婚於衛，若伐曹、衛，楚必救之，則齊、宋免矣。果如是計。魏伐趙，趙急請救於齊。齊威王以田忌為將，以孫臏為師，居辎車中為計謀。田忌欲引兵之趙，孫子曰：夫解雜亂紛糾者不控拳，救斗者不摶扞。批亢捣虛，形格势禁，則自為解耳。今梁、趙相攻，輕兵銳卒必竭於外，老弱疲於內。君不若引兵疾走大梁，據其街路，冲其方虛，彼必釋趙而自救。是我一舉解趙之围，而收弊於魏也。田忌從之，魏果去邯鄲。又曹操為東郡太守，治東武陽，軍頓丘。墨山賊於毒等攻東武陽，太祖欲引兵西入山攻毒本屯，諸將皆以為當還自救。曹操曰：昔孫臏救趙而攻魏；耿弇欲走西安，攻臨菑。使賊聞我西而還，則武陽自解。不還，我能破虜家，虜不能拔武陽必矣。乃行。毒聞之，果弃武陽還。曹操要击，大破之。初，關羽围樊、誤陽，曹操以漢帝在許近賊，欲徙都。司馬宣王及莊濟說曹操曰：劉備、孫權，外親內疏，關羽得志，必不願也。可遣人勸躡其後，許割江南以封權，則樊围自解。曹操從之，羽遂見擒。此言攻其所愛則動矣。是以善戰者無知名、無勇功、不爭白刃之前、不備已失之後，此之謂矣。","sortOrder":56},
  {"id":"s_work_tdk_9_57","chapterId":"ch_work_tdk_9","text":"蛇势第十七","sortOrder":57},
  {"id":"s_work_tdk_9_58","chapterId":"ch_work_tdk_9","text":"語曰：投兵散地，則六親不能相保；同舟而濟，胡越何患乎異心？《孫子》曰：善用兵者，譬如率然。何以明之？漢宣帝時，先零為寇，帝命趙充國征之，引兵至先零所在。虜久屯聚，解弛，望見大軍，弃車重，欲渡湟水。道厄狹，充國徐行驅之。或曰：遂利行速。充國曰：此窮寇不可追也，缓之則走不顧，急之則還致死。諸將校皆曰：善。虜果赴水溺死者數百。於是破之。袁尚既败，遂奔遼東，眾有數千。初，遼東太守公孫康恃遠不服。曹公既破鳥丸，或說公遂征之，尚兄弟可擒也。公曰：吾方使康斬送尚、熙首，不煩兵矣。公引兵還，康果斬送尚、熙，傳其首。諸將或問曰：公還而康斬尚、熙，何也？公曰：彼素畏尚、熙，其急之併力，缓之則自相圖，其劫然也。曹公征張繡，荀攸曰：繡與劉表相恃為強，然繡以遊軍仰食於表，表不能供也，其势必離。不如缓軍以待之，可誘而致也。若急之，則必相救。曹操不從，進至穰，與繡戰。表果救之，軍不利矣。故《孫子》曰：善用兵者，譬如率然。率然者，常山之蛇，击其頭則尾至，击其尾則首至，击其中則首尾俱至。或曰：敢問可使如率然乎？孫子曰：可矣。夫吳人之與越人相惡，當其同舟而濟則相救如左右手。是故放馬埋輪，不足恃也；齊勇若一，政之道也。此之謂矣。","sortOrder":58},
  {"id":"s_work_tdk_9_59","chapterId":"ch_work_tdk_9","text":"先勝第十八","sortOrder":59},
  {"id":"s_work_tdk_9_60","chapterId":"ch_work_tdk_9","text":"《孫子》曰：善用兵者，先為不可勝，以待敵之可勝。何以明之？梁州賊王國围陳仓，乃拜皇甫嵩、董卓各率二萬人拒之。卓欲速進赴陳仓，嵩不聽。卓曰：智者不待時，勇者不留决。速戰則城全，不救則城滅。全滅之势，在於此也。嵩曰：不然。百戰百勝，不如不戰而屈人之兵。是以先為不可勝，以待敵之可勝。不可勝在此，可勝在彼。彼守不足，我攻有餘。有餘者動於九天之上，不足者陷於九地之下。今陳仓雖小，城守固備，非九地之陷也；王國雖強，而攻我之所不救，非九天之势也。夫势非九天，攻者受害；陷非九地，守者不拔。國今已陷受害之地，而陳仓保不拔之城，我可不煩兵動眾，而取全勝之功。將何救焉！遂不聽。王國围陳仓，自冬迄春八十餘日，城堅守固，竟不能拔。賊眾疲弊，果自解去。嵩進兵击之，卓曰：不可。兵法窮寇勿迫、歸眾勿追。今吾追國，是迫歸眾、追窮寶也。困獸猶斗、蜂蠆有毒，况大眾乎？嵩曰：不然。吾前不击，避其銳也；今而击之，待其衰也。所击疲師，非歸師也。國眾且走，莫有斗志，以整击亂，非窮寇也。遂獨進兵击之，使卓為後拒，連戰大破，國走而死。卓大慚恨。青州黃巾眾百餘萬八東平。劉岱欲击之。鮑永諫曰：今賊眾百萬，百姓皆震恐，士卒無斗志，不可敵也。觀賊眾群辈相隨，軍無辎重，唯以抄掠為資，今若畜士眾之力，先為固守，彼欲戰不得，攻則不能，其势必離散，然後譔精銳，據其要害，击之可破也。岱不從，果為賊所败。晉代王开攻燕鄴城，慕穀德拒戰，代師败績。又欲攻之，別駕韓谭進曰：昔漢高祖雲：吾寧斗智，不能斗力。是以古人先勝廟堂，然後攻戰。今代不可击者四，燕不宜動者三。代懸軍遠人，利在野戰，不一可击也；深適近畿，頓兵死地，二不可击也；前鋒既败，後軍方固，三不可击也；彼眾我寡，四不可击也。官軍自戰其地，一不宜動；動而不勝，眾心難固，二不宜動；湟池未修，敵來無備，三不宜動，此皆兵機也。深溝高壘，以逸待勞。彼千里饋糧，野無所掠，久則三軍縻費，攻則眾旅多弊，師老衅生，詳而圖之，可以捷也。德曰：韓別駕之言，良、平之策也。此先勝而後戰者也。","sortOrder":60},
  {"id":"s_work_tdk_9_61","chapterId":"ch_work_tdk_9","text":"围師第十九","sortOrder":61},
  {"id":"s_work_tdk_9_62","chapterId":"ch_work_tdk_9","text":"《孫子》曰：围師必闕。何以明之？黃巾賊韓忠宛，朱俊張超围之，結壘起土山以臨城，因鳴鼓攻其西南，賊悉眾赴之，乃掩其東北，乘城而入。忠退保小城，乞降。諸將欲聽之，俊曰：兵有形同而势異者。昔秦項之际，民無定主，故賞附以勸來耳。今海內一統，唯黃巾造寇，納降無以勸善，讨之足以懲惡。今若受之，更开逆意。賊利則進戰、钝則乞降，縱敵長寇，非良計也。因急攻之，不克。俊登土山，顧謂張超曰：吾知之矣。賊今外围周固，連營逼急，乞降不受，欲出不得，所以死戰也。萬人一心，猶不可當，况十萬乎？其害甚矣。不如撤围，併兵入城。忠見解围，势必自出，出則意散，易破之道也。既而解围，忠果出戰遂破忠等。魏太祖围壶關，下令曰：城拔，皆坑之。連月不下，曹仁言於太祖曰：围城必不之門，所以开其生路也。今公許之必死，將人人自為守。且城固而糧多，攻之則士卒傷，守則引日持久。今頓兵堅城之下，以攻必死之虜，非良計也。太祖從之，城降。北围師之道也。","sortOrder":62},
  {"id":"s_work_tdk_9_63","chapterId":"ch_work_tdk_9","text":"变通第二十","sortOrder":63},
  {"id":"s_work_tdk_9_64","chapterId":"ch_work_tdk_9","text":"《孫子》曰：善動敵者形之，敵必從之。何以明之？魏與趙攻韓，齊田忌為將而救之，直走大梁。魏將庞涓去韓而歸，齊軍已過而西矣。孫臏謂田忌曰：被三晉之兵，素悍勇而輕齊，齊號為怯。善用兵者，因其势而利导之。兵法曰：百里而趨利者，蹶上將軍。使齊軍入魏地為十萬竈。明日為五萬竈，明日為二萬竈。涓喜曰：吾固知齊卒怯也，入吾地三日，士卒亡已過半。乃弃其步兵，與輕銳倍日併行遂之。臏度其暮至馬陵，道狹而多险，可伏兵。及斫大树白書之曰：庞涓死此树下。令善射者萬弩，夹道而伏，期曰：見火舉而發。涓夜至斫木下，見白書，及鑽火燭之，讀書。齊軍萬弩俱發，魏軍大亂。涓乃自刭曰：果成竖子之名也。虞詡為武都郡，羌率眾遮詡於陳仓崤穀。詡令吏士各作兩竈，日增位之，羌不敢逼。或問曰：孫子减竈而君增之，兵法日行三十里以戒不虞，今且行二百里，何也？詡曰：虜眾既多，吾徐行則易為所及，疾行則彼不测之。且虜見吾竈多，謂群兵來至。孫子見弱吾示強，势不同也。故曰：料腋在心，察機在目。因形而作，勝於眾善之善者矣。此变通之理也。","sortOrder":64},
  {"id":"s_work_tdk_9_65","chapterId":"ch_work_tdk_9","text":"利害第二十一","sortOrder":65},
  {"id":"s_work_tdk_9_66","chapterId":"ch_work_tdk_9","text":"《孫子》曰：陷之死地而後生，投之亡地而後存。又曰：雜於利而務可伸，雜於害而患可解。何以明之？漢將韓信攻趙，趙盛兵井陉口。信乃引兵未至井陉口三十里止舍，夜半傳發，選輕騎二千人，持一赤幟，從間道萆山而望見趙軍。誡之曰：趙見我走，必空壁逐我。若疾入趙壁，拔趙幟，立漢赤幟。令其裨將傅餐曰：今日破趙會食。諸將皆莫信，佯應曰：诺。信謂軍吏曰：趙已先據便地為壁，且彼未見我大將旗鼓，未肯击前行，恐吾至阻险而還。信乃使萬人行，出倍水陣。趙軍望見，大笑之。平旦，信建大將之旗鼓，鼓行出井陉口。趙开壁击之，大戰良久。於是信與張耳弃旗鼓，走水上，水上軍开壁入之，复疾戰。趙空壁爭漢鼓旗，逐韓信、張耳。韓信、張耳已入水上軍，軍皆殊死戰，不可败。信所出奇兵二十騎，共候趙空壁逐利，則馳入趙壁，皆拔趙幟，立漢赤幟二千。趙軍不得信等，欲還歸壁，壁皆漢亦幟而大驚，以為漢皆已得趙主將矣，遂亂遁走。趙將雖击斬之，不能禁也。於是漢兵來击大破之，斬成安軍泜水上，擒趙王歇。諸將效首虜休，畢贺，因問信曰：兵法右背山陵，前左水泽。今者將軍令臣等反背水陣，曰：破趙會食。時臣等不服，然竟以勝，此何術也？信曰：此在兵法中，顧諸君不察耳。兵法不曰？陷之死地而後生，置之亡地而後存。且信非得素撫循士大夫也，所謂驅市人而戰，其势非置之死地，使人人自為戰。今與之生地皆走，寧尚可得而用之乎？諸將曰：善。非所及也。魏太祖征張繡，一朝引軍退，繡自追之。贾詡曰：不可追也。繡不從，果败而還。詡謂繡曰：促更追之，戰必勝。繡收散卒，赴追太祖，戰果勝。還問詡曰：繡以精兵追運，而公曰必败退；以败卒击勝兵，而公曰必克，皆如公之言。何其反而皆验也？詡曰：此易知耳。軍势百途，事不一也。將軍雖善用兵，非曹公也敵也。魏軍新退，曹公必自斷其後。追兵雖精，將既不敵，彼士亦銳，故知必败。曹公攻將軍無失策，力未盡而還，必國內有故也。既破將軍，必輕軍速進，留諸將斷後。諸將雖勇，亦非將軍敵也，故雖用败兵而勝也。繡乃服其能。此利害之变。故曰：陷之死地而後生，雜於害而患可解。此之謂也。","sortOrder":66},
  {"id":"s_work_tdk_9_67","chapterId":"ch_work_tdk_9","text":"奇正第二十二","sortOrder":67},
  {"id":"s_work_tdk_9_68","chapterId":"ch_work_tdk_9","text":"太公曰：不能分移，不可語奇。《孫子》曰：兵以正合，事以奇勝。何以明之？魏王豹反漢，漢王以韓信為左丞相击魏。魏王盛兵蒲坂，塞臨晉。信乃益為疑兵，陳船欲渡臨晉，而伏兵從夏陽以木罌渡軍袭安邑。魏王豹驚，引兵迎信。信遂虜豹，定魏為河東郡。是知奇正者，兵之要也。經曰：戰勝不過奇正。奇正之变，不可勝窮，如環之無端，孰能窮之。此之謂矣。","sortOrder":68},
  {"id":"s_work_tdk_9_69","chapterId":"ch_work_tdk_9","text":"掩發第二十三","sortOrder":69},
  {"id":"s_work_tdk_9_70","chapterId":"ch_work_tdk_9","text":"《孫子》曰：善戰者其势险，其節短，以利動之，以卒待之。又曰：善動敵者形之，敵必從。何以明其然耶？燕平齊，围即墨城。即墨城中推田单為將以拒燕。田单欲激怒其卒，乃宣言曰：吾雖恐燕將劓所得齊卒，及掘城外墳墓、傷先人，可為寒心。燕將如其言，即墨人皆涕泣，共欲出戰，怒皆十倍。单乃收人金得千溢，令即墨富豪遺燕將書曰：即墨即降，願不虜吾家族。燕將大喜，亦懈。乃收牛得千頭，束苇於尾，燒其端，凿城數十穴，夜縱牛出，以壮士五千人隨其後。牛尾熱而奔燕，燕軍大驚，所隨五千因衔枚击之，燕軍大败，殺其將騎劫，复齊七十餘城。呂蒙西屯陆口。關羽讨樊，留兵備公安、南郡。蒙上疏曰：關羽讨樊而多留備兵，必恐蒙圖其後故也。蒙常有病，乞分眾還建鄴，以治病為名。羽聞之，必撤備兵，盡赴襄陽。大軍浮江，晝夜馳上，袭其空虛，則南郡可取，而羽可擒之。遂稱病篤，權乃露檄召蒙。羽果信之，稍彻兵赴樊。權聞之遂行，先遣蒙在前，伏其精兵於〈舟句〉〈舟鹿〉中，使白衣搖橹，作商贾服，晝夜兼行。至羽所置江邊屯候，盡收縛之，是故羽不聞知。遂到南郡，士仁、糜芳皆降。蒙入據城表，得羽得士家屬，皆撫慰，約令軍中不得幹歷人家，道不拾遺。羽還在道路，數使人與蒙相聞。蒙厚遇其使，使周旋城中，家家致問，或手書示信。羽使人還，私相參訊，鹹知家門無恙，相待過於平時，故羽士卒無斗心。權至獲羽，遂定荆州。此掩發之变。故曰：始如處女，敵人开戶；後如脱兔，敵不及距。此之謂矣。","sortOrder":70},
  {"id":"s_work_tdk_9_71","chapterId":"ch_work_tdk_9","text":"還師第二十四","sortOrder":71},
  {"id":"s_work_tdk_9_72","chapterId":"ch_work_tdk_9","text":"《孫子》曰：興師百萬，日費千金。玉子曰：四人用虛，國家無储。故曰：運糧百里，無一年之食，二百里無二年之食，三百里無三年之食，是謂虛國。國虛則人貧，人貧則上下不相親。上無以树其恩，下無以活其身，則離叛之心生。此為戰勝而自败。故雖破敵於外、立功於內，然而戰勝者以丧禮處之，將軍縞素請罪於君。君曰：兵之所加，無道國也。擒敵致勝，將無咎殃。乃尊其官以奪其势。故曰：高鳥死，良弓藏；敵國滅，謀臣亡。亡者非丧其身，謂沉之於淵。沉之於淵者，謂奪其威、废其權、封之於朝，極人臣之位以顯其功，中州善國以富其心。仁者之眾，可合而不可離，威權可樂而難卒移。是故還軍罢師，存亡之階。故弱之以位，奪之以國。故霸者之佐，其論驳也。人主深晓此道，則能御臣將。人臣深晓此道，則能全功保首。此還師之術也。論曰：奇正之機，五間之要；天地之变，水火之道。如聲不過五聲，五聲之变，不可勝聽；色不過五色，五色之变，不可勝觀，在乎因機而用權矣，不可執一也。故略舉其體之要。","sortOrder":72},
];

